import{m as e}from"./merge-BmcoofH2.js";const t={"unternehmer-firma-firmenbuch":[{type:"text",level:1,de:{q:"Wie heißt das öffentliche Verzeichnis, in das Unternehmen wie GmbH oder OG eingetragen werden?",a:["Firmenbuch"],e:"Das Firmenbuch ist ein öffentliches Verzeichnis beim Landesgericht – jeder kann Einsicht nehmen."},en:{q:"What is the public register called in which companies such as a GmbH or OG are entered?",a:["company register","commercial register","Firmenbuch"],e:"The company register is a public register kept by the regional court – anyone can look at it."},hu:{q:"Hogy hívják azt a nyilvános jegyzéket, amelybe a GmbH-hoz vagy OG-hez hasonló vállalatokat bejegyzik?",a:["cégjegyzék","Firmenbuch"],e:"A cégjegyzék a tartományi bíróságon vezetett nyilvános jegyzék – bárki betekinthet."}},{type:"text",level:2,de:{q:"Wie nennt man den im Firmenbuch eingetragenen Namen, unter dem ein Unternehmer Geschäfte betreibt?",a:["Firma","Firmenname"],e:"Die Firma ist rechtlich der Name des Unternehmers bzw. Unternehmens – nicht das Unternehmen selbst."},en:{q:"What do you call the name entered in the company register under which a business operates?",a:["company name","business name","firm name","Firma"],e:'Legally, the "Firma" is the registered name of the business – not the business itself.'},hu:{q:"Hogyan nevezzük a cégjegyzékbe bejegyzett nevet, amely alatt a vállalkozó üzletel?",a:["cégnév","Firma"],e:"A cégnév (Firma) jogilag a vállalkozó, illetve a vállalat neve – nem maga a vállalat."}},{type:"number",level:3,value:1e6,tol:0,unit:{de:"€",en:"€",hu:"€"},de:{q:"Ab welchem Jahresumsatz in EINEM Jahr muss sich ein Einzelunternehmen ins Firmenbuch eintragen lassen? (Betrag in € als Zahl)",e:"Ab 1.000.000 € Umsatz in einem Jahr (oder zwei Jahre hintereinander je über 700.000 €) besteht Rechnungslegungs- und damit Eintragungspflicht (e. U.)."},en:{q:"From what annual revenue in ONE year must a sole proprietorship be entered in the company register? (Amount in € as a number)",e:"From €1,000,000 revenue in one year (or more than €700,000 in two consecutive years) there is an accounting and therefore registration obligation (e. U.)."},hu:{q:"EGY évben mekkora éves árbevételtől kell egy egyéni vállalkozást a cégjegyzékbe bejegyeztetni? (Összeg €-ban, számmal)",e:"1 000 000 € éves árbevételtől (vagy két egymást követő évben 700 000 € felett) könyvvezetési és így bejegyzési kötelezettség áll fenn (e. U.)."}}],"rechtsformen-unternehmen":[{type:"text",level:1,de:{q:"Bei welcher Rechtsform sind die Anteile Aktien? (Abkürzung)",a:["AG","Aktiengesellschaft"],e:"Bei der Aktiengesellschaft (AG) ist das Grundkapital in Aktien aufgeteilt."},en:{q:'In which legal form are the shares called "Aktien" (stocks)? (Abbreviation)',a:["AG","stock corporation","public limited company","Aktiengesellschaft"],e:"In a stock corporation (AG) the share capital is divided into shares."},hu:{q:"Melyik jogi formánál részvények a részesedések? (Rövidítés)",a:["AG","részvénytársaság","rt"],e:"A részvénytársaságnál (AG) az alaptőke részvényekre oszlik."}},{type:"number",level:2,value:1e4,tol:0,unit:{de:"€",en:"€",hu:"€"},de:{q:"Wie hoch ist das Mindeststammkapital einer GmbH?",e:"Eine GmbH braucht mindestens 10.000 € Stammkapital. Die Gesellschafter haften nur bis zu ihrer Stammeinlage."},en:{q:"What is the minimum share capital of a GmbH (private limited company)?",e:"A GmbH needs a share capital of at least €10,000. The partners are only liable up to their contribution."},hu:{q:"Mekkora egy GmbH (kft.) minimális törzstőkéje?",e:"Egy GmbH-nak legalább 10 000 € törzstőke kell. A tagok csak a törzsbetétjük erejéig felelnek."}},{type:"mc",level:3,correctIndex:1,de:{q:"Welche drei Organe hat eine AG zwingend?",o:["Geschäftsführer, Generalversammlung, Aufsichtsrat","Vorstand, Aufsichtsrat, Hauptversammlung","Vorstand, Hauptversammlung, Betriebsrat","Komplementär, Kommanditist, Aufsichtsrat"],e:"Die AG hat Vorstand (leitet), Aufsichtsrat (kontrolliert) und Hauptversammlung (Aktionäre). Geschäftsführer und Generalversammlung gehören zur GmbH."},en:{q:"Which three bodies must an AG (stock corporation) have?",o:["Managing director, general meeting, supervisory board","Management board, supervisory board, general meeting","Management board, general meeting, works council","General partner, limited partner, supervisory board"],e:'An AG has a management board (runs it), a supervisory board (controls it) and the general meeting (shareholders). Managing director and "Generalversammlung" belong to the GmbH.'},hu:{q:"Melyik három szerv kötelező egy AG-nél (részvénytársaságnál)?",o:["Ügyvezető, taggyűlés, felügyelőbizottság","Igazgatóság, felügyelőbizottság, közgyűlés","Igazgatóság, közgyűlés, üzemi tanács","Beltag, kültag, felügyelőbizottság"],e:"Az AG szervei az igazgatóság (vezet), a felügyelőbizottság (ellenőriz) és a közgyűlés (részvényesek). Az ügyvezető és a taggyűlés a GmbH-hoz tartozik."}}],vollmachten:[{type:"text",level:1,de:{q:"Wie heißt die umfassende Vollmacht, die ins Firmenbuch eingetragen wird?",a:["Prokura"],e:"Die Prokura ist die umfassendste Vollmacht im Unternehmensrecht und wird ins Firmenbuch eingetragen."},en:{q:"What is the comprehensive power of attorney called that is entered in the company register?",a:["Prokura","power of procuration","procuration"],e:"Prokura is the most comprehensive power of attorney in company law and is entered in the company register."},hu:{q:"Hogy hívják azt az átfogó meghatalmazást, amelyet a cégjegyzékbe bejegyeznek?",a:["prokúra","cégvezetési meghatalmazás"],e:"A prokúra a vállalati jog legátfogóbb meghatalmazása, és a cégjegyzékbe bejegyzik."}},{type:"text",level:2,de:{q:"Mit welchem Zusatz unterschreibt ein Prokurist? (Abkürzung)",a:["ppa","ppa.","per procura"],e:"Prokuristen unterschreiben mit „ppa.“ (per procura) vor ihrem Namen."},en:{q:"Which addition does a holder of Prokura use when signing? (Abbreviation)",a:["ppa","ppa.","pp","per procura"],e:'Holders of Prokura sign with "ppa." (per procura) before their name.'},hu:{q:"Milyen rövidítéssel ír alá a prokurista?",a:["ppa","ppa.","per procura"],e:"A prokuristák a nevük előtt „ppa.” (per procura) rövidítéssel írnak alá."}},{type:"mc",level:3,correctIndex:2,de:{q:"Was darf ein Prokurist ohne besondere Befugnis NICHT?",o:["Personal einstellen und entlassen","Kredite bei der Bank aufnehmen","Grundstücke verkaufen oder belasten","Waren ein- und verkaufen"],e:"Grundstücke verkaufen oder belasten darf ein Prokurist nur mit besonderer Befugnis. Ebenso wenig darf er z. B. das Unternehmen auflösen oder die Firma ändern."},en:{q:"What may a holder of Prokura NOT do without special authorisation?",o:["Hire and fire staff","Take out bank loans","Sell or mortgage land","Buy and sell goods"],e:"Selling or mortgaging land requires special authorisation. A holder of Prokura also may not, for example, dissolve the company or change its name."},hu:{q:"Mit NEM tehet meg a prokurista külön felhatalmazás nélkül?",o:["Dolgozót felvenni és elbocsátani","Banki hitelt felvenni","Ingatlant eladni vagy megterhelni","Árut beszerezni és eladni"],e:"Ingatlan eladásához vagy megterheléséhez külön felhatalmazás kell. A prokurista azt sem teheti meg pl., hogy megszünteti a vállalatot vagy megváltoztatja a cégnevet."}}],beschaeftigungsverhaeltnisse:[{type:"text",level:1,de:{q:"Wie nennt man eine Beschäftigung unter der Geringfügigkeitsgrenze, bei der man nur unfallversichert ist?",a:["geringfügige Beschäftigung","geringfügig beschäftigt","geringfügiges Dienstverhältnis"],e:"Bei geringfügiger Beschäftigung liegt das Entgelt unter der Geringfügigkeitsgrenze – man ist nur unfallversichert."},en:{q:"What do you call employment below the marginal earnings threshold where you are only insured against accidents?",a:["marginal employment","mini job","minijob"],e:"In marginal employment pay is below the threshold – you are only covered by accident insurance."},hu:{q:"Hogyan nevezzük az alkalmazást a csekély keresetű határ alatt, amelynél csak balesetbiztosítás van?",a:["csekély mértékű foglalkoztatás","alkalmi foglalkoztatás","kisjövedelmű foglalkoztatás"],e:"Csekély mértékű foglalkoztatásnál a bér a határ alatt van – csak balesetbiztosítás jár."}},{type:"mc",level:2,correctIndex:0,de:{q:"Freier Dienstvertrag: Wer meldet die Sozialversicherung an und wer zahlt die Einkommensteuer?",o:["Der Auftraggeber meldet die SV an, die Steuer zahlt der freie Dienstnehmer selbst","Beides erledigt der Auftraggeber für den freien Dienstnehmer","Beides erledigt der freie Dienstnehmer selbst","Der freie Dienstnehmer meldet die SV an, die Steuer zahlt der Auftraggeber"],e:"Beim freien Dienstvertrag meldet der Auftraggeber zur Sozialversicherung an, die Einkommensteuer muss der freie Dienstnehmer aber selbst abführen."},en:{q:"Freelance service contract: who registers for social insurance and who pays the income tax?",o:["The client registers for social insurance, the freelancer pays the tax","The client does both for the freelancer","The freelancer does both","The freelancer registers for social insurance, the client pays the tax"],e:"In a freelance service contract the client registers the person for social insurance, but the freelancer has to pay the income tax themselves."},hu:{q:"Szabad szolgáltatási szerződés: ki jelenti be a társadalombiztosítást, és ki fizeti a jövedelemadót?",o:["A megbízó jelenti be a tb-t, az adót a szabad munkavállaló maga fizeti","Mindkettőt a megbízó intézi a szabad munkavállaló helyett","Mindkettőt a szabad munkavállaló maga intézi","A tb-t a szabad munkavállaló jelenti be, az adót a megbízó fizeti"],e:"Szabad szolgáltatási szerződésnél a megbízó jelent be a társadalombiztosításhoz, a jövedelemadót azonban a szabad munkavállalónak magának kell befizetnie."}},{type:"number",level:3,value:1500,tol:.01,unit:{de:"€",en:"€",hu:"€"},de:{q:"Eine Vollzeitkraft (40 Std./Woche) verdient 2.400 € brutto im Monat. Wie hoch ist das anteilige Bruttogehalt einer Teilzeitkraft mit 25 Std./Woche im selben Job?",e:"Anteil = 25 ÷ 40 = 62,5 %. Gehalt = 2.400 · 0,625 = 1.500 € brutto."},en:{q:"A full-time employee (40 h/week) earns €2,400 gross per month. What is the proportional gross salary of a part-time employee with 25 h/week in the same job?",e:"Share = 25 ÷ 40 = 62.5%. Salary = 2,400 · 0.625 = €1,500 gross."},hu:{q:"Egy teljes munkaidős munkavállaló (heti 40 óra) havi 2400 € bruttót keres. Mennyi az arányos bruttó fizetése egy heti 25 órás részmunkaidősnek ugyanebben a munkakörben?",e:"Arány = 25 ÷ 40 = 62,5%. Fizetés = 2400 · 0,625 = 1500 € bruttó."}}]},a={"kaufvertraege-aussenhandel":[{type:"text",level:1,de:{q:"Wie heißen die international einheitlichen Lieferklauseln der Internationalen Handelskammer (ICC)?",a:["Incoterms","Incoterm"],e:"Die Incoterms regeln, wer Kosten und Risiko des Transports trägt – weltweit einheitlich."},en:{q:"What are the internationally standardised delivery terms of the International Chamber of Commerce (ICC) called?",a:["Incoterms","Incoterm"],e:"The Incoterms regulate who bears transport costs and risk – the same all over the world."},hu:{q:"Hogy hívják a Nemzetközi Kereskedelmi Kamara (ICC) nemzetközileg egységes szállítási záradékait?",a:["Incoterms","Incoterm"],e:"Az Incoterms szabályozza, ki viseli a szállítás költségét és kockázatát – világszerte egységesen."}},{type:"text",level:2,de:{q:"Bei welcher Incoterms-Klausel trägt der Käufer alle Kosten und Risiken schon ab dem Werk des Verkäufers? (Kürzel mit 3 Buchstaben)",a:["EXW","Ex Works","Ab Werk"],e:"EXW (Ab Werk): Der Verkäufer stellt die Ware nur bereit – alles Weitere zahlt und riskiert der Käufer."},en:{q:"Under which Incoterm does the buyer bear all costs and risks from the seller's works onwards? (3-letter code)",a:["EXW","Ex Works"],e:"EXW (Ex Works): the seller only makes the goods available – the buyer pays for and bears the risk of everything else."},hu:{q:"Melyik Incoterms-záradéknál viseli a vevő minden költséget és kockázatot már az eladó gyárától? (3 betűs rövidítés)",a:["EXW","Ex Works"],e:"EXW (gyárból): az eladó csak rendelkezésre bocsátja az árut – minden mást a vevő fizet és kockáztat."}},{type:"mc",level:3,correctIndex:2,de:{q:"Loopy verkauft Pralinen nach Japan mit der Klausel DDP Tokio. Was bedeutet das für sie als Verkäuferin?",o:["Sie trägt Transport und Risiko bis Tokio, den Einfuhrzoll zahlt aber der Käufer","Sie trägt Kosten und Risiko nur bis zum Hafen in Europa","Sie trägt alle Kosten und Risiken bis Tokio, auch die Einfuhrabgaben","Sie muss die Ware nur im Werk bereitstellen"],e:"DDP (Delivered Duty Paid) ist das Gegenteil von EXW: Der Verkäufer trägt alles bis zum Bestimmungsort, sogar die Einfuhrabgaben."},en:{q:"Loopy sells chocolates to Japan under the term DDP Tokyo. What does this mean for her as the seller?",o:["She bears transport and risk up to Tokyo, but the buyer pays the import duty","She bears costs and risk only up to the port in Europe","She bears all costs and risks up to Tokyo, including import duties","She only has to make the goods available at her works"],e:"DDP (Delivered Duty Paid) is the opposite of EXW: the seller bears everything up to the destination, even the import duties."},hu:{q:"Loopy DDP Tokió záradékkal ad el bonbont Japánba. Mit jelent ez számára eladóként?",o:["Tokióig viseli a szállítást és a kockázatot, de a behozatali vámot a vevő fizeti","Csak az európai kikötőig viseli a költséget és a kockázatot","Tokióig minden költséget és kockázatot visel, a behozatali terhekkel együtt","Csak a gyárában kell rendelkezésre bocsátania az árut"],e:"A DDP (vámfizetéssel leszállítva) az EXW ellentéte: az eladó a rendeltetési helyig mindent visel, még a behozatali terheket is."}}],"grundlagen-leistungserstellung-2jg":[{type:"text",level:1,de:{q:"Wie nennt man das Verhältnis von mengenmäßigem Output zu mengenmäßigem Input?",a:["Produktivität"],e:"Produktivität = mengenmäßiger Output ÷ mengenmäßiger Input, z. B. Stück pro Arbeitsstunde."},en:{q:"What do you call the ratio of output quantity to input quantity?",a:["productivity"],e:"Productivity = output quantity ÷ input quantity, e.g. pieces per working hour."},hu:{q:"Hogyan nevezzük a mennyiségi output és a mennyiségi input arányát?",a:["termelékenység","produktivitás"],e:"Termelékenység = mennyiségi output ÷ mennyiségi input, pl. darab munkaóránként."}},{type:"number",level:2,value:85,tol:.01,unit:{de:"%",en:"%",hu:"%"},de:{q:"Von 80 Aufträgen wurden 68 pünktlich geliefert. Wie hoch ist die Termintreue in %?",e:"Termintreue = pünktliche Aufträge ÷ alle Aufträge · 100 = 68 ÷ 80 · 100 = 85 %."},en:{q:"Of 80 orders, 68 were delivered on time. What is the delivery reliability in %?",e:"Delivery reliability = on-time orders ÷ all orders · 100 = 68 ÷ 80 · 100 = 85%."},hu:{q:"80 megrendelésből 68-at szállítottak ki időben. Hány százalék a határidő-pontosság?",e:"Határidő-pontosság = időben teljesített ÷ összes megrendelés · 100 = 68 ÷ 80 · 100 = 85%."}},{type:"number",level:3,value:15,tol:.01,unit:{de:"%",en:"%",hu:"%"},de:{q:"Loopy erzielt Erlöse von 312.000 € bei Kosten von 288.000 €. Das eingesetzte Kapital beträgt 160.000 €. Berechne die Rentabilität in %.",e:"Gewinn = 312.000 − 288.000 = 24.000 €. Rentabilität = 24.000 ÷ 160.000 · 100 = 15 %."},en:{q:"Loopy earns revenue of €312,000 with costs of €288,000. The capital employed is €160,000. Calculate the profitability in %.",e:"Profit = 312,000 − 288,000 = €24,000. Profitability = 24,000 ÷ 160,000 · 100 = 15%."},hu:{q:"Loopy árbevétele 312 000 €, költségei 288 000 €. A befektetett tőke 160 000 €. Számítsd ki a jövedelmezőséget %-ban.",e:"Nyereség = 312 000 − 288 000 = 24 000 €. Jövedelmezőség = 24 000 ÷ 160 000 · 100 = 15%."}}],"kunde-im-mittelpunkt":[{type:"text",level:1,de:{q:"Wie nennt man den gesamten „Weg“ eines Kunden mit allen Kontaktpunkten vor, während und nach dem Kauf? (englischer Begriff)",a:["Customer Journey","Kundenreise"],e:"Die Customer Journey umfasst alle Touchpoints, an denen ein Kunde mit dem Unternehmen in Berührung kommt."},en:{q:`What do you call a customer's whole "path" with all touchpoints before, during and after a purchase?`,a:["customer journey"],e:"The customer journey includes all touchpoints at which a customer comes into contact with the company."},hu:{q:"Hogyan nevezzük a vásárló teljes „útját” az összes kapcsolódási ponttal a vásárlás előtt, alatt és után?",a:["vásárlói út","customer journey","ügyfélút"],e:"A vásárlói út minden olyan kapcsolódási pontot magában foglal, ahol a vásárló kapcsolatba kerül a vállalattal."}},{type:"text",level:2,de:{q:"Wie heißen die 4 Ps (Product, Price, Place, Promotion) zusammen?",a:["Marketingmix","Marketing-Mix","Marketing Mix"],e:"Die 4 Ps bilden zusammen den Marketingmix – sie müssen zueinander passen."},en:{q:"What are the 4 Ps (product, price, place, promotion) called together?",a:["marketing mix","marketing-mix"],e:"Together the 4 Ps form the marketing mix – they have to fit together."},hu:{q:"Hogyan nevezzük együtt a 4 P-t (termék, ár, értékesítés, kommunikáció)?",a:["marketingmix","marketing mix","marketing-mix"],e:"A 4 P együtt alkotja a marketingmixet – illeszkedniük kell egymáshoz."}},{type:"mc",level:3,correctIndex:0,de:{q:"Loopy entwickelt EIN Angebot (vegane Pralinen) und richtet ihr ganzes Marketing nur auf die Zielgruppe der Veganer:innen aus. Welche Marktbearbeitung ist das?",o:["Konzentrierte Marktbearbeitung","Differenzierte Marktbearbeitung","Undifferenzierte Marktbearbeitung","Massenmarketing"],e:"Konzentriert = ein Segment mit einem passenden Angebot. Differenziert = mehrere Segmente mit jeweils eigenem Angebot. Undifferenziert = ein Angebot für alle."},en:{q:"Loopy develops ONE offer (vegan chocolates) and aims all her marketing only at vegans. Which market approach is this?",o:["Concentrated marketing","Differentiated marketing","Undifferentiated marketing","Mass marketing"],e:"Concentrated = one segment with a suitable offer. Differentiated = several segments, each with its own offer. Undifferentiated = one offer for everyone."},hu:{q:"Loopy EGY ajánlatot fejleszt (vegán bonbon), és egész marketingjét csak a vegánokra irányítja. Milyen piacfeldolgozásról van szó?",o:["Koncentrált piacfeldolgozás","Differenciált piacfeldolgozás","Differenciálatlan piacfeldolgozás","Tömegmarketing"],e:"Koncentrált = egy szegmens egy hozzá illő ajánlattal. Differenciált = több szegmens, mindegyik saját ajánlattal. Differenciálatlan = egy ajánlat mindenkinek."}}],marktforschung:[{type:"text",level:1,de:{q:"Wie heißt Marktforschung, bei der bereits vorhandene Daten ausgewertet werden?",a:["Sekundärforschung","Sekundärmarktforschung","Sekundärerhebung","Desk Research"],e:"Sekundärforschung nutzt vorhandene Daten (z. B. Statistiken), Primärforschung erhebt neue Daten."},en:{q:"What do you call market research that analyses data that already exists?",a:["secondary research","secondary market research","desk research"],e:"Secondary research uses existing data (e.g. statistics); primary research collects new data."},hu:{q:"Hogyan nevezzük azt a piackutatást, amely már meglévő adatokat értékel ki?",a:["szekunder kutatás","másodlagos kutatás","szekunder piackutatás","desk research"],e:"A szekunder kutatás meglévő adatokat használ (pl. statisztikák), a primer kutatás új adatokat gyűjt."}},{type:"text",level:2,de:{q:"Wie nennt man eine gleichbleibende Gruppe von Personen, die über längere Zeit regelmäßig zum selben Thema befragt wird?",a:["Panel","Panelerhebung","Panelbefragung"],e:"Ein Panel zeigt, wie sich Meinungen oder Verhalten derselben Personen über die Zeit verändern."},en:{q:"What do you call a fixed group of people who are asked about the same topic regularly over a long period?",a:["panel","panel survey"],e:"A panel shows how opinions or behaviour of the same people change over time."},hu:{q:"Hogyan nevezzük az állandó személyekből álló csoportot, amelyet hosszabb ideig rendszeresen ugyanarról a témáról kérdeznek?",a:["panel","panelvizsgálat","panel felmérés"],e:"A panel megmutatja, hogyan változik ugyanazon személyek véleménye vagy viselkedése az idő során."}},{type:"mc",level:3,correctIndex:1,de:{q:"Loopy testet eine neue Verpackung zuerst in 3 ausgewählten Filialen unter echten Verkaufsbedingungen, bevor sie sie überall einführt. Welche Methode ist das?",o:["Produkttest","Storetest","Panelerhebung","Vollerhebung"],e:"Beim Storetest wird ein Produkt in ausgewählten Geschäften unter echten Bedingungen getestet. Ein Produkttest prüft das Produkt selbst (z. B. Geschmack), meist mit Testpersonen."},en:{q:"Loopy first tests a new packaging in 3 selected branches under real sales conditions before introducing it everywhere. Which method is this?",o:["Product test","Store test","Panel survey","Full survey"],e:"In a store test a product is tested in selected shops under real conditions. A product test checks the product itself (e.g. taste), usually with test persons."},hu:{q:"Loopy egy új csomagolást először 3 kiválasztott fióküzletben, valós eladási körülmények között tesztel, mielőtt mindenhol bevezetné. Milyen módszer ez?",o:["Termékteszt","Üzletteszt (storetest)","Panelvizsgálat","Teljes körű adatfelvétel"],e:"Üzlettesztnél egy terméket kiválasztott üzletekben, valós körülmények között tesztelnek. A termékteszt magát a terméket vizsgálja (pl. ízt), többnyire tesztszemélyekkel."}}]},n={"instrumente-marketings":[{type:"text",level:1,de:{q:"Welche Phase folgt im Produktlebenszyklus auf die Reifephase?",a:["Sättigung","Sättigungsphase"],e:"Einführung → Wachstum → Reife → Sättigung → Rückgang (evtl. Relaunch)."},en:{q:"Which phase follows the maturity phase in the product life cycle?",a:["saturation","saturation phase"],e:"Introduction → growth → maturity → saturation → decline (possibly a relaunch)."},hu:{q:"Melyik szakasz követi az érettségi szakaszt a termékéletciklusban?",a:["telítettség","telítődés","telítettségi szakasz"],e:"Bevezetés → növekedés → érettség → telítettség → hanyatlás (esetleg újraindítás)."}},{type:"text",level:2,de:{q:"Wie heißen im BCG-Portfolio Produkte mit hohem Marktanteil in einem kaum noch wachsenden Markt?",a:["Cashcows","Cashcow","Cash Cows","Cash Cow","Melkkühe"],e:"Cashcows bringen viel Geld bei wenig Investition – sie werden „gemolken“."},en:{q:"In the BCG portfolio, what are products with a high market share in a market that is hardly growing called?",a:["cash cows","cash cow","cashcows"],e:'Cash cows bring in a lot of money with little investment – they are "milked".'},hu:{q:"Hogy hívják a BCG-portfólióban a magas piaci részesedésű termékeket egy alig növekvő piacon?",a:["fejőstehenek","fejőstehén","cash cow"],e:"A fejőstehenek kevés befektetéssel sok pénzt hoznak – „fejik” őket."}},{type:"number",level:3,value:25,tol:.01,unit:{de:"€",en:"€",hu:"€"},de:{q:"Eine Anzeige kostet 4.500 € und erreicht 180.000 Leser:innen. Berechne den Tausenderkontaktpreis (TKP).",e:"TKP = Kosten · 1.000 ÷ Reichweite = 4.500 · 1.000 ÷ 180.000 = 25 € pro 1.000 Kontakte."},en:{q:"An advert costs €4,500 and reaches 180,000 readers. Calculate the cost per thousand contacts (CPM).",e:"CPM = cost · 1,000 ÷ reach = 4,500 · 1,000 ÷ 180,000 = €25 per 1,000 contacts."},hu:{q:"Egy hirdetés 4500 €-ba kerül, és 180 000 olvasót ér el. Számítsd ki az ezer kontaktusra jutó költséget (TKP).",e:"TKP = költség · 1000 ÷ elérés = 4500 · 1000 ÷ 180 000 = 25 € 1000 kontaktusonként."}}],"material-warenwirtschaft":[{type:"text",level:1,de:{q:"Wie nennt man Waren, die ein Handelsbetrieb einkauft und unverändert weiterverkauft?",a:["Handelswaren","Handelsware"],e:"Handelswaren werden ohne Verarbeitung weiterverkauft – das ist Warenwirtschaft (im Gegensatz zur Materialwirtschaft der Produktion)."},en:{q:"What do you call goods that a trading business buys and resells unchanged?",a:["merchandise","goods for resale","trade goods"],e:"Goods for resale are sold on without processing – this is merchandise management (as opposed to materials management in production)."},hu:{q:"Hogyan nevezzük azokat az árukat, amelyeket egy kereskedelmi vállalat megvásárol és változatlanul továbbad?",a:["kereskedelmi áru","kereskedelmi áruk"],e:"A kereskedelmi árukat feldolgozás nélkül adják tovább – ez az árugazdálkodás (szemben a termelés anyaggazdálkodásával)."}},{type:"text",level:2,de:{q:"Wie heißen Stoffe, die als Hauptbestandteil in ein Produkt eingehen (z. B. Kakao in Pralinen)?",a:["Rohstoffe","Rohstoff"],e:"Rohstoffe = Hauptbestandteil, Hilfsstoffe = Nebenbestandteil (z. B. Kleber), Betriebsstoffe gehen nicht ins Produkt ein (z. B. Strom)."},en:{q:"What do you call materials that become the main component of a product (e.g. cocoa in chocolates)?",a:["raw materials","raw material"],e:"Raw materials = main component, auxiliary materials = minor component (e.g. glue), operating supplies do not become part of the product (e.g. electricity)."},hu:{q:"Hogyan nevezzük azokat az anyagokat, amelyek a termék fő alkotórészévé válnak (pl. kakaó a bonbonban)?",a:["nyersanyagok","nyersanyag","alapanyag","alapanyagok"],e:"Nyersanyag = fő alkotórész, segédanyag = mellékes alkotórész (pl. ragasztó), az üzemanyagok nem kerülnek a termékbe (pl. áram)."}},{type:"mc",level:3,correctIndex:2,de:{q:"Der Strom für die Maschinen in Loopys Pralinenküche ist ein …",o:["Rohstoff","Hilfsstoff","Betriebsstoff","Handelsware"],e:"Betriebsstoffe werden bei der Produktion verbraucht, gehen aber nicht ins Produkt ein – z. B. Strom, Schmiermittel."},en:{q:"The electricity for the machines in Loopy's chocolate kitchen is …",o:["a raw material","an auxiliary material","an operating supply","goods for resale"],e:"Operating supplies are used up in production but do not become part of the product – e.g. electricity, lubricants."},hu:{q:"Az áram Loopy bonbonkonyhájának gépeihez …",o:["nyersanyag","segédanyag","üzemi anyag","kereskedelmi áru"],e:"Az üzemi anyagok a termelés során elhasználódnak, de nem kerülnek a termékbe – pl. áram, kenőanyag."}}],beschaffungsmarketing:[{type:"text",level:1,de:{q:"Wie heißt die Beschaffungsform, bei der Material genau dann geliefert wird, wenn es in der Produktion gebraucht wird? (englischer Begriff)",a:["Just-in-time","Just in time","JIT"],e:"Just-in-time spart Lagerkosten, braucht aber sehr zuverlässige Lieferanten."},en:{q:"What is the procurement method called where material is delivered exactly when production needs it?",a:["just-in-time","just in time","JIT"],e:"Just-in-time saves storage costs but needs very reliable suppliers."},hu:{q:"Hogy hívják azt a beszerzési formát, amelynél az anyagot pontosan akkor szállítják, amikor a termelésnek szüksége van rá?",a:["just-in-time","just in time","JIT"],e:"A just-in-time raktározási költséget takarít meg, de nagyon megbízható beszállítókat igényel."}},{type:"number",level:2,value:360,tol:0,unit:{de:"kg",en:"kg",hu:"kg"},de:{q:"Loopy verbraucht täglich 40 kg Kakao. Die Beschaffungszeit beträgt 6 Tage, der Sicherheitsbestand 120 kg. Wie hoch ist der Meldebestand?",e:"Meldebestand = Ø-Verbrauch · Beschaffungszeit + Sicherheitsbestand = 40 · 6 + 120 = 360 kg."},en:{q:"Loopy uses 40 kg of cocoa per day. The delivery time is 6 days and the safety stock 120 kg. What is the reorder level?",e:"Reorder level = average usage · delivery time + safety stock = 40 · 6 + 120 = 360 kg."},hu:{q:"Loopy naponta 40 kg kakaót használ fel. A beszerzési idő 6 nap, a biztonsági készlet 120 kg. Mekkora a rendelési pont (jelzőkészlet)?",e:"Rendelési pont = átlagos felhasználás · beszerzési idő + biztonsági készlet = 40 · 6 + 120 = 360 kg."}},{type:"number",level:3,value:1e3,tol:.5,unit:{de:"Stück",en:"pcs",hu:"db"},de:{q:"Jahresbedarf 8.000 Stück, Bestellkosten 50 € pro Bestellung, Einstandspreis 4 € pro Stück, Lagerhaltungskostensatz 20 %. Berechne die optimale Bestellmenge.",e:"Optimale Bestellmenge = √(200 · 8.000 · 50 ÷ (4 · 20)) = √(80.000.000 ÷ 80) = √1.000.000 = 1.000 Stück."},en:{q:"Annual demand 8,000 pieces, ordering costs €50 per order, purchase price €4 per piece, storage cost rate 20%. Calculate the optimal order quantity.",e:"Optimal order quantity = √(200 · 8,000 · 50 ÷ (4 · 20)) = √(80,000,000 ÷ 80) = √1,000,000 = 1,000 pieces."},hu:{q:"Éves szükséglet 8000 darab, rendelési költség 50 € rendelésenként, beszerzési ár 4 € darabonként, raktározási költséghányad 20%. Számítsd ki az optimális rendelési mennyiséget.",e:"Optimális rendelési mennyiség = √(200 · 8000 · 50 ÷ (4 · 20)) = √(80 000 000 ÷ 80) = √1 000 000 = 1000 darab."}}],"lager-transport-entsorgung":[{type:"text",level:1,de:{q:"Wie nennt man die Lagerhaltung, bei der Waren dort abgelegt werden, wo gerade Platz frei ist (z. B. bei Amazon)?",a:["chaotische Lagerhaltung","chaotisches Lager","Freiplatzsystem","chaotische Lagerung"],e:"Beim Freiplatzsystem (chaotische Lagerhaltung) wird der Platz optimal genutzt – man braucht aber eine EDV, die weiß, wo was liegt."},en:{q:"What is the kind of storage called where goods are put wherever space is free (e.g. at Amazon)?",a:["chaotic storage","random storage","free location storage"],e:"Chaotic storage uses space optimally – but you need IT that knows where everything is."},hu:{q:"Hogyan nevezzük azt a raktározást, amelynél az árut oda teszik, ahol éppen szabad hely van (pl. az Amazonnál)?",a:["kaotikus raktározás","kaotikus raktár","szabad helyes rendszer"],e:"A kaotikus raktározás optimálisan használja ki a helyet – de kell hozzá informatikai rendszer, amely tudja, mi hol van."}},{type:"number",level:2,value:16e3,tol:0,unit:{de:"€",en:"€",hu:"€"},de:{q:"Der Lagerbestand betrug am 1. Jänner 14.000 € und am 31. Dezember 18.000 €. Wie hoch ist der durchschnittliche Lagerbestand?",e:"Ø Lagerbestand = (Anfangsbestand + Endbestand) ÷ 2 = (14.000 + 18.000) ÷ 2 = 16.000 €."},en:{q:"Stock was €14,000 on 1 January and €18,000 on 31 December. What is the average stock?",e:"Average stock = (opening stock + closing stock) ÷ 2 = (14,000 + 18,000) ÷ 2 = €16,000."},hu:{q:"A raktárkészlet január 1-jén 14 000 €, december 31-én 18 000 € volt. Mekkora az átlagos raktárkészlet?",e:"Ø raktárkészlet = (nyitókészlet + zárókészlet) ÷ 2 = (14 000 + 18 000) ÷ 2 = 16 000 €."}},{type:"number",level:3,value:60.83,tol:.1,unit:{de:"Tage",en:"days",hu:"nap"},de:{q:"Wareneinsatz 96.000 €, Anfangsbestand 14.000 €, Endbestand 18.000 €. Berechne die durchschnittliche Lagerdauer in Tagen (Jahr = 365 Tage, auf 2 Kommastellen).",e:"Ø Lager = 16.000 €. Umschlagshäufigkeit = 96.000 ÷ 16.000 = 6. Lagerdauer = 365 ÷ 6 = 60,83 Tage."},en:{q:"Cost of goods used €96,000, opening stock €14,000, closing stock €18,000. Calculate the average storage period in days (year = 365 days, 2 decimal places).",e:"Average stock = €16,000. Turnover rate = 96,000 ÷ 16,000 = 6. Storage period = 365 ÷ 6 = 60.83 days."},hu:{q:"Áruráfordítás 96 000 €, nyitókészlet 14 000 €, zárókészlet 18 000 €. Számítsd ki az átlagos raktározási időt napokban (év = 365 nap, 2 tizedesjegyre).",e:"Ø készlet = 16 000 €. Forgási sebesség = 96 000 ÷ 16 000 = 6. Raktározási idő = 365 ÷ 6 = 60,83 nap."}}]},r={"supply-chain-management":[{type:"text",level:1,de:{q:"Wie nennt man alle Unternehmen vom Rohstoff bis zum Endverbraucher zusammen? (englischer Begriff)",a:["Supply Chain","Lieferkette","Wertschöpfungskette"],e:"Die Supply Chain (Lieferkette) umfasst alle Unternehmen vom Rohstoff bis zum Endverbraucher."},en:{q:"What do you call all the companies from raw material to end consumer together?",a:["supply chain"],e:"The supply chain includes all companies from raw material to end consumer."},hu:{q:"Hogyan nevezzük együtt az összes vállalatot a nyersanyagtól a végső fogyasztóig?",a:["ellátási lánc","supply chain","beszállítói lánc"],e:"Az ellátási lánc a nyersanyagtól a végső fogyasztóig minden vállalatot magában foglal."}},{type:"text",level:2,de:{q:"Wie nennt man die Fähigkeit einer Lieferkette, Störungen (z. B. eine Pandemie) gut zu überstehen?",a:["Resilienz","Widerstandsfähigkeit"],e:"Resilienz erreicht man z. B. durch Multi-Sourcing, Pufferbestände und Kooperation."},en:{q:"What do you call a supply chain's ability to cope well with disruptions (e.g. a pandemic)?",a:["resilience"],e:"Resilience is achieved e.g. through multi-sourcing, buffer stocks and cooperation."},hu:{q:"Hogyan nevezzük az ellátási lánc azon képességét, hogy jól átvészelje a zavarokat (pl. egy járványt)?",a:["reziliencia","ellenálló képesség","ellenállóképesség"],e:"A reziliencia pl. több beszállítóval, puffer­készletekkel és együttműködéssel érhető el."}},{type:"mc",level:3,correctIndex:0,de:{q:"Loopy bezieht Kakao jetzt von drei Lieferanten aus verschiedenen Ländern statt nur von einem. Was gewinnt sie vor allem – und was ist der Nachteil?",o:["Mehr Resilienz – aber weniger Effizienz","Mehr Effizienz – aber weniger Sicherheit","Niedrigere Kosten – aber mehr Abhängigkeit","Keinen Vorteil – nur mehr Risiko und Kosten"],e:"Multi-Sourcing macht die Kette widerstandsfähiger, kostet aber Effizienz (kleinere Mengen, mehr Abstimmung) – der Resilienz-Effizienz-Konflikt."},en:{q:"Loopy now buys cocoa from three suppliers in different countries instead of just one. What does she mainly gain – and what is the downside?",o:["More resilience – but less efficiency","More efficiency – but less security","Lower costs – but more dependence","No advantage – only more risk and cost"],e:"Multi-sourcing makes the chain more resilient but costs efficiency (smaller quantities, more coordination) – the resilience-efficiency conflict."},hu:{q:"Loopy most egy helyett három, különböző országokból származó beszállítótól veszi a kakaót. Mit nyer ezzel elsősorban – és mi a hátránya?",o:["Nagyobb rezilienciát – de kisebb hatékonyságot","Nagyobb hatékonyságot – de kisebb biztonságot","Alacsonyabb költséget – de nagyobb függőséget","Semmi előnyt – csak több kockázatot és költséget"],e:"A több beszállító ellenállóbbá teszi a láncot, de csökkenti a hatékonyságot (kisebb mennyiségek, több egyeztetés) – ez a reziliencia–hatékonyság konfliktus."}}],logistik:[{type:"text",level:1,de:{q:"Wie nennt man ein Unternehmen, das Transporte im eigenen Namen organisiert, sie aber nicht selbst durchführt?",a:["Spediteur","Spedition"],e:"Der Spediteur organisiert, der Frachtführer führt den Transport tatsächlich durch."},en:{q:"What do you call a company that organises transport in its own name but does not carry it out itself?",a:["freight forwarder","forwarder","forwarding agent"],e:"The freight forwarder organises, the carrier actually carries out the transport."},hu:{q:"Hogyan nevezzük azt a vállalatot, amely saját nevében szervez szállításokat, de maga nem hajtja végre őket?",a:["szállítmányozó","szállítmányozó cég"],e:"A szállítmányozó szervez, a fuvarozó ténylegesen végrehajtja a szállítást."}},{type:"text",level:2,de:{q:"Wie heißt der Frachtbrief im internationalen Straßengüterverkehr? (Abkürzung)",a:["CMR","CMR-Frachtbrief"],e:"Im Straßenverkehr gilt der CMR-Frachtbrief, im Bahnverkehr der CIM-Frachtbrief, in der Luftfahrt der Air Waybill."},en:{q:"What is the consignment note in international road freight called? (Abbreviation)",a:["CMR","CMR consignment note"],e:"Road: CMR consignment note, rail: CIM consignment note, air: air waybill."},hu:{q:"Hogy hívják a nemzetközi közúti áruszállítás fuvarlevelét? (Rövidítés)",a:["CMR","CMR fuvarlevél"],e:"Közúton a CMR, vasúton a CIM fuvarlevél, légi szállításnál az Air Waybill érvényes."}},{type:"mc",level:3,correctIndex:1,de:{q:"Ganze Lkw fahren auf einen Zug und werden so durch Österreich transportiert. Wie nennt man das?",o:["Unbegleiteter Containerverkehr","Rollende Landstraße (Huckepack)","Werkverkehr","Reiner Straßengüterverkehr im Transit"],e:"Bei der Rollenden Landstraße (RoLa) wird der ganze Lkw auf der Bahn transportiert – eine Form des Huckepackverkehrs im kombinierten Verkehr."},en:{q:"Whole lorries drive onto a train and are transported through Austria that way. What is this called?",o:["Unaccompanied container transport","Rolling motorway (piggyback)","Own-account transport","Pure road freight transport in transit"],e:"On the rolling motorway (RoLa) the whole lorry is carried by rail – a form of piggyback transport in combined transport."},hu:{q:"Egész kamionok hajtanak fel egy vonatra, és így szállítják őket Ausztrián keresztül. Hogy hívják ezt?",o:["Kíséret nélküli konténeres fuvarozás","Gördülő országút (huckepack)","Saját számlás fuvarozás","Tisztán közúti tranzit áruszállítás"],e:"A gördülő országúton (RoLa) az egész kamiont vasúton szállítják – ez a kombinált fuvarozáson belüli ráterheléses (huckepack) forma."}}],"der-handel":[{type:"text",level:1,de:{q:"Wie nennt man den Handel, der an Endverbraucher:innen verkauft?",a:["Einzelhandel","Detailhandel"],e:"Einzelhandel verkauft an Endverbraucher:innen, Großhandel an andere Unternehmen."},en:{q:"What do you call the trade that sells to end consumers?",a:["retail","retail trade","retailing"],e:"Retail sells to end consumers, wholesale to other businesses."},hu:{q:"Hogyan nevezzük azt a kereskedelmet, amely a végső fogyasztóknak ad el?",a:["kiskereskedelem"],e:"A kiskereskedelem a végső fogyasztóknak, a nagykereskedelem más vállalatoknak ad el."}},{type:"text",level:2,de:{q:"Wie nennt man ein System, bei dem ein selbstständiger Unternehmer gegen Gebühr das Konzept und die Marke eines anderen nutzt (z. B. McDonald's)?",a:["Franchising","Franchise","Franchisesystem"],e:"Beim Franchising zahlt der Franchisenehmer Gebühren und nutzt dafür Konzept, Marke und Unterstützung des Franchisegebers."},en:{q:"What do you call a system in which an independent business owner uses another company's concept and brand for a fee (e.g. McDonald's)?",a:["franchising","franchise","franchise system"],e:"In franchising the franchisee pays fees and in return uses the franchisor's concept, brand and support."},hu:{q:"Hogyan nevezzük azt a rendszert, amelyben egy önálló vállalkozó díj ellenében más koncepcióját és márkáját használja (pl. McDonald's)?",a:["franchise","franchising","franchise-rendszer"],e:"Franchise esetén a franchisevevő díjat fizet, és cserébe használja a franchiseadó koncepcióját, márkáját és támogatását."}},{type:"number",level:3,value:40,tol:.01,unit:{de:"%",en:"%",hu:"%"},de:{q:"Loopy kauft eine Packung Pralinen um 2,40 € ein (Einstandspreis) und verkauft sie um 4,00 € netto. Wie hoch ist die Handelsspanne in % vom Verkaufspreis?",e:"Handelsspanne = 4,00 − 2,40 = 1,60 €. In % vom Verkaufspreis: 1,60 ÷ 4,00 · 100 = 40 %."},en:{q:"Loopy buys a box of chocolates for €2.40 (cost price) and sells it for €4.00 net. What is the trade margin in % of the selling price?",e:"Trade margin = 4.00 − 2.40 = €1.60. As % of the selling price: 1.60 ÷ 4.00 · 100 = 40%."},hu:{q:"Loopy egy doboz bonbont 2,40 €-ért szerez be (beszerzési ár), és nettó 4,00 €-ért adja el. Hány százalék a kereskedelmi árrés az eladási árhoz viszonyítva?",e:"Árrés = 4,00 − 2,40 = 1,60 €. Az eladási ár %-ában: 1,60 ÷ 4,00 · 100 = 40%."}}],"businessplan-2jg":[{type:"text",level:1,de:{q:"Wie nennt man überprüfbare Zwischenziele im Umsetzungsfahrplan eines Businessplans?",a:["Meilensteine","Meilenstein"],e:"Meilensteine sind prüfbare Zwischenziele – so sieht man, ob man im Zeitplan liegt."},en:{q:"What do you call checkable interim goals in a business plan's implementation roadmap?",a:["milestones","milestone"],e:"Milestones are checkable interim goals – they show whether you are on schedule."},hu:{q:"Hogyan nevezzük az üzleti terv megvalósítási ütemtervében az ellenőrizhető részcélokat?",a:["mérföldkövek","mérföldkő"],e:"A mérföldkövek ellenőrizhető részcélok – megmutatják, tartjuk-e az ütemtervet."}},{type:"number",level:2,value:12e3,tol:0,unit:{de:"Stück",en:"pcs",hu:"db"},de:{q:"500 mögliche Käufer:innen kaufen jeweils 24 Packungen Pralinen pro Jahr. Wie hoch ist das Marktpotenzial in Stück?",e:"Marktpotenzial = mögliche Käufer · jährliche Kaufmenge = 500 · 24 = 12.000 Stück."},en:{q:"500 potential buyers each buy 24 boxes of chocolates per year. What is the market potential in pieces?",e:"Market potential = potential buyers · annual purchase quantity = 500 · 24 = 12,000 pieces."},hu:{q:"500 lehetséges vevő évente egyenként 24 doboz bonbont vásárol. Mekkora a piaci potenciál darabban?",e:"Piaci potenciál = lehetséges vevők · éves vásárlási mennyiség = 500 · 24 = 12 000 darab."}},{type:"number",level:3,value:3.6,tol:.01,unit:{de:"Punkte",en:"points",hu:"pont"},de:{q:"Scoring-Methode für Standort A: Kundennähe (Gewicht 50 %) 4 Punkte, Miete (Gewicht 30 %) 2 Punkte, Verkehrslage (Gewicht 20 %) 5 Punkte. Wie hoch ist das gewichtete Gesamtergebnis?",e:"0,5 · 4 + 0,3 · 2 + 0,2 · 5 = 2,0 + 0,6 + 1,0 = 3,6 Punkte."},en:{q:"Scoring method for location A: closeness to customers (weight 50%) 4 points, rent (weight 30%) 2 points, transport links (weight 20%) 5 points. What is the weighted total?",e:"0.5 · 4 + 0.3 · 2 + 0.2 · 5 = 2.0 + 0.6 + 1.0 = 3.6 points."},hu:{q:"Pontozásos módszer az A telephelyre: vevőközelség (súly 50%) 4 pont, bérleti díj (súly 30%) 2 pont, közlekedési helyzet (súly 20%) 5 pont. Mekkora a súlyozott összeredmény?",e:"0,5 · 4 + 0,3 · 2 + 0,2 · 5 = 2,0 + 0,6 + 1,0 = 3,6 pont."}}]},s={"unternehmer-firma-firmenbuch":[{type:"tf",level:1,correct:!0,de:{q:"Neueintragungen ins Firmenbuch werden in der Ediktsdatei veröffentlicht",e:"Richtig. Neueinträge erscheinen in der Ediktsdatei und auf der EVI. Einsehen kann das Firmenbuch jeder – über Gericht, Notar, Anwalt oder online."},en:{q:"New entries in the company register are published in the official edicts database (Ediktsdatei)",e:"True. New entries appear in the Ediktsdatei and on the EVI. Anyone can inspect the company register – via a court, notary, lawyer or online."},hu:{q:"A cégjegyzékbe történt új bejegyzéseket az Ediktsdatei hirdetményi adatbázisban teszik közzé",e:"Igaz. Az új bejegyzések megjelennek az Ediktsdateiban és az EVI-n. A cégjegyzékbe bárki betekinthet – bíróságon, közjegyzőnél, ügyvédnél vagy online."}},{type:"tf",level:2,correct:!0,de:{q:"Eine GmbH schließt Verträge über ihre Organe ab, z. B. über ihren Geschäftsführer, weil sie als juristische Person nicht selbst handeln kann",e:"Richtig. Juristische Personen haben zwar Rechte und Pflichten, handeln aber durch Menschen – ihre Organe (bei der GmbH v. a. der Geschäftsführer)."},en:{q:"A GmbH concludes contracts through its bodies, e.g. its managing director, because as a legal person it cannot act by itself",e:"True. Legal persons have rights and duties but act through people – their bodies (in a GmbH mainly the managing director)."},hu:{q:"Egy kft. a szervein, pl. az ügyvezetőjén keresztül köt szerződéseket, mert jogi személyként önmaga nem tud cselekedni",e:"Igaz. A jogi személyeknek vannak jogaik és kötelezettségeik, de emberek – a szerveik (kft.-nél főként az ügyvezető) – útján cselekszenek."}},{type:"tf",level:3,correct:!1,de:{q:"Die Musterunterschriften der vertretungsbefugten Personen findet man im Hauptbuch des Firmenbuchs",e:"Falsch. Das Hauptbuch enthält die Daten (Firmenname, FN, Rechtsform, Sitz, Inhaber). Dokumente wie Musterunterschriften, Gesellschaftsvertrag und Bilanz liegen in der Urkundensammlung."},en:{q:"The specimen signatures of the persons authorised to represent the company are found in the main register (Hauptbuch) of the company register",e:"False. The main register holds the data (company name, number, legal form, seat, owners). Documents such as specimen signatures, the partnership agreement and the balance sheet are kept in the collection of documents."},hu:{q:"A képviseletre jogosult személyek aláírásmintái a cégjegyzék főkönyvében találhatók",e:"Hamis. A főkönyv az adatokat tartalmazza (cégnév, cégjegyzékszám, jogi forma, székhely, tulajdonosok). Az olyan dokumentumok, mint az aláírásminták, a társasági szerződés és a mérleg, az okirattárban vannak."}},{type:"multi",level:1,correct:[0,1,2,5],de:{q:"Welche Unternehmen müssen sich verpflichtend ins Firmenbuch eintragen lassen? Wähle alle zutreffenden.",o:["Eine Offene Gesellschaft (OG)","Eine GmbH","Eine Genossenschaft","Eine Ärztin mit eigener Ordination","Ein Einzelunternehmer mit 80.000 € Jahresumsatz","Eine Kommanditgesellschaft (KG)"],e:"Personengesellschaften (OG, KG), Kapitalgesellschaften und Genossenschaften sind immer eintragungspflichtig. Freie Berufe und kleine Einzelunternehmen dürfen sich freiwillig eintragen."},en:{q:"Which businesses must be entered in the company register? Select all that apply.",o:["A general partnership (OG)","A GmbH","A cooperative","A doctor with her own practice","A sole trader with an annual turnover of €80,000","A limited partnership (KG)"],e:"Partnerships (OG, KG), corporations and cooperatives must always register. Liberal professions and small sole traders may register voluntarily."},hu:{q:"Mely vállalkozásoknak kötelező bejegyeztetniük magukat a cégjegyzékbe? Jelöld meg az összes helyeset.",o:["Egy közkereseti társaság (OG)","Egy kft. (GmbH)","Egy szövetkezet","Egy saját rendelővel rendelkező orvosnő","Egy 80 000 € éves árbevételű egyéni vállalkozó","Egy betéti társaság (KG)"],e:"A személyegyesítő társaságok (OG, KG), a tőketársaságok és a szövetkezetek bejegyzése mindig kötelező. A szabadfoglalkozásúak és a kis egyéni vállalkozók önkéntesen jegyeztethetik be magukat."}},{type:"multi",level:2,correct:[0,1,2,3],de:{q:"Welche Angaben muss ein im Firmenbuch eingetragenes Unternehmen auf Geschäftsbriefen, in E-Mails und im Impressum machen? Wähle alle zutreffenden.",o:["Firmenname","Rechtsform","Firmenbuchnummer und Firmenbuchgericht","Sitz des Unternehmens","Umsatz des letzten Geschäftsjahres","Privatadresse der Geschäftsführung"],e:"Pflichtangaben sind Firmenname, Rechtsform, Firmenbuchnummer, Firmenbuchgericht und Sitz. Umsatz oder Privatadressen gehören nicht dazu."},en:{q:"Which details must a registered business state on business letters, in e-mails and in its imprint? Select all that apply.",o:["Company name","Legal form","Company register number and register court","Registered seat","Turnover of the last financial year","Private address of the management"],e:"Mandatory details are company name, legal form, company register number, register court and seat. Turnover or private addresses are not required."},hu:{q:"Milyen adatokat kell egy cégjegyzékbe bejegyzett vállalkozásnak feltüntetnie üzleti leveleken, e-mailekben és az impresszumban? Jelöld meg az összes helyeset.",o:["Cégnév","Jogi forma","Cégjegyzékszám és cégbíróság","A vállalkozás székhelye","Az előző üzleti év árbevétele","A vezetőség lakcíme"],e:"Kötelező adat a cégnév, a jogi forma, a cégjegyzékszám, a cégbíróság és a székhely. Az árbevétel vagy a lakcímek nem tartoznak ide."}},{type:"match",level:2,de:{q:"Ordne jeden Firmennamen der passenden Firmenart zu.",p:[["Anna Berger e. U.","Personenfirma"],["Tiroler Holzbau GmbH","Sachfirma"],["Zuckerwolke GmbH","Fantasiefirma"],["Julia Moser Gartenbau KG","Gemischte Firma"]],e:"Personenfirma = Name des Inhabers, Sachfirma = Hinweis auf den Unternehmensgegenstand, Fantasiefirma = erfundener Name, gemischte Firma = Name + Gegenstand."},en:{q:"Match each company name to the right type of company name.",p:[["Anna Berger e. U.","Personal name"],["Tiroler Holzbau GmbH","Descriptive name"],["Zuckerwolke GmbH","Fantasy name"],["Julia Moser Gartenbau KG","Mixed name"]],e:"Personal name = owner's name, descriptive name = refers to the business activity, fantasy name = invented name, mixed name = name + activity."},hu:{q:"Párosítsd az egyes cégneveket a megfelelő cégnévtípussal.",p:[["Anna Berger e. U.","Személynév-cégnév"],["Tiroler Holzbau GmbH","Tárgyi cégnév"],["Zuckerwolke GmbH","Fantázianév"],["Julia Moser Gartenbau KG","Vegyes cégnév"]],e:"Személynév-cégnév = a tulajdonos neve, tárgyi cégnév = utal a tevékenységre, fantázianév = kitalált név, vegyes cégnév = név + tevékenység."}},{type:"mc",level:2,correctIndex:2,de:{q:"Thomas kauft das gut eingeführte Unternehmen „Huber Elektro e. U.“ von Franz Huber. Er möchte den bekannten Namen weiterführen. Was gilt?",o:["Das ist nie erlaubt, weil Thomas nicht Huber heißt","Das ist erlaubt, wenn das Firmenbuchgericht zustimmt","Das ist erlaubt, wenn Franz Huber zustimmt","Das ist ohne Weiteres erlaubt, weil er das Unternehmen gekauft hat"],e:"Bei Unternehmenskauf oder Erbschaft darf der bisherige Firmenname weitergeführt werden, wenn der frühere Inhaber zustimmt. Ohne diese Zustimmung geht es nicht – auch nicht automatisch durch den Kauf."},en:{q:"Thomas buys the well-established business ‘Huber Elektro e. U.’ from Franz Huber. He wants to keep the well-known name. What applies?",o:["This is never allowed because Thomas is not called Huber","This is allowed if the register court agrees","This is allowed if Franz Huber agrees","This is allowed anyway because he bought the business"],e:"When a business is bought or inherited, the existing company name may be continued if the former owner agrees. Without that consent it is not possible – the purchase alone is not enough."},hu:{q:"Thomas megvásárolja Franz Hubertől a jól bevezetett „Huber Elektro e. U.” vállalkozást. Szeretné megtartani az ismert nevet. Mi érvényes?",o:["Ez soha nem megengedett, mert Thomast nem Hubernek hívják","Ez megengedett, ha a cégbíróság hozzájárul","Ez megengedett, ha Franz Huber hozzájárul","Ez minden további nélkül megengedett, mert megvette a vállalkozást"],e:"Vállalkozás megvásárlásakor vagy öröklésekor a korábbi cégnév továbbvihető, ha a korábbi tulajdonos hozzájárul. Hozzájárulás nélkül nem lehet – a vásárlás önmagában nem elég."}},{type:"mc",level:3,correctIndex:1,de:{q:"Loopy betreibt ihren Candy Store als nicht eingetragenes Einzelunternehmen. Umsatz: 2024 = 750.000 €, 2025 = 820.000 €. Was gilt nun für das Firmenbuch?",o:["Keine Pflicht, weil sie nie über 1 Mio. € Umsatz lag","Eintragung ist Pflicht, weil sie 2 Jahre in Folge über 700.000 € lag","Eintragung ist Pflicht, sobald sie einen Mitarbeiter anstellt","Keine Pflicht, weil Einzelunternehmen nie eintragungspflichtig sind"],e:"Ein Einzelunternehmen muss sich eintragen lassen, wenn es über 1 Mio. € Umsatz in einem Jahr ODER in zwei aufeinanderfolgenden Jahren jeweils über 700.000 € hat. Loopy erfüllt die zweite Bedingung."},en:{q:"Loopy runs her Candy Store as an unregistered sole proprietorship. Turnover: 2024 = €750,000, 2025 = €820,000. What now applies regarding the company register?",o:["No obligation, because she never exceeded €1 million turnover","Registration is mandatory, as she exceeded €700,000 two years in a row","Registration is mandatory as soon as she hires an employee","No obligation, because sole proprietorships never have to register"],e:"A sole proprietorship must register if its turnover exceeds €1 million in one year OR €700,000 in each of two consecutive years. Loopy meets the second condition."},hu:{q:"Loopy be nem jegyzett egyéni vállalkozásként üzemelteti a Candy Store-t. Árbevétel: 2024 = 750 000 €, 2025 = 820 000 €. Mi érvényes most a cégjegyzékre?",o:["Nincs kötelezettség, mert soha nem lépte túl az 1 millió € árbevételt","Kötelező a bejegyzés, mert két egymást követő évben 700 000 € felett volt","Kötelező a bejegyzés, amint alkalmazottat vesz fel","Nincs kötelezettség, mert egyéni vállalkozásokat soha nem kell bejegyezni"],e:"Egy egyéni vállalkozásnak be kell jegyeztetnie magát, ha egy évben 1 millió € feletti, VAGY két egymást követő évben évente 700 000 € feletti az árbevétele. Loopy a második feltételt teljesíti."}},{type:"mc",level:3,correctIndex:1,de:{q:"Vor einer Kreditvergabe will die Bank den Gesellschaftsvertrag und die letzte Bilanz der „Holz Maier GmbH“ einsehen. Wo findet sie diese Unterlagen?",o:["Im Hauptbuch des Firmenbuchs","In der Urkundensammlung","In der Ediktsdatei","Im Gewerbeinformationssystem (GISA)"],e:"Dokumente wie Gesellschaftsvertrag, Bilanz, Musterunterschriften und Gesellschafterbeschlüsse liegen in der Urkundensammlung. Das Hauptbuch enthält nur die Eckdaten, die Ediktsdatei dient der Veröffentlichung von Neueinträgen."},en:{q:"Before granting a loan, the bank wants to see the partnership agreement and the latest balance sheet of ‘Holz Maier GmbH’. Where does it find these documents?",o:["In the main register of the company register","In the collection of documents","In the official edicts database (Ediktsdatei)","In the trade information system (GISA)"],e:"Documents such as the partnership agreement, balance sheet, specimen signatures and shareholder resolutions are kept in the collection of documents. The main register only holds the key data; the Ediktsdatei is used to publish new entries."},hu:{q:"Hitelnyújtás előtt a bank meg akarja tekinteni a „Holz Maier GmbH” társasági szerződését és legutóbbi mérlegét. Hol találja ezeket a dokumentumokat?",o:["A cégjegyzék főkönyvében","A cégjegyzék okirattárában","Az Ediktsdatei hirdetményi adatbázisban","Az iparűzési információs rendszerben (GISA)"],e:"Az olyan dokumentumok, mint a társasági szerződés, a mérleg, az aláírásminták és a taggyűlési határozatok, az okirattárban vannak. A főkönyv csak az alapadatokat tartalmazza, az Ediktsdatei az új bejegyzések közzétételére szolgál."}},{type:"text",level:1,de:{q:"Wie heißt der frei wählbare Teil des Firmennamens, z. B. „Red Bull“ in „Red Bull GmbH“?",a:["Firmenkern","Firmenwortlaut","Kern"],e:"Firma = Firmenkern (frei wählbar) + Firmenzusatz (Rechtsform, z. B. GmbH)."},en:{q:"What is the freely chosen part of a company name called, e.g. ‘Red Bull’ in ‘Red Bull GmbH’?",a:["core name","company core","core of the company name","core"],e:"Company name = core name (freely chosen) + suffix showing the legal form (e.g. GmbH)."},hu:{q:"Hogyan nevezzük a cégnév szabadon választható részét, pl. a „Red Bull”-t a „Red Bull GmbH”-ban?",a:["cégnévmag","cégnév magja","mag","vezérszó"],e:"Cégnév = cégnévmag (szabadon választható) + cégforma-toldat (jogi forma, pl. GmbH)."}}],"rechtsformen-unternehmen":[{type:"tf",level:1,correct:!0,de:{q:"Ein Einzelunternehmen entsteht mit der Gewerbeanmeldung",e:"Richtig. Das Einzelunternehmen entsteht mit der Gewerbeanmeldung; ins Firmenbuch muss es erst ab den Umsatzgrenzen (dann als e. U.)."},en:{q:"A sole proprietorship comes into existence when the trade is registered",e:"True. A sole proprietorship comes into being with the trade registration; it only has to enter the company register once it exceeds the turnover thresholds (then as e. U.)."},hu:{q:"Az egyéni vállalkozás az iparűzési bejelentéssel jön létre",e:"Igaz. Az egyéni vállalkozás az iparűzési bejelentéssel jön létre; a cégjegyzékbe csak az árbevételi határok átlépésekor kell bejegyezni (akkor e. U.-ként)."}},{type:"tf",level:2,correct:!1,de:{q:"Stirbt ein Gesellschafter einer GmbH, ist die GmbH automatisch aufgelöst",e:"Falsch. Tod oder Konkurs eines Gesellschafters lösen Einzelunternehmen und Personengesellschaften auf – Kapitalgesellschaften wie die GmbH bestehen als juristische Personen weiter; der Anteil geht z. B. an die Erben."},en:{q:"If a shareholder of a GmbH dies, the GmbH is automatically dissolved",e:"False. Death or bankruptcy of a partner dissolves sole proprietorships and partnerships – corporations such as the GmbH continue to exist as legal persons; the share passes e.g. to the heirs."},hu:{q:"Ha egy kft. tagja meghal, a kft. automatikusan megszűnik",e:"Hamis. Egy tag halála vagy csődje az egyéni vállalkozást és a személyegyesítő társaságokat szünteti meg – a tőketársaságok, mint a kft., jogi személyként tovább léteznek; az üzletrész pl. az örökösökre száll."}},{type:"tf",level:2,correct:!0,de:{q:"Wer aus einer OG ausscheidet, haftet noch 5 Jahre lang für die Schulden, die bis zu seinem Ausscheiden entstanden sind",e:"Richtig. Die Haftung für alte Schulden endet nicht mit dem Austritt – ausgeschiedene OG-Gesellschafter haften noch 5 Jahre."},en:{q:"A partner who leaves an OG remains liable for 5 years for the debts incurred up to the date of leaving",e:"True. Liability for old debts does not end with leaving – former OG partners remain liable for another 5 years."},hu:{q:"Aki kilép egy közkereseti társaságból (OG), még 5 évig felel a kilépéséig keletkezett tartozásokért",e:"Igaz. A régi tartozásokért fennálló felelősség nem szűnik meg a kilépéssel – a kilépett OG-tagok még 5 évig felelnek."}},{type:"tf",level:3,correct:!1,de:{q:"Ein Kommanditist darf die KG leiten und nach außen vertreten, sobald er seine Haftsumme voll eingezahlt hat",e:"Falsch. Leitung und Vertretung liegen bei den Komplementären. Der Kommanditist hat nur ein Kontrollrecht – daran ändert auch eine voll eingezahlte Haftsumme nichts."},en:{q:"A limited partner may manage the KG and represent it externally once he has fully paid in his liability amount",e:"False. Management and representation lie with the general partners. The limited partner only has a right of control – a fully paid liability amount does not change this."},hu:{q:"Egy kültag vezetheti és kifelé képviselheti a betéti társaságot (KG), amint teljesen befizette a vállalt összeget",e:"Hamis. A vezetés és a képviselet a beltagok feladata. A kültagnak csak ellenőrzési joga van – ezen a teljesen befizetett vállalt összeg sem változtat."}},{type:"multi",level:1,correct:[0,1],de:{q:"Welche Gesellschaftsformen werden NICHT ins Firmenbuch eingetragen? Wähle alle zutreffenden.",o:["Stille Gesellschaft","Gesellschaft bürgerlichen Rechts (GesbR)","Kommanditgesellschaft (KG)","Genossenschaft","Flexible Kapitalgesellschaft (FlexKapG)"],e:"Stille Gesellschaft und GesbR sind keine eigenen Rechtsformen im Firmenbuch – die Stille Gesellschaft ist nach außen sogar unsichtbar. KG, Genossenschaft und FlexKapG sind eintragungspflichtig."},en:{q:"Which forms of company are NOT entered in the company register? Select all that apply.",o:["Silent partnership","Civil-law partnership (GesbR)","Limited partnership (KG)","Cooperative","Flexible corporation (FlexKapG)"],e:"The silent partnership and the GesbR are not entered in the company register – the silent partnership is even invisible to outsiders. KG, cooperative and FlexKapG must register."},hu:{q:"Mely társasági formákat NEM jegyzik be a cégjegyzékbe? Jelöld meg az összes helyeset.",o:["Csendes társaság","Polgári jogi társaság (GesbR)","Betéti társaság (KG)","Szövetkezet","Rugalmas tőketársaság (FlexKapG)"],e:"A csendes társaság és a GesbR nem kerül be a cégjegyzékbe – a csendes társaság kifelé egyáltalán nem is látható. A KG, a szövetkezet és a FlexKapG bejegyzése kötelező."}},{type:"multi",level:2,correct:[0,2,4],de:{q:"Welche Aussagen zur Ertragsbesteuerung treffen zu? Wähle alle zutreffenden.",o:["Ein Einzelunternehmer zahlt auf seinen Gewinn Einkommensteuer (bis 55 %)","Eine OG zahlt auf ihren Gewinn selbst Körperschaftsteuer","Eine GmbH zahlt auf ihren Gewinn 23 % Körperschaftsteuer","Dividenden einer AG sind für Aktionär:innen steuerfrei","Die Gesellschafter einer KG zahlen Einkommensteuer auf ihren Gewinnanteil"],e:"Einzelunternehmer und Gesellschafter von Personengesellschaften (OG, KG) zahlen ESt. Kapitalgesellschaften zahlen 23 % KöSt; auf Ausschüttungen wie Dividenden fallen zusätzlich 27,5 % KESt an."},en:{q:"Which statements on income taxation are correct? Select all that apply.",o:["A sole trader pays income tax on his profit (up to 55%)","An OG itself pays corporation tax on its profit","A GmbH pays 23% corporation tax on its profit","Dividends of an AG are tax-free for shareholders","The partners of a KG pay income tax on their share of the profit"],e:"Sole traders and partners of partnerships (OG, KG) pay income tax. Corporations pay 23% corporation tax; distributions such as dividends are additionally subject to 27.5% capital gains tax (KESt)."},hu:{q:"Mely állítások helyesek a jövedelemadózásról? Jelöld meg az összes helyeset.",o:["Az egyéni vállalkozó a nyeresége után jövedelemadót fizet (legfeljebb 55%)","Az OG maga fizet társasági adót a nyeresége után","A kft. a nyeresége után 23% társasági adót fizet","Az rt. osztaléka a részvényesek számára adómentes","A KG tagjai a nyereségrészük után jövedelemadót fizetnek"],e:"Az egyéni vállalkozók és a személyegyesítő társaságok (OG, KG) tagjai jövedelemadót fizetnek. A tőketársaságok 23% társasági adót fizetnek; a kifizetésekre, például az osztalékra, ezen felül 27,5% tőkehozam-adó (KESt) terhel."}},{type:"match",level:1,de:{q:"Ordne jeder Rechtsform zu, wer die Gesellschaft leitet.",p:[["Aktiengesellschaft","Vorstand"],["GmbH","Geschäftsführer"],["Kommanditgesellschaft","Komplementär(e)"],["Offene Gesellschaft","alle Gesellschafter"]],e:"AG: Vorstand (bestellt vom Aufsichtsrat). GmbH: Geschäftsführer (bestellt von der Generalversammlung). KG: nur die Komplementäre. OG: alle Gesellschafter."},en:{q:"Match each legal form with who manages the company.",p:[["Stock corporation (AG)","Management board"],["GmbH","Managing director"],["Limited partnership (KG)","General partner(s)"],["General partnership (OG)","All partners"]],e:"AG: management board (appointed by the supervisory board). GmbH: managing director (appointed by the general meeting). KG: only the general partners. OG: all partners."},hu:{q:"Párosítsd az egyes jogi formákat azzal, aki a társaságot vezeti.",p:[["Részvénytársaság (AG)","Igazgatóság"],["Kft. (GmbH)","Ügyvezető"],["Betéti társaság (KG)","Beltag(ok)"],["Közkereseti társaság (OG)","Minden tag"]],e:"AG: igazgatóság (a felügyelőbizottság nevezi ki). Kft.: ügyvezető (a taggyűlés nevezi ki). KG: csak a beltagok. OG: minden tag."}},{type:"mc",level:2,correctIndex:0,de:{q:"Sophie gründet eine Tischlerei und will sie leiten. Ihr Onkel gibt 50.000 €, will aber nicht mitarbeiten und nur bis zu diesem Betrag haften. Er soll offiziell als Gesellschafter im Firmenbuch stehen, ein Mindestkapital soll nicht nötig sein. Welche Rechtsform passt?",o:["Kommanditgesellschaft (KG)","Offene Gesellschaft (OG)","Stille Gesellschaft","Gesellschaft bürgerlichen Rechts"],e:"Die KG passt, wenn eine Person arbeitet und haftet (Komplementärin Sophie) und eine andere nur Kapital gibt und beschränkt haftet (Kommanditist). Eine Stille Gesellschaft wäre nach außen unsichtbar und steht nicht im Firmenbuch; bei OG und GesbR haften alle unbeschränkt."},en:{q:"Sophie founds a joinery and wants to run it. Her uncle contributes €50,000 but does not want to work in it and only wants to be liable up to that amount. He is to be officially listed as a partner in the company register, and no minimum capital should be needed. Which legal form fits?",o:["Limited partnership (KG)","General partnership (OG)","Silent partnership","Civil-law partnership (GesbR)"],e:"The KG fits when one person works and is fully liable (Sophie as general partner) and another only provides capital with limited liability (limited partner). A silent partnership would be invisible and is not in the company register; in an OG and a GesbR everyone is fully liable."},hu:{q:"Sophie asztalosműhelyt alapít, és ő akarja vezetni. A nagybátyja 50 000 €-t ad, de nem akar dolgozni benne, és csak eddig az összegig akar felelni. Hivatalosan tagként kell szerepelnie a cégjegyzékben, és ne legyen szükség minimális tőkére. Melyik jogi forma illik ide?",o:["Betéti társaság (KG)","Közkereseti társaság (OG)","Csendes társaság","Polgári jogi társaság (GesbR)"],e:"A KG akkor illik, ha az egyik személy dolgozik és korlátlanul felel (Sophie mint beltag), a másik pedig csak tőkét ad és korlátozottan felel (kültag). A csendes társaság kifelé láthatatlan és nincs a cégjegyzékben; az OG-ben és a GesbR-ben mindenki korlátlanul felel."}},{type:"mc",level:3,correctIndex:2,de:{q:"Anna, Ben und Clara sind gleichberechtigte Gesellschafter der „ABC Catering OG“. Ein Lieferant hat eine offene Forderung von 60.000 € und verlangt den gesamten Betrag direkt von Ben. Was gilt?",o:["Ben muss nur seinen eigenen Anteil von 20.000 € zahlen","Der Lieferant muss zuerst das Vermögen der OG einklagen","Ben muss alles zahlen, kann aber intern Rückgriff nehmen","Ben haftet nur, wenn Anna und Clara zahlungsunfähig sind"],e:"OG-Gesellschafter haften unbeschränkt, unmittelbar und solidarisch: Der Gläubiger kann sich direkt an einen beliebigen Gesellschafter wenden und den vollen Betrag verlangen. Im Innenverhältnis kann sich Ben das Geld anteilig von den anderen zurückholen."},en:{q:"Anna, Ben and Clara are equal partners in ‘ABC Catering OG’. A supplier has an outstanding claim of €60,000 and demands the full amount directly from Ben. What applies?",o:["Ben only has to pay his own share of €20,000","The supplier must first sue the assets of the OG","Ben must pay it all but can claim recourse internally","Ben is only liable if Anna and Clara are insolvent"],e:"OG partners are liable without limit, directly and jointly and severally: the creditor can turn directly to any partner and demand the full amount. Internally, Ben can recover the others' shares from them."},hu:{q:"Anna, Ben és Clara egyenrangú tagjai az „ABC Catering OG”-nek. Egy beszállítónak 60 000 € nyitott követelése van, és a teljes összeget közvetlenül Bentől követeli. Mi érvényes?",o:["Bennek csak a saját 20 000 €-s részét kell kifizetnie","A beszállítónak először az OG vagyonát kell perelnie","Bennek mindent fizetnie kell, de visszkeresettel élhet","Ben csak akkor felel, ha Anna és Clara fizetésképtelen"],e:"Az OG tagjai korlátlanul, közvetlenül és egyetemlegesen felelnek: a hitelező közvetlenül bármelyik taghoz fordulhat, és a teljes összeget követelheti. Belső viszonyban Ben a többiektől visszakérheti az őket terhelő részt."}},{type:"number",level:3,value:6.08,tol:.01,unit:{de:"€",en:"€",hu:"€"},de:{q:"Eine AG hat ein Grundkapital von 2.000.000 €, aufgeteilt in Aktien mit einem Nennbetrag von je 20 €. Der Jahresgewinn beträgt 640.000 €, davon kommen 5 % in die Rücklage. Wie hoch ist die Dividende pro Aktie?",e:"Anzahl Aktien = 2.000.000 / 20 = 100.000. Rücklage = 5 % von 640.000 = 32.000 €. Auszuschüttender Gewinn = 608.000 €. Dividende = 608.000 / 100.000 = 6,08 € pro Aktie."},en:{q:"An AG has share capital of €2,000,000, divided into shares with a nominal value of €20 each. The annual profit is €640,000, of which 5% goes into reserves. How high is the dividend per share?",e:"Number of shares = 2,000,000 / 20 = 100,000. Reserve = 5% of 640,000 = €32,000. Profit to distribute = €608,000. Dividend = 608,000 / 100,000 = €6.08 per share."},hu:{q:"Egy rt. alaptőkéje 2 000 000 €, amely egyenként 20 € névértékű részvényekre oszlik. Az éves nyereség 640 000 €, ennek 5%-a tartalékba kerül. Mekkora az egy részvényre jutó osztalék?",e:"Részvények száma = 2 000 000 / 20 = 100 000. Tartalék = 640 000 5%-a = 32 000 €. Felosztható nyereség = 608 000 €. Osztalék = 608 000 / 100 000 = 6,08 € részvényenként."}}],vollmachten:[{type:"tf",level:1,correct:!0,de:{q:"Eine Handlungsvollmacht kann auch durch schlüssiges Handeln entstehen, ohne dass sie ausdrücklich erteilt wurde",e:"Richtig. Bestellt z. B. ein Mitarbeiter wiederholt Waren und der Chef zahlt jedes Mal, entsteht eine Handlungsvollmacht durch schlüssiges Handeln. Die Prokura dagegen muss ausdrücklich erteilt werden."},en:{q:"A commercial power of attorney (Handlungsvollmacht) can also arise from conduct, without being granted expressly",e:"True. If, for example, an employee repeatedly orders goods and the boss pays every time, a power of attorney arises from conduct. Prokura, by contrast, must be granted expressly."},hu:{q:"A kereskedelmi meghatalmazás ráutaló magatartással is létrejöhet, kifejezett megadás nélkül",e:"Igaz. Ha például egy munkatárs többször rendel árut, és a főnök minden alkalommal kifizeti, ráutaló magatartással kereskedelmi meghatalmazás jön létre. A prokúrát ezzel szemben kifejezetten kell megadni."}},{type:"tf",level:2,correct:!1,de:{q:"Ein Prokurist darf die Bilanz des Unternehmens unterzeichnen",e:"Falsch. Die Bilanz unterzeichnet der Unternehmer bzw. das Leitungsorgan. Prokuristen dürfen sie ebenso wenig unterschreiben, wie sie das Unternehmen verkaufen oder den Firmennamen ändern dürfen."},en:{q:"An authorised officer (Prokurist) may sign the company's balance sheet",e:"False. The balance sheet is signed by the owner or the management body. A Prokurist may not sign it, just as he may not sell the business or change the company name."},hu:{q:"A cégvezető (prokurista) aláírhatja a vállalkozás mérlegét",e:"Hamis. A mérleget a vállalkozó, illetve a vezető szerv írja alá. A prokurista ezt nem teheti meg, ahogy a vállalkozást sem adhatja el, és a cégnevet sem változtathatja meg."}},{type:"tf",level:3,correct:!1,de:{q:"Auch ein nicht im Firmenbuch eingetragener Einzelunternehmer kann einer Mitarbeiterin Prokura erteilen",e:"Falsch. Prokura kann nur ein im Firmenbuch eingetragenes Unternehmen erteilen, weil sie ins Firmenbuch eingetragen werden muss. Ein nicht eingetragener Unternehmer kann nur Handlungsvollmacht erteilen."},en:{q:"A sole trader who is not entered in the company register can also grant Prokura to an employee",e:"False. Only a business entered in the company register can grant Prokura, because Prokura must itself be entered there. An unregistered trader can only grant a commercial power of attorney."},hu:{q:"Egy cégjegyzékbe be nem jegyzett egyéni vállalkozó is adhat prokúrát egy munkatársának",e:"Hamis. Prokúrát csak cégjegyzékbe bejegyzett vállalkozás adhat, mert a prokúrát is be kell jegyezni a cégjegyzékbe. Egy be nem jegyzett vállalkozó csak kereskedelmi meghatalmazást adhat."}},{type:"multi",level:2,correct:[0,1,2],de:{q:"Filialleiterin Eva hat eine Generalvollmacht für ihre Boutique. Was darf sie damit? Wähle alle zutreffenden.",o:["Die neue Kollektion einkaufen","Löhne und Gehälter auszahlen","Eine neue Verkäuferin einstellen","Einen Bankkredit für die Boutique aufnehmen","Das Unternehmen in einem Gerichtsverfahren vertreten"],e:"Die Generalvollmacht deckt alle gewöhnlichen Geschäfte des Unternehmens. Kredite aufnehmen und das Unternehmen vor Gericht vertreten darf ein Handlungsbevollmächtigter aber nicht – das darf erst ein Prokurist."},en:{q:"Branch manager Eva holds a general commercial power of attorney (Generalvollmacht) for her boutique. What may she do with it? Select all that apply.",o:["Buy the new collection","Pay wages and salaries","Hire a new sales assistant","Take out a bank loan for the boutique","Represent the business in court proceedings"],e:"A general power of attorney covers all ordinary transactions of the business. However, a holder of a commercial power of attorney may not take out loans or represent the business in court – only a Prokurist may do that."},hu:{q:"Eva üzletvezetőnek általános meghatalmazása van a butikjára. Mit tehet ennek alapján? Jelöld meg az összes helyeset.",o:["Beszerezheti az új kollekciót","Kifizetheti a béreket és fizetéseket","Felvehet egy új eladót","Bankhitelt vehet fel a butik számára","Képviselheti a vállalkozást bírósági eljárásban"],e:"Az általános meghatalmazás a vállalkozás minden szokásos ügyletére kiterjed. Hitelt felvenni és a vállalkozást bíróság előtt képviselni azonban kereskedelmi meghatalmazott nem jogosult – erre csak a prokurista."}},{type:"multi",level:3,correct:[0,1,2],de:{q:"Prokurist Leon darf laut interner Anweisung keine Geschäfte über 9.500 € abschließen. Trotzdem kauft er bei einem Lieferanten, der davon nichts weiß, eine Maschine um 20.000 €. Welche Aussagen treffen zu? Wähle alle zutreffenden.",o:["Der Kaufvertrag ist gültig","Der Lieferant kann vom Unternehmen die Bezahlung verlangen","Leon kann schadenersatzpflichtig werden und gekündigt werden","Der Vertrag ist nichtig, weil Leon seine Grenze überschritten hat","Das Unternehmen kann vom Vertrag zurücktreten, weil die Grenze vereinbart war"],e:"Interne Beschränkungen der Prokura gelten nicht gegenüber Dritten – der Vertrag bindet das Unternehmen. Im Innenverhältnis haftet Leon aber auf Schadenersatz und riskiert seine Kündigung."},en:{q:"According to an internal instruction, Prokurist Leon may not conclude deals above €9,500. Nevertheless, he buys a machine for €20,000 from a supplier who knows nothing about this. Which statements are correct? Select all that apply.",o:["The purchase contract is valid","The supplier can demand payment from the business","Leon may be liable for damages and may be dismissed","The contract is void because Leon exceeded his limit","The business can withdraw from the contract because the limit was agreed"],e:"Internal restrictions on Prokura do not apply to third parties – the contract binds the business. Internally, however, Leon is liable for damages and risks dismissal."},hu:{q:"Leon prokurista belső utasítás szerint nem köthet 9 500 € feletti ügyletet. Ennek ellenére egy beszállítótól, aki erről semmit sem tud, vesz egy 20 000 €-s gépet. Mely állítások helyesek? Jelöld meg az összes helyeset.",o:["Az adásvételi szerződés érvényes","A beszállító követelheti a vállalkozástól a fizetést","Leon kártérítésre kötelezhető, és fel is mondhatnak neki","A szerződés semmis, mert Leon túllépte a keretét","A vállalkozás elállhat a szerződéstől, mert a keretet megállapodták"],e:"A prokúra belső korlátozásai harmadik személyekkel szemben nem érvényesek – a szerződés köti a vállalkozást. Belső viszonyban azonban Leon kártérítéssel tartozik, és a felmondását kockáztatja."}},{type:"order",level:2,de:{q:"Ordne die Vollmachten vom größten zum kleinsten Umfang.",o:["Prokura","Generalvollmacht","Artvollmacht","Spezialvollmacht"],e:"Prokura (alle Geschäfte des Betriebs, pp./ppa.) > Generalvollmacht (alle gewöhnlichen Geschäfte, i. V.) > Artvollmacht (eine bestimmte Art von Geschäften, i. A.) > Spezialvollmacht (eine einzelne Handlung, i. A.)."},en:{q:"Put the powers of attorney in order from the widest to the narrowest scope.",o:["Prokura","General power of attorney","Power for a type of transaction","Special power of attorney"],e:"Prokura (all transactions of the business, pp./ppa.) > general power (all ordinary transactions, i. V.) > power for a type of transaction (one kind of deal, i. A.) > special power (a single act, i. A.)."},hu:{q:"Állítsd sorba a meghatalmazásokat a legszélesebbtől a legszűkebb terjedelműig.",o:["Prokúra","Általános meghatalmazás","Ügyfajtára szóló meghatalmazás","Eseti meghatalmazás"],e:"Prokúra (az üzem összes ügylete, pp./ppa.) > általános meghatalmazás (minden szokásos ügylet, i. V.) > ügyfajtára szóló meghatalmazás (egy bizonyos ügyletfajta, i. A.) > eseti meghatalmazás (egyetlen cselekmény, i. A.)."}},{type:"match",level:1,de:{q:"Ordne jede Art der Prokura ihrer Bedeutung zu.",p:[["Einzelprokura","vertritt allein"],["Gesamtprokura","nur gemeinsam mit anderen Prokuristen"],["Gemischte Prokura","nur gemeinsam mit Geschäftsführer/Vorstand"],["Filialprokura","nur für eine bestimmte Filiale"]],e:"Einzelprokura = allein vertretungsberechtigt. Gesamtprokura = Vier-Augen-Prinzip unter Prokuristen. Gemischte Prokura = zusammen mit einem Geschäftsführer oder Vorstand. Filialprokura = beschränkt auf eine Filiale."},en:{q:"Match each type of Prokura with its meaning.",p:[["Sole Prokura","represents alone"],["Joint Prokura","only together with other Prokuristen"],["Mixed Prokura","only together with a managing director/board"],["Branch Prokura","only for one particular branch"]],e:"Sole Prokura = may represent alone. Joint Prokura = four-eyes principle among Prokuristen. Mixed Prokura = together with a managing director or board member. Branch Prokura = limited to one branch."},hu:{q:"Párosítsd a prokúra egyes fajtáit a jelentésükkel.",p:[["Önálló prokúra","egyedül képvisel"],["Együttes prokúra","csak más prokuristákkal együtt"],["Vegyes prokúra","csak ügyvezetővel/igazgatósággal együtt"],["Fióktelepi prokúra","csak egy meghatározott fióktelepre"]],e:"Önálló prokúra = egyedül jogosult képviseletre. Együttes prokúra = négy szem elve a prokuristák között. Vegyes prokúra = ügyvezetővel vagy igazgatósági taggal együtt. Fióktelepi prokúra = egy fióktelepre korlátozva."}},{type:"mc",level:2,correctIndex:0,de:{q:"Lehrling Tim bekommt von seiner Chefin den Auftrag, einmalig einen neuen Drucker fürs Büro zu kaufen. Welche Vollmacht hat er und wie unterschreibt er?",o:["Spezialvollmacht – Unterschrift mit „i. A.“","Artvollmacht – Unterschrift mit „i. V.“","Generalvollmacht – Unterschrift mit „i. V.“","Einzelprokura – Unterschrift mit „ppa.“"],e:"Für eine einzelne Handlung genügt eine Spezialvollmacht (Einzelvollmacht); unterschrieben wird mit „i. A.“ (im Auftrag). „i. V.“ steht für die Generalvollmacht, „ppa.“ für die Prokura."},en:{q:"Apprentice Tim is asked by his boss to buy a new printer for the office, as a one-off. Which power of attorney does he have and how does he sign?",o:["Special power – signs with ‘i. A.’","Power for a type of deal – signs with ‘i. V.’","General power – signs with ‘i. V.’","Sole Prokura – signs with ‘ppa.’"],e:"A single act only requires a special power of attorney; the signature uses ‘i. A.’ (on behalf of). ‘i. V.’ is used for a general power of attorney, ‘ppa.’ for Prokura."},hu:{q:"Tim tanonc azt a megbízást kapja a főnökétől, hogy egyszeri alkalommal vegyen egy új nyomtatót az irodába. Milyen meghatalmazása van, és hogyan ír alá?",o:["Eseti meghatalmazás – „i. A.” aláírással","Ügyfajtára szóló meghatalmazás – „i. V.” aláírással","Általános meghatalmazás – „i. V.” aláírással","Önálló prokúra – „ppa.” aláírással"],e:"Egyetlen cselekményhez eseti meghatalmazás elegendő; az aláírás „i. A.” (megbízásból) toldattal történik. Az „i. V.” az általános meghatalmazásé, a „ppa.” a prokúráé."}},{type:"mc",level:3,correctIndex:3,de:{q:"Verkäuferin Mia hat eine Artvollmacht für Wareneinkäufe bis 5.000 €. Der Lieferant kennt diese Grenze. Mia bestellt trotzdem Ware um 8.000 €. Was gilt?",o:["Der Vertrag ist voll gültig, weil Beschränkungen nie gegen Dritte wirken","Der Vertrag gilt, weil Mia im Namen des Unternehmens unterschrieben hat","Der Vertrag gilt bis 5.000 €, der Rest muss automatisch storniert werden","Das Unternehmen ist nicht gebunden, weil der Lieferant die Grenze kannte"],e:"Anders als bei der Prokura wirken Beschränkungen der Handlungsvollmacht auch gegenüber Dritten, wenn diese davon wissen (müssten). Da der Lieferant die 5.000-€-Grenze kannte, bindet die Bestellung das Unternehmen nicht."},en:{q:"Sales assistant Mia has a power of attorney for purchasing goods up to €5,000. The supplier knows about this limit. Mia nevertheless orders goods worth €8,000. What applies?",o:["The contract is fully valid because restrictions never affect third parties","The contract is valid because Mia signed in the name of the business","The contract is valid up to €5,000; the rest is cancelled automatically","The business is not bound because the supplier knew the limit"],e:"Unlike with Prokura, restrictions on a commercial power of attorney also apply to third parties if they know (or should know) about them. As the supplier knew the €5,000 limit, the order does not bind the business."},hu:{q:"Mia eladónak ügyfajtára szóló meghatalmazása van 5 000 €-ig terjedő árubeszerzésekre. A beszállító ismeri ezt a korlátot. Mia mégis 8 000 € értékben rendel árut. Mi érvényes?",o:["A szerződés teljesen érvényes, mert a korlátozások sosem hatnak harmadik félre","A szerződés érvényes, mert Mia a vállalkozás nevében írta alá","A szerződés 5 000 €-ig érvényes, a többi automatikusan törlődik","A vállalkozást nem köti, mert a beszállító ismerte a korlátot"],e:"A prokúrától eltérően a kereskedelmi meghatalmazás korlátozásai harmadik személyekkel szemben is hatályosak, ha azok tudnak (vagy tudniuk kellene) róluk. Mivel a beszállító ismerte az 5 000 €-s korlátot, a rendelés nem köti a vállalkozást."}},{type:"text",level:1,de:{q:"Mit welcher Abkürzung unterschreibt jemand, der eine Generalvollmacht hat?",a:["i. V.","i.V.","iV","i V","in Vertretung"],e:"Generalvollmacht = „i. V.“ (in Vertretung). Art- und Spezialvollmacht = „i. A.“, Prokura = „pp.“ bzw. „ppa.“."},en:{q:"Which abbreviation does a holder of a general commercial power of attorney (Generalvollmacht) use when signing?",a:["i. V.","i.V.","iV","i V","in Vertretung"],e:"General power of attorney = ‘i. V.’ (in Vertretung, ‘as representative’). Power for a type of deal and special power = ‘i. A.’, Prokura = ‘pp.’ or ‘ppa.’."},hu:{q:"Milyen rövidítéssel ír alá az, akinek általános meghatalmazása van?",a:["i. V.","i.V.","iV","i V","in Vertretung"],e:"Általános meghatalmazás = „i. V.” (in Vertretung, azaz képviseletben). Ügyfajtára szóló és eseti meghatalmazás = „i. A.”, prokúra = „pp.” vagy „ppa.”."}}],beschaeftigungsverhaeltnisse:[{type:"tf",level:1,correct:!0,de:{q:"Ein freier Dienstnehmer darf sich bei der Arbeit grundsätzlich von einer anderen Person vertreten lassen",e:"Richtig. Weil keine persönliche Abhängigkeit besteht, ist beim freien Dienstvertrag eine Vertretung möglich. Im echten Arbeitsvertrag schuldet man dagegen die persönliche Arbeitskraft."},en:{q:"A freelance employee (freier Dienstnehmer) may in principle have another person stand in for them at work",e:"True. Since there is no personal dependence, substitution is possible under a freelance service contract. Under a ‘real’ employment contract, by contrast, the employee owes their personal labour."},hu:{q:"A szabad szolgálati szerződéssel foglalkoztatott személy alapvetően helyettesíttetheti magát a munkában egy másik személlyel",e:"Igaz. Mivel nincs személyes függőség, a szabad szolgálati szerződésnél a helyettesítés lehetséges. A „valódi” munkaszerződésnél ezzel szemben a munkavállaló a saját személyes munkavégzésével tartozik."}},{type:"tf",level:2,correct:!1,de:{q:"Freie Dienstnehmer:innen haben wie Angestellte Anspruch auf Sonderzahlungen (13. und 14. Gehalt)",e:"Falsch. Freie Dienstnehmer:innen bekommen nur das Entgelt für ihre Leistungen – kein Urlaubsentgelt, kein Krankengeld vom Arbeitgeber, keine Sonderzahlungen."},en:{q:"Like employees, freelance workers are entitled to special payments (13th and 14th salary)",e:"False. Freelance workers only receive payment for their services – no paid holiday, no sick pay from the employer and no special payments."},hu:{q:"A szabad szolgálati szerződéssel foglalkoztatottak az alkalmazottakhoz hasonlóan jogosultak különjuttatásokra (13. és 14. havi fizetés)",e:"Hamis. A szabad szolgálati szerződéssel foglalkoztatottak csak a teljesítményükért járó díjazást kapják – nincs fizetett szabadság, nincs munkáltatói táppénz és nincsenek különjuttatások."}},{type:"tf",level:3,correct:!1,de:{q:"Beim freien Dienstvertrag zieht der Auftraggeber die Lohnsteuer vom Entgelt ab und führt sie ans Finanzamt ab",e:"Falsch. Beim freien Dienstvertrag meldet der Auftraggeber zwar die Sozialversicherung (ÖGK) an, die Steuer muss der freie Dienstnehmer aber selbst über die Einkommensteuererklärung zahlen. Lohnsteuerabzug gibt es nur beim echten Arbeitsvertrag."},en:{q:"Under a freelance service contract, the client deducts wage tax from the pay and transfers it to the tax office",e:"False. Under a freelance service contract the client does register the worker for social insurance (ÖGK), but the worker pays tax themselves via an income tax return. Wage tax is only deducted under a ‘real’ employment contract."},hu:{q:"A szabad szolgálati szerződésnél a megbízó levonja a díjazásból a béradót, és befizeti az adóhivatalnak",e:"Hamis. A szabad szolgálati szerződésnél a megbízó ugyan bejelenti a dolgozót a társadalombiztosításhoz (ÖGK), az adót azonban a dolgozónak magának kell megfizetnie jövedelemadó-bevallással. Béradó-levonás csak a „valódi” munkaszerződésnél van."}},{type:"multi",level:2,correct:[0,1,2],de:{q:"Welche Merkmale sprechen für einen „echten“ Arbeitsvertrag? Wähle alle zutreffenden.",o:["Der Arbeitgeber gibt fixe Arbeitszeiten vor","Arbeitsmittel werden vom Arbeitgeber gestellt","Die Person muss den Anordnungen des Vorgesetzten folgen","Die Person trägt ein eigenes unternehmerisches Risiko","Geschuldet wird ein fertiges Werk","Die Person kann sich jederzeit vertreten lassen"],e:"Typisch für den echten Arbeitsvertrag sind persönliche Abhängigkeit: Weisungen, fixe Zeit und fixer Ort, Arbeitsmittel vom Arbeitgeber, kein eigenes Risiko. Werk und eigenes Risiko deuten auf einen Werkvertrag, Vertretung auf einen freien Dienstvertrag."},en:{q:"Which features indicate a ‘real’ employment contract? Select all that apply.",o:["The employer sets fixed working hours","Work equipment is provided by the employer","The person must follow the supervisor's instructions","The person bears their own entrepreneurial risk","A finished piece of work is owed","The person can have someone stand in for them at any time"],e:"A ‘real’ employment contract is characterised by personal dependence: instructions, fixed time and place, equipment from the employer, no own risk. A finished work and own risk point to a contract for work, substitution to a freelance service contract."},hu:{q:"Mely jellemzők utalnak „valódi” munkaszerződésre? Jelöld meg az összes helyeset.",o:["A munkáltató rögzített munkaidőt ír elő","A munkaeszközöket a munkáltató biztosítja","A személynek követnie kell a felettese utasításait","A személy saját vállalkozói kockázatot visel","Egy kész mű elkészítésével tartozik","A személy bármikor helyettesíttetheti magát"],e:"A „valódi” munkaszerződésre a személyes függőség jellemző: utasítások, rögzített idő és hely, munkáltatói munkaeszközök, nincs saját kockázat. A kész mű és a saját kockázat vállalkozási szerződésre, a helyettesítés szabad szolgálati szerződésre utal."}},{type:"multi",level:3,correct:[0,1,2],de:{q:"Welche Aussagen treffen sowohl auf den freien Dienstvertrag als auch auf den Werkvertrag zu? Wähle alle zutreffenden.",o:["Keine Bindung an Weisungen des Auftraggebers","Kein Anspruch auf bezahlten Urlaub","Die Steuer wird selbst über die Einkommensteuererklärung bezahlt","Die Arbeitsmittel werden selbst beschafft","Der Auftraggeber meldet die Person bei der ÖGK an","Es besteht eine Gewährleistungspflicht für das Ergebnis"],e:"Gemeinsam sind: keine Weisungsbindung, kein Urlaub/keine Sonderzahlungen, Steuer selbst. Nur beim Werkvertrag gilt: eigene Arbeitsmittel, Versicherung selbst bei der SVS und Gewährleistung. Nur beim freien Dienstvertrag meldet der Auftraggeber bei der ÖGK an."},en:{q:"Which statements apply to BOTH the freelance service contract and the contract for work? Select all that apply.",o:["No obligation to follow the client's instructions","No entitlement to paid holiday","Tax is paid by the person themselves via an income tax return","The person provides their own work equipment","The client registers the person with the ÖGK","There is a warranty obligation for the result"],e:"Common to both: no instructions, no holiday/special payments, tax paid by oneself. Only for the contract for work: own equipment, self-insurance with the SVS and warranty. Only for the freelance service contract does the client register with the ÖGK."},hu:{q:"Mely állítások igazak MIND a szabad szolgálati szerződésre, MIND a vállalkozási szerződésre? Jelöld meg az összes helyeset.",o:["Nincs kötöttség a megbízó utasításaihoz","Nincs jogosultság fizetett szabadságra","Az adót a személy maga fizeti meg jövedelemadó-bevallással","A munkaeszközöket a személy maga szerzi be","A megbízó jelenti be a személyt az ÖGK-nál","Az eredményért szavatossági kötelezettség áll fenn"],e:"Közös: nincs utasításhoz kötöttség, nincs szabadság/különjuttatás, az adót maga fizeti. Csak a vállalkozási szerződésnél: saját munkaeszközök, saját biztosítás az SVS-nél és szavatosság. Csak a szabad szolgálati szerződésnél jelenti be a megbízó az ÖGK-nál."}},{type:"match",level:1,de:{q:"Ordne jedes Beispiel dem passenden Beschäftigungsverhältnis zu.",p:[["Website-Gestaltung um 12.000 € pauschal","Werkvertrag"],["Dateneingabe von zu Hause, Zeit frei einteilbar","Freier Dienstvertrag"],["Bürokauffrau, 38,5 Std. pro Woche im Büro","„Echter“ Arbeitsvertrag"],["Aushilfe mit Entgelt unter der Geringfügigkeitsgrenze","Geringfügige Beschäftigung"]],e:"Ein fertiges Werk = Werkvertrag. Arbeitskraft ohne Weisungen, Zeit und Ort frei = freier Dienstvertrag. Weisungen, fixe Zeit und fixer Ort = echter Arbeitsvertrag. Entgelt unter der Grenze = geringfügige Beschäftigung."},en:{q:"Match each example to the right type of employment.",p:[["Designing a website for a flat €12,000","Contract for work"],["Data entry from home, own working hours","Freelance service contract"],["Office clerk, 38.5 hours a week in the office","‘Real’ employment contract"],["Temp whose pay is below the marginal earnings threshold","Marginal employment"]],e:"A finished work = contract for work. Labour without instructions, free time and place = freelance service contract. Instructions, fixed time and place = ‘real’ employment contract. Pay below the threshold = marginal employment."},hu:{q:"Párosítsd az egyes példákat a megfelelő foglalkoztatási formával.",p:[["Weboldal elkészítése 12 000 € átalányért","Vállalkozási szerződés"],["Otthoni adatbevitel, szabadon beosztható idő","Szabad szolgálati szerződés"],["Irodai ügyintéző, heti 38,5 óra az irodában","„Valódi” munkaszerződés"],["Kisegítő, akinek díjazása a határ alatt van","Csekély mértékű foglalkoztatás"]],e:"Kész mű = vállalkozási szerződés. Munkavégzés utasítások nélkül, szabad idővel és hellyel = szabad szolgálati szerződés. Utasítások, rögzített idő és hely = „valódi” munkaszerződés. A határ alatti díjazás = csekély mértékű foglalkoztatás."}},{type:"mc",level:2,correctIndex:0,de:{q:"Malermeister Huber streicht um einen Pauschalpreis von 8.000 € die Räume einer Bankfiliale – mit eigenem Werkzeug und zu selbst gewählten Zeiten. Zwei Wochen später zeigen sich Risse in der Farbe. Was gilt?",o:["Werkvertrag – Huber muss im Rahmen der Gewährleistung nachbessern","Freier Dienstvertrag – Huber erhält das Entgelt ohne Nachbesserung","Echter Arbeitsvertrag – die Bank trägt das Risiko für Mängel","Freier Dienstvertrag – die Bank muss ihn bei der ÖGK anmelden"],e:"Geschuldet ist ein fertiges Werk (gestrichene Räume) mit eigenen Mitteln und eigenem Risiko → Werkvertrag. Dazu gehört die Gewährleistung: Bei Mängeln muss Huber nachbessern."},en:{q:"Master painter Huber paints the rooms of a bank branch for a flat price of €8,000 – with his own tools and at times he chooses himself. Two weeks later cracks appear in the paint. What applies?",o:["Contract for work – Huber must repair the defects under warranty","Freelance contract – Huber gets paid without having to repair anything","‘Real’ employment contract – the bank bears the risk of defects","Freelance contract – the bank must register him with the ÖGK"],e:"A finished work (painted rooms) is owed, using his own means and at his own risk → contract for work. This includes warranty: if there are defects, Huber must repair them."},hu:{q:"Huber festőmester 8 000 €-s átalányárért kifesti egy bankfiók helyiségeit – saját szerszámmal és maga választotta időben. Két héttel később repedések jelennek meg a festékben. Mi érvényes?",o:["Vállalkozási szerződés – Hubernek szavatosság keretében javítania kell","Szabad szolgálati szerződés – Huber javítás nélkül megkapja a díjat","„Valódi” munkaszerződés – a bank viseli a hibák kockázatát","Szabad szolgálati szerződés – a banknak be kell jelentenie őt az ÖGK-nál"],e:"Kész művel tartozik (kifestett helyiségek), saját eszközökkel és saját kockázatra → vállalkozási szerződés. Ehhez szavatosság tartozik: hiba esetén Hubernek javítania kell."}},{type:"mc",level:2,correctIndex:1,de:{q:"Eine Webdesignerin soll für Loopys Candy Store bis 30. Juni einen fertigen Onlineshop um 5.000 € pauschal erstellen – mit ihrem eigenen Laptop. Was muss sie bei diesem Vertrag selbst erledigen?",o:["Nichts – Loopy meldet sie bei der ÖGK an und zieht ihr die Lohnsteuer ab","Sie versichert sich selbst bei der SVS und versteuert das Honorar selbst","Nur die Steuer – die Sozialversicherung meldet Loopy bei der ÖGK an","Nur die Versicherung – die Lohnsteuer zieht Loopy vom Honorar ab"],e:"Ein fertiger Onlineshop zu einem Pauschalpreis ist ein Werkvertrag. Werkvertragsnehmer:innen versichern sich selbst bei der SVS und zahlen ihre Steuer selbst. Die ÖGK-Anmeldung durch den Auftraggeber gibt es beim echten und beim freien Dienstvertrag."},en:{q:"A web designer is to build a finished online shop for Loopy's Candy Store by 30 June for a flat €5,000 – using her own laptop. What does she have to take care of herself under this contract?",o:["Nothing – Loopy registers her with the ÖGK and deducts wage tax","She insures herself with the SVS and pays tax on the fee herself","Only the tax – Loopy registers her with the ÖGK for social insurance","Only the insurance – Loopy deducts wage tax from the fee"],e:"A finished online shop for a flat price is a contract for work. Contractors insure themselves with the SVS and pay their own tax. Registration with the ÖGK by the client applies to ‘real’ employment and freelance service contracts."},hu:{q:"Egy webdizájnernek június 30-ig kész webáruházat kell készítenie Loopy Candy Store-ja számára 5 000 €-s átalányért – a saját laptopjával. Mit kell ennél a szerződésnél magának intéznie?",o:["Semmit – Loopy bejelenti őt az ÖGK-nál és levonja a béradót","Saját magát biztosítja az SVS-nél, és maga adózik a díj után","Csak az adót – a társadalombiztosításhoz Loopy jelenti be az ÖGK-nál","Csak a biztosítást – a béradót Loopy vonja le a díjból"],e:"Egy kész webáruház átalányárért vállalkozási szerződés. A vállalkozók maguk biztosítják magukat az SVS-nél, és maguk fizetik az adójukat. A megbízó általi ÖGK-bejelentés a „valódi” munkaszerződésnél és a szabad szolgálati szerződésnél van."}},{type:"mc",level:3,correctIndex:2,de:{q:"Lena hat mit einer Tischlerei einen „freien Dienstvertrag“ unterschrieben. Tatsächlich muss sie täglich von 8 bis 17 Uhr in der Werkstatt sein, den Anweisungen des Meisters folgen und darf sich nicht vertreten lassen. Wie ist das Verhältnis zu beurteilen?",o:["Als freier Dienstvertrag, weil das so im Vertrag steht","Als Werkvertrag, weil sie fertige Möbelstücke herstellt und abliefert","Als echter Arbeitsvertrag, weil die tatsächlichen Merkmale zählen","Als geringfügige Beschäftigung, weil sie keine Angestellte ist"],e:"Entscheidend ist nicht die Bezeichnung, sondern wie die Arbeit tatsächlich abläuft. Fixe Zeit, fixer Ort, Weisungen und keine Vertretung = persönliche Abhängigkeit → echter Arbeitsvertrag mit allen Ansprüchen (Urlaub, Sonderzahlungen, Lohnsteuerabzug)."},en:{q:"Lena signed a ‘freelance service contract’ with a joinery. In fact she has to be in the workshop daily from 8 am to 5 pm, follow the master's instructions and may not send a substitute. How should the relationship be assessed?",o:["As a freelance service contract, because that is what the contract says","As a contract for work, because she makes furniture","As a ‘real’ employment contract, because the actual features count","As marginal employment, because she is not an employee"],e:"What matters is not the label but how the work is actually done. Fixed hours, fixed place, instructions and no substitution = personal dependence → ‘real’ employment contract with all entitlements (holiday, special payments, wage tax deduction)."},hu:{q:"Lena „szabad szolgálati szerződést” írt alá egy asztalosműhellyel. Valójában naponta 8 és 17 óra között a műhelyben kell lennie, követnie kell a mester utasításait, és nem helyettesíttetheti magát. Hogyan kell megítélni a jogviszonyt?",o:["Szabad szolgálati szerződésként, mert ez áll a szerződésben","Vállalkozási szerződésként, mert bútorokat készít","„Valódi” munkaszerződésként, mert a tényállás dönt","Csekély mértékű foglalkoztatásként, mert nem alkalmazott"],e:"Nem a megnevezés a döntő, hanem az, hogyan zajlik ténylegesen a munka. Rögzített idő, rögzített hely, utasítások és helyettesítés kizárása = személyes függőség → „valódi” munkaszerződés minden jogosultsággal (szabadság, különjuttatások, béradó-levonás)."}},{type:"text",level:1,de:{q:"Bei welcher Sozialversicherung müssen sich Werkvertragsnehmer:innen selbst versichern? (Abkürzung)",a:["SVS","Sozialversicherungsanstalt der Selbständigen","Sozialversicherung der Selbständigen"],e:"Werkvertragsnehmer:innen versichern sich selbst bei der SVS (Sozialversicherungsanstalt der Selbständigen). Echte und freie Dienstnehmer:innen meldet der Arbeitgeber bei der ÖGK an."},en:{q:"With which social insurance institution do contractors under a contract for work have to insure themselves? (abbreviation)",a:["SVS","Sozialversicherungsanstalt der Selbständigen","social insurance for the self-employed"],e:"Contractors insure themselves with the SVS (social insurance institution for the self-employed). Employees and freelance workers are registered with the ÖGK by the employer."},hu:{q:"Melyik társadalombiztosítónál kell a vállalkozási szerződéssel dolgozóknak saját magukat biztosítaniuk? (rövidítés)",a:["SVS","Sozialversicherungsanstalt der Selbständigen","önálló vállalkozók társadalombiztosítója"],e:"A vállalkozók az SVS-nél (az önálló vállalkozók társadalombiztosítója) biztosítják magukat. A munkavállalókat és a szabad szolgálati szerződéssel foglalkoztatottakat a munkáltató jelenti be az ÖGK-nál."}}],"kaufvertraege-aussenhandel":[{type:"tf",level:1,correct:!1,de:{q:"Incoterms regeln auch, wann und auf welche Weise der Käufer bezahlen muss",e:"Falsch. Incoterms regeln Risiko- und Kostenübergang, Transportmittel/-dokumente sowie Aus-, Durch- und Einfuhr – aber NICHT Zahlungsmodalitäten, Vertragsverletzungen oder das anwendbare Recht."},en:{q:"Incoterms also determine when and how the buyer has to pay",e:"False. Incoterms govern the transfer of risk and costs, transport and documents, and export, transit and import formalities – but NOT payment terms, breaches of contract or the applicable law."},hu:{q:"Az Incoterms azt is szabályozza, hogy a vevőnek mikor és milyen módon kell fizetnie",e:"Hamis. Az Incoterms a kockázat- és költségátszállást, a szállítóeszközöket/okmányokat, valamint a kiviteli, átmenő és behozatali ügyintézést szabályozza – a fizetési feltételeket, a szerződésszegést és az alkalmazandó jogot NEM."}},{type:"tf",level:2,correct:!0,de:{q:"Bei CIF zahlt der Verkäufer Fracht und Versicherung bis zum Bestimmungshafen, das Risiko geht aber schon mit der Verladung an Bord auf den Käufer über",e:"Richtig. CIF ist eine C-Klausel und damit eine Zweipunktklausel: Das Risiko geht früh (an Bord im Verschiffungshafen) über, die Kosten trägt der Verkäufer bis zum Bestimmungshafen."},en:{q:"Under CIF the seller pays freight and insurance to the port of destination, but the risk passes to the buyer as soon as the goods are loaded on board",e:"True. CIF is a C clause and therefore a two-point clause: the risk passes early (on board at the port of shipment), while the seller bears the costs up to the port of destination."},hu:{q:"CIF esetén az eladó fizeti a fuvardíjat és a biztosítást a rendeltetési kikötőig, a kockázat azonban már a hajóra rakodáskor átszáll a vevőre",e:"Igaz. A CIF C-klauzula, tehát kétpontos klauzula: a kockázat korán (a berakodási kikötőben a hajó fedélzetén) száll át, a költségeket viszont az eladó viseli a rendeltetési kikötőig."}},{type:"tf",level:3,correct:!1,de:{q:"Beim Dokumentenakkreditiv prüft die Bank vor der Zahlung, ob die gelieferte Ware mangelfrei ist",e:"Falsch. Banken prüfen ausschließlich die Dokumente, nicht die Ware. Stimmen die Dokumente mit den Akkreditivbedingungen überein, wird gezahlt – auch wenn die Ware Mängel hat."},en:{q:"With a documentary letter of credit, the bank checks before payment whether the delivered goods are free of defects",e:"False. Banks only examine the documents, not the goods. If the documents comply with the terms of the letter of credit, payment is made – even if the goods are defective."},hu:{q:"Okmányos meghitelezésnél a bank a fizetés előtt ellenőrzi, hogy a leszállított áru hibátlan-e",e:"Hamis. A bankok kizárólag az okmányokat vizsgálják, az árut nem. Ha az okmányok megfelelnek az akkreditív feltételeinek, fizetnek – akkor is, ha az áru hibás."}},{type:"multi",level:1,correct:[0,1,2,3],de:{q:"Welche Incoterms-Klauseln dürfen nur für den Transport per Schiff verwendet werden? Wähle alle zutreffenden.",o:["FAS","FOB","CFR","CIF","CPT","DAP"],e:"FAS, FOB, CFR und CIF sind reine See- und Binnenschiffsklauseln. CPT und DAP (wie auch EXW, FCA, CIP, DPU, DDP) passen für alle Transportarten."},en:{q:"Which Incoterms clauses may only be used for transport by ship? Select all that apply.",o:["FAS","FOB","CFR","CIF","CPT","DAP"],e:"FAS, FOB, CFR and CIF are pure sea and inland waterway clauses. CPT and DAP (like EXW, FCA, CIP, DPU, DDP) are suitable for any mode of transport."},hu:{q:"Mely Incoterms-klauzulák használhatók kizárólag hajós szállításnál? Jelöld meg az összes helyeset.",o:["FAS","FOB","CFR","CIF","CPT","DAP"],e:"Az FAS, FOB, CFR és CIF tisztán tengeri és belvízi klauzulák. A CPT és a DAP (ahogy az EXW, FCA, CIP, DPU, DDP is) minden szállítási módhoz alkalmas."}},{type:"multi",level:3,correct:[0,1,2],de:{q:"Welche Maßnahmen sichern einen Exporteur gegen das Zahlungsausfallrisiko ab? Wähle alle zutreffenden.",o:["Anzahlung durch den Importeur","Staatliche Exportgarantie (OeKB)","Dokumentenakkreditiv","Devisentermingeschäft","Pönale im Kaufvertrag","Dokumenteninkasso"],e:"Anzahlung, Exportgarantie und Akkreditiv (Zahlungsversprechen einer Bank) schützen vor Zahlungsausfall. Ein Devisentermingeschäft sichert nur den Wechselkurs, eine Pönale schützt den Käufer, und beim Inkasso geben Banken keine Zahlungsgarantie."},en:{q:"Which measures protect an exporter against the risk of non-payment? Select all that apply.",o:["Down payment by the importer","State export guarantee (OeKB)","Documentary letter of credit","Forward exchange contract","Contractual penalty in the sales contract","Documentary collection"],e:"A down payment, an export guarantee and a letter of credit (a bank's promise to pay) protect against non-payment. A forward exchange contract only secures the exchange rate, a penalty protects the buyer, and with a documentary collection banks give no payment guarantee."},hu:{q:"Mely intézkedések védik az exportőrt a nemfizetési kockázat ellen? Jelöld meg az összes helyeset.",o:["Előleg az importőrtől","Állami exportgarancia (OeKB)","Okmányos meghitelezés","Határidős devizaügylet","Kötbér az adásvételi szerződésben","Okmányos beszedés"],e:"Az előleg, az exportgarancia és az akkreditív (egy bank fizetési ígérete) véd a nemfizetés ellen. A határidős devizaügylet csak az árfolyamot biztosítja, a kötbér a vevőt védi, okmányos beszedésnél pedig a bankok nem vállalnak fizetési garanciát."}},{type:"order",level:3,de:{q:"Bringe den Ablauf eines Dokumentenakkreditivs in die richtige Reihenfolge.",o:["Kaufvertrag mit Zahlung per Akkreditiv wird abgeschlossen","Käufer beauftragt seine Bank (Akkreditivbank)","Akkreditivbank schickt die Eröffnungsanzeige an die Bank des Verkäufers","Verkäufer wird über das eröffnete Akkreditiv informiert","Verkäufer versendet die Ware und reicht die Dokumente bei seiner Bank ein","Verkäufer erhält nach Prüfung der Dokumente sein Geld","Käufer zahlt und erhält die Dokumente – und damit die Verfügung über die Ware"],e:"Erst wenn das Akkreditiv eröffnet und dem Verkäufer avisiert ist, versendet er die Ware. Gezahlt wird gegen ordnungsgemäße Dokumente; der Käufer kommt erst mit den Dokumenten an die Ware."},en:{q:"Put the steps of a documentary letter of credit in the correct order.",o:["A sales contract with payment by letter of credit is concluded","The buyer instructs his bank (issuing bank)","The issuing bank sends the opening notice to the seller's bank","The seller is informed about the opened letter of credit","The seller ships the goods and submits the documents to his bank","After the documents are checked, the seller receives his money","The buyer pays and receives the documents – and thus control of the goods"],e:"Only once the letter of credit has been opened and advised to the seller does he ship the goods. Payment is made against compliant documents; the buyer only gets the goods with the documents."},hu:{q:"Állítsd helyes sorrendbe az okmányos meghitelezés lépéseit.",o:["Akkreditíves fizetéssel adásvételi szerződést kötnek","A vevő megbízza a bankját (akkreditívet nyitó bank)","A nyitó bank megküldi a nyitási értesítést az eladó bankjának","Az eladót értesítik a megnyitott akkreditívről","Az eladó elküldi az árut, és benyújtja az okmányokat a bankjának","Az okmányok ellenőrzése után az eladó megkapja a pénzét","A vevő fizet, és megkapja az okmányokat – ezzel az áru feletti rendelkezést"],e:"Az eladó csak akkor küldi el az árut, amikor az akkreditívet megnyitották és értesítették róla. A fizetés szabályos okmányok ellenében történik; a vevő csak az okmányokkal jut hozzá az áruhoz."}},{type:"match",level:1,de:{q:"Ordne jedem Transportmittel das passende Transportdokument zu.",p:[["Lkw","Straßenfrachtbrief (CMR)"],["Flugzeug","Luftfrachtbrief"],["Schiff (Meer)","Seekonnossement (Bill of Lading)"],["Schiff (Binnengewässer)","Flusskonnossement"],["Eisenbahn","Internationaler Eisenbahnfrachtbrief"]],e:"Jedes Transportmittel hat sein eigenes Frachtdokument. Bei mehreren Transportmitteln verwendet man das FIATA Multimodal Transport Bill of Lading."},en:{q:"Match each means of transport with the right transport document.",p:[["Lorry","Road consignment note (CMR)"],["Aircraft","Air waybill"],["Ship (sea)","Ocean bill of lading"],["Ship (inland waters)","Inland waterway bill of lading"],["Rail","International rail consignment note"]],e:"Each means of transport has its own transport document. For several means of transport, the FIATA Multimodal Transport Bill of Lading is used."},hu:{q:"Párosítsd az egyes szállítóeszközöket a megfelelő fuvarokmánnyal.",p:[["Kamion","Közúti fuvarlevél (CMR)"],["Repülőgép","Légi fuvarlevél"],["Hajó (tengeri)","Tengeri hajóraklevél (Bill of Lading)"],["Hajó (belvízi)","Belvízi hajóraklevél"],["Vasút","Nemzetközi vasúti fuvarlevél"]],e:"Minden szállítóeszköznek saját fuvarokmánya van. Több szállítóeszköz esetén a FIATA multimodális hajóraklevelet (FIATA Multimodal Transport Bill of Lading) használják."}},{type:"mc",level:2,correctIndex:0,de:{q:"Ein Schweizer Kunde will bei Loopy Pralinen bestellen. Für seine Importgenehmigung braucht er schon VOR der Lieferung ein Dokument mit Preis und Menge, das noch keine Zahlungspflicht auslöst. Welches Dokument schickt Loopy?",o:["Pro-Forma-Rechnung","Handelsrechnung (Faktura)","Ursprungszeugnis","Warenverkehrsbescheinigung"],e:"Die Pro-Forma-Rechnung wird vor der Lieferung ausgestellt, löst keine Zahlungspflicht aus und dient z. B. für Zoll oder Importgenehmigung. Die Handelsrechnung bestätigt den tatsächlichen Verkauf, das Ursprungszeugnis die Herkunft."},en:{q:"A Swiss customer wants to order chocolates from Loopy. For his import licence he needs, BEFORE delivery, a document stating price and quantity that does not yet create an obligation to pay. Which document does Loopy send?",o:["Pro forma invoice","Commercial invoice","Certificate of origin","Movement certificate"],e:"A pro forma invoice is issued before delivery, creates no obligation to pay and is used e.g. for customs or import licences. The commercial invoice confirms the actual sale, the certificate of origin the country of origin."},hu:{q:"Egy svájci vevő bonbont szeretne rendelni Loopytól. A behozatali engedélyéhez már a szállítás ELŐTT szüksége van egy árat és mennyiséget tartalmazó okmányra, amely még nem keletkeztet fizetési kötelezettséget. Melyik okmányt küldi Loopy?",o:["Proforma számla","Kereskedelmi számla","Származási bizonyítvány","Szállítási bizonyítvány"],e:"A proforma számlát a szállítás előtt állítják ki, nem keletkeztet fizetési kötelezettséget, és pl. vámhoz vagy behozatali engedélyhez használják. A kereskedelmi számla a tényleges eladást igazolja, a származási bizonyítvány az áru eredetét."}},{type:"mc",level:3,correctIndex:0,de:{q:"Loopy (Graz) verkauft Pralinen an einen Händler in Mailand, Lieferbedingung „CPT Mailand“. Der Lkw des Frachtführers verunglückt noch in Kärnten, die Ware ist zerstört. Wer trägt den Schaden?",o:["Der Käufer, da das Risiko schon beim 1. Frachtführer überging","Loopy, weil sie die Frachtkosten bis Mailand bezahlt hat","Loopy, weil das Risiko erst am Bestimmungsort Mailand übergeht","Beide je zur Hälfte, weil sich Kosten und Risiko aufteilen"],e:"CPT ist eine Zweipunktklausel: Loopy zahlt die Fracht bis Mailand, das Risiko geht aber schon mit der Übergabe an den ersten Frachtführer auf den Käufer über. Wer zahlt, trägt also nicht automatisch das Risiko."},en:{q:"Loopy (Graz) sells chocolates to a retailer in Milan, delivery term ‘CPT Milan’. The carrier's lorry crashes while still in Carinthia and the goods are destroyed. Who bears the loss?",o:["The buyer, as the risk already passed at the first carrier","Loopy, because she paid for transport to Milan","Loopy, because the risk only passes at the destination, Milan","Both half each, because costs and risk are split"],e:"CPT is a two-point clause: Loopy pays the freight to Milan, but the risk passes to the buyer on handover to the first carrier. Paying for transport does not automatically mean bearing the risk."},hu:{q:"Loopy (Graz) bonbont ad el egy milánói kereskedőnek „CPT Milánó” szállítási feltétellel. A fuvarozó kamionja még Karintiában balesetet szenved, az áru megsemmisül. Ki viseli a kárt?",o:["A vevő, mert a kockázat már az első fuvarozónál átszállt","Loopy, mert ő fizette a szállítást Milánóig","Loopy, mert a kockázat csak a rendeltetési helyen, Milánóban száll át","Mindketten fele-fele arányban, mert a költség és a kockázat megoszlik"],e:"A CPT kétpontos klauzula: Loopy fizeti a fuvardíjat Milánóig, a kockázat azonban már az első fuvarozónak való átadáskor átszáll a vevőre. Aki fizeti a szállítást, nem feltétlenül viseli a kockázatot is."}},{type:"number",level:2,value:5454.55,tol:.5,unit:{de:"€",en:"€",hu:"€"},de:{q:"Ein österreichischer Exporteur verkauft Maschinen um 50.000 USD, zahlbar in 3 Monaten. Bei Vertragsabschluss gilt 1 € = 1,10 USD, am Zahlungstag 1 € = 1,25 USD. Wie hoch ist sein Kursverlust in Euro (ohne Kurssicherung)?",e:"Erwartet: 50.000 / 1,10 = 45.454,55 €. Erhalten: 50.000 / 1,25 = 40.000,00 €. Kursverlust = 45.454,55 − 40.000,00 = 5.454,55 €. Absichern hätte er sich mit einem Devisentermingeschäft können."},en:{q:"An Austrian exporter sells machines for USD 50,000, payable in 3 months. When the contract is signed, €1 = USD 1.10; on the payment date €1 = USD 1.25. How large is his exchange loss in euros (without hedging)?",e:"Expected: 50,000 / 1.10 = €45,454.55. Received: 50,000 / 1.25 = €40,000.00. Exchange loss = 45,454.55 − 40,000.00 = €5,454.55. He could have hedged with a forward exchange contract."},hu:{q:"Egy osztrák exportőr 50 000 USD-ért gépeket ad el, 3 hónapos fizetési határidővel. A szerződéskötéskor 1 € = 1,10 USD, a fizetés napján 1 € = 1,25 USD. Mekkora az árfolyamvesztesége euróban (árfolyam-fedezet nélkül)?",e:"Várt összeg: 50 000 / 1,10 = 45 454,55 €. Kapott összeg: 50 000 / 1,25 = 40 000,00 €. Árfolyamveszteség = 45 454,55 − 40 000,00 = 5 454,55 €. Határidős devizaügylettel fedezhette volna magát."}}],"grundlagen-leistungserstellung-2jg":[{type:"tf",level:1,correct:!0,de:{q:"Rohstoffe und Handelswaren gehören zum Umlaufvermögen, Gebäude und Maschinen zum Anlagevermögen",e:"Richtig. Das Betriebsvermögen besteht aus Anlagevermögen (bleibt lange im Betrieb, z. B. Gebäude, Maschinen) und Umlaufvermögen (wird verbraucht oder verkauft, z. B. Rohstoffe, Handelswaren)."},en:{q:"Raw materials and merchandise belong to current assets, buildings and machines to fixed assets",e:"True. Business assets consist of fixed assets (stay in the business for a long time, e.g. buildings, machines) and current assets (used up or sold, e.g. raw materials, merchandise)."},hu:{q:"A nyersanyagok és a kereskedelmi áruk a forgóeszközökhöz, az épületek és a gépek a befektetett eszközökhöz tartoznak",e:"Igaz. Az üzemi vagyon befektetett eszközökből (hosszú ideig az üzemben maradnak, pl. épületek, gépek) és forgóeszközökből (felhasználják vagy eladják őket, pl. nyersanyagok, kereskedelmi áruk) áll."}},{type:"tf",level:2,correct:!1,de:{q:"Steigt die Produktivität eines Betriebs, arbeitet er automatisch auch wirtschaftlicher",e:"Falsch. Produktivität misst Mengen, Wirtschaftlichkeit Werte (Erlöse/Kosten). Eine neue Maschine kann mehr Stück pro Stunde schaffen, aber so teuer sein, dass die Kosten stärker steigen als die Erlöse."},en:{q:"If a firm's productivity rises, it automatically becomes more economically efficient as well",e:"False. Productivity measures quantities, economic efficiency measures values (revenue/costs). A new machine may produce more units per hour but be so expensive that costs rise faster than revenue."},hu:{q:"Ha egy üzem termelékenysége nő, automatikusan gazdaságosabban is működik",e:"Hamis. A termelékenység mennyiségeket mér, a gazdaságosság értékeket (árbevétel/költség). Egy új gép több darabot gyárthat óránként, de olyan drága lehet, hogy a költségek jobban nőnek, mint az árbevétel."}},{type:"tf",level:2,correct:!1,de:{q:"Eine Wirtschaftlichkeit von genau 1 bedeutet, dass das Unternehmen 1 % Gewinn erzielt",e:"Falsch. Bei einer Wirtschaftlichkeit von 1 sind Erlöse und Kosten gleich hoch – das Unternehmen arbeitet kostendeckend, also ohne Gewinn und ohne Verlust. Gewinn gibt es erst ab einem Wert über 1."},en:{q:"An economic efficiency of exactly 1 means the company makes a profit of 1%",e:"False. At an economic efficiency of 1, revenue and costs are equal – the company just covers its costs, with neither profit nor loss. There is only a profit if the value is above 1."},hu:{q:"A pontosan 1-es gazdaságosság azt jelenti, hogy a vállalkozás 1% nyereséget ér el",e:"Hamis. 1-es gazdaságosságnál az árbevétel és a költség egyenlő – a vállalkozás költségfedezeti szinten működik, sem nyereség, sem veszteség nincs. Nyereség csak 1 feletti értéknél keletkezik."}},{type:"multi",level:1,correct:[0,1,4],de:{q:"Welche Maßnahmen gehören zur ökologischen Dimension der Nachhaltigkeit? Wähle alle zutreffenden.",o:["Eigene Photovoltaikanlage am Hallendach","Verpackungsmüll deutlich reduzieren","Faire Löhne für alle Mitarbeiter:innen","Gewinne erwirtschaften, um neue Anlagen zu kaufen","Produkte nach dem Cradle-to-Cradle-Prinzip herstellen"],e:"Ökologisch = Ressourcen schonen, wenig Emissionen und Abfall (Solarstrom, weniger Müll, Kreislaufwirtschaft). Faire Löhne gehören zur sozialen, Gewinne für Investitionen zur ökonomischen Dimension."},en:{q:"Which measures belong to the ecological dimension of sustainability? Select all that apply.",o:["Own photovoltaic system on the factory roof","Significantly reducing packaging waste","Fair wages for all employees","Making profits in order to buy new equipment","Manufacturing products according to the cradle-to-cradle principle"],e:"Ecological = saving resources, few emissions and little waste (solar power, less waste, circular economy). Fair wages belong to the social dimension, profits for investment to the economic one."},hu:{q:"Mely intézkedések tartoznak a fenntarthatóság ökológiai dimenziójához? Jelöld meg az összes helyeset.",o:["Saját napelemes rendszer a csarnok tetején","A csomagolási hulladék jelentős csökkentése","Tisztességes bér minden munkatársnak","Nyereség termelése új berendezések vásárlására","Termékek gyártása a cradle-to-cradle elv szerint"],e:"Ökológiai = erőforrások kímélése, kevés kibocsátás és hulladék (napenergia, kevesebb szemét, körforgásos gazdaság). A tisztességes bér a társadalmi, az új beruházásokra fordított nyereség a gazdasági dimenzióhoz tartozik."}},{type:"multi",level:3,correct:[0,1,2],de:{q:"Welche Kennzahlen werden mit Mengen bzw. Stückzahlen berechnet und NICHT mit Euro-Werten? Wähle alle zutreffenden.",o:["Produktivität","Termintreue","Produktqualität","Wirtschaftlichkeit","Rentabilität"],e:"Produktivität (Output/Input in Stück, Stunden), Termintreue (Aufträge) und Produktqualität (Güter) rechnen mit Mengen. Wirtschaftlichkeit (Erlöse/Kosten) und Rentabilität (Gewinn/Kapital) rechnen mit Euro-Werten."},en:{q:"Which ratios are calculated with quantities or numbers of units and NOT with euro values? Select all that apply.",o:["Productivity","On-time delivery rate","Product quality","Economic efficiency","Return on capital"],e:"Productivity (output/input in units, hours), on-time delivery (orders) and product quality (goods) use quantities. Economic efficiency (revenue/costs) and return on capital (profit/capital) use euro values."},hu:{q:"Mely mutatókat számítják mennyiségekkel, illetve darabszámokkal, és NEM euróértékekkel? Jelöld meg az összes helyeset.",o:["Termelékenység","Határidő-pontosság","Termékminőség","Gazdaságosság","Jövedelmezőség"],e:"A termelékenység (output/input darabban, órában), a határidő-pontosság (megrendelések) és a termékminőség (termékek) mennyiségekkel számol. A gazdaságosság (árbevétel/költség) és a jövedelmezőség (nyereség/tőke) euróértékekkel."}},{type:"order",level:1,de:{q:"Bringe den betrieblichen Leistungsprozess in die richtige Reihenfolge.",o:["Beschaffungsmarkt","Beschaffung","Produktion","Absatz","Absatzmarkt"],e:"Produktionsfaktoren werden am Beschaffungsmarkt eingekauft (Beschaffung), in der Produktion kombiniert und die Leistungen über den Absatz am Absatzmarkt verkauft."},en:{q:"Put the operational value-creation process in the correct order.",o:["Procurement market","Procurement","Production","Sales","Sales market"],e:"Factors of production are bought on the procurement market (procurement), combined in production, and the output is sold on the sales market (sales)."},hu:{q:"Állítsd helyes sorrendbe az üzemi teljesítményfolyamatot.",o:["Beszerzési piac","Beszerzés","Termelés","Értékesítés","Értékesítési piac"],e:"A termelési tényezőket a beszerzési piacon vásárolják meg (beszerzés), a termelésben kombinálják, a teljesítményeket pedig az értékesítés révén az értékesítési piacon adják el."}},{type:"match",level:2,de:{q:"Ordne jede Angabe der Kennzahl zu, die damit berechnet wird.",p:[["127 von 130 erstellten Gütern sind fehlerfrei","Produktqualität"],["18 von 20 Sonderwünschen wurden erfüllt","Flexibilität"],["45 von 50 Aufträgen kamen pünktlich","Termintreue"],["Gewinn im Verhältnis zum eingesetzten Kapital","Rentabilität"],["Erlöse im Verhältnis zu den Kosten","Wirtschaftlichkeit"]],e:"Produktqualität = fehlerfreie Güter / alle Güter · 100. Flexibilität = erfüllte / angefragte Sonderwünsche · 100. Termintreue = pünktliche / alle Aufträge · 100. Rentabilität = Gewinn / Kapital · 100. Wirtschaftlichkeit = Erlöse / Kosten."},en:{q:"Match each piece of information with the ratio it is used to calculate.",p:[["127 of 130 goods produced are defect-free","Product quality"],["18 of 20 special requests were met","Flexibility"],["45 of 50 orders arrived on time","On-time delivery rate"],["Profit in relation to capital employed","Return on capital"],["Revenue in relation to costs","Economic efficiency"]],e:"Product quality = defect-free goods / all goods · 100. Flexibility = fulfilled / requested special requests · 100. On-time delivery = punctual / all orders · 100. Return on capital = profit / capital · 100. Economic efficiency = revenue / costs."},hu:{q:"Párosítsd az egyes adatokat azzal a mutatóval, amelyet velük számítanak.",p:[["130 legyártott termékből 127 hibátlan","Termékminőség"],["20 egyedi kérésből 18-at teljesítettek","Rugalmasság"],["50 megrendelésből 45 időben érkezett","Határidő-pontosság"],["Nyereség a befektetett tőkéhez viszonyítva","Jövedelmezőség"],["Árbevétel a költségekhez viszonyítva","Gazdaságosság"]],e:"Termékminőség = hibátlan termékek / összes termék · 100. Rugalmasság = teljesített / kért egyedi kérések · 100. Határidő-pontosság = időben teljesített / összes megrendelés · 100. Jövedelmezőség = nyereség / tőke · 100. Gazdaságosság = árbevétel / költség."}},{type:"mc",level:2,correctIndex:1,de:{q:"Eine Bäckerei vergleicht zwei Investitionen: Projekt A bringt 40.000 € Gewinn bei 500.000 € Kapitaleinsatz, Projekt B 30.000 € Gewinn bei 300.000 € Kapitaleinsatz. Welches Projekt ist rentabler?",o:["Projekt A, weil es den höheren Gewinn in Euro bringt","Projekt B, weil es 10 % statt 8 % Rentabilität hat","Beide gleich, weil beide Projekte Gewinn erzielen","Projekt A, weil es eine Rentabilität von 12,5 % hat"],e:"Rentabilität = Gewinn / Kapitaleinsatz · 100. A: 40.000 / 500.000 · 100 = 8 %. B: 30.000 / 300.000 · 100 = 10 %. Entscheidend ist die Verzinsung des Kapitals, nicht der absolute Gewinn."},en:{q:"A bakery compares two investments: project A brings €40,000 profit with €500,000 capital employed, project B €30,000 profit with €300,000 capital employed. Which project is more profitable?",o:["Project A, because it brings the higher profit in euros","Project B, because it has a return of 10% instead of 8%","Both equally, because both projects make a profit","Project A, because it has a return of 12.5%"],e:"Return on capital = profit / capital employed · 100. A: 40,000 / 500,000 · 100 = 8%. B: 30,000 / 300,000 · 100 = 10%. What counts is the return on capital, not the absolute profit."},hu:{q:"Egy pékség két beruházást hasonlít össze: az A projekt 500 000 € tőkebefektetéssel 40 000 € nyereséget hoz, a B projekt 300 000 € tőkebefektetéssel 30 000 €-t. Melyik projekt jövedelmezőbb?",o:["Az A projekt, mert nagyobb nyereséget hoz euróban","A B projekt, mert jövedelmezősége 10% a 8% helyett","Egyformák, mert mindkét projekt egyaránt nyereséges","Az A projekt, mert a jövedelmezősége 12,5%-os"],e:"Jövedelmezőség = nyereség / befektetett tőke · 100. A: 40 000 / 500 000 · 100 = 8%. B: 30 000 / 300 000 · 100 = 10%. A tőke megtérülése a döntő, nem az abszolút nyereség."}},{type:"mc",level:3,correctIndex:2,de:{q:"Eine Tischlerei kauft eine neue CNC-Fräse. Statt 40 schafft sie nun 50 Werkstücke pro Stunde. Wegen hoher Leasingraten steigen die Kosten aber stärker als die Erlöse. Welche Aussage trifft zu?",o:["Produktivität und Wirtschaftlichkeit sind beide gestiegen","Die Produktivität ist gleich geblieben, die Wirtschaftlichkeit gesunken","Die Produktivität ist gestiegen, die Wirtschaftlichkeit gesunken","Die Produktivität ist gesunken, die Wirtschaftlichkeit gestiegen"],e:"Mehr Stück pro Stunde = höhere Produktivität (Mengen). Steigen die Kosten stärker als die Erlöse, sinkt der Quotient Erlöse/Kosten = Wirtschaftlichkeit. Höhere Produktivität ist also nicht automatisch wirtschaftlich."},en:{q:"A joinery buys a new CNC milling machine. Instead of 40, it now produces 50 workpieces per hour. Because of high leasing instalments, however, costs rise faster than revenue. Which statement is correct?",o:["Productivity and economic efficiency have both risen","Productivity has stayed the same, economic efficiency has fallen","Productivity has risen, economic efficiency has fallen","Productivity has fallen, economic efficiency has risen"],e:"More units per hour = higher productivity (quantities). If costs rise faster than revenue, the ratio revenue/costs = economic efficiency falls. Higher productivity is therefore not automatically economical."},hu:{q:"Egy asztalosműhely új CNC-marógépet vásárol. 40 helyett most óránként 50 munkadarabot gyárt. A magas lízingdíjak miatt azonban a költségek jobban nőnek, mint az árbevétel. Melyik állítás helyes?",o:["A termelékenység és a gazdaságosság is nőtt","A termelékenység változatlan maradt, a gazdaságosság csökkent","A termelékenység nőtt, a gazdaságosság csökkent","A termelékenység csökkent, a gazdaságosság nőtt"],e:"Több darab óránként = nagyobb termelékenység (mennyiségek). Ha a költségek jobban nőnek, mint az árbevétel, az árbevétel/költség hányados, azaz a gazdaságosság csökken. A nagyobb termelékenység tehát nem automatikusan gazdaságos."}},{type:"number",level:3,value:1.15,tol:.01,de:{q:"Ein Betrieb verkauft 2.400 Stück zu je 15 €. Die Kosten bestehen aus 12.000 € Fixkosten und 8 € variablen Kosten pro Stück. Berechne die Wirtschaftlichkeit (auf 2 Dezimalstellen).",e:"Erlöse = 2.400 · 15 = 36.000 €. Kosten = 12.000 + 2.400 · 8 = 12.000 + 19.200 = 31.200 €. Wirtschaftlichkeit = 36.000 / 31.200 ≈ 1,15 → größer als 1, also Gewinn."},en:{q:"A firm sells 2,400 units at €15 each. Its costs consist of €12,000 fixed costs and €8 variable costs per unit. Calculate the economic efficiency (to 2 decimal places).",e:"Revenue = 2,400 · 15 = €36,000. Costs = 12,000 + 2,400 · 8 = 12,000 + 19,200 = €31,200. Economic efficiency = 36,000 / 31,200 ≈ 1.15 → greater than 1, so a profit."},hu:{q:"Egy üzem 2 400 darabot ad el darabonként 15 €-ért. A költségek 12 000 € állandó költségből és darabonként 8 € változó költségből állnak. Számítsd ki a gazdaságosságot (2 tizedesjegyre).",e:"Árbevétel = 2 400 · 15 = 36 000 €. Költség = 12 000 + 2 400 · 8 = 12 000 + 19 200 = 31 200 €. Gazdaságosság = 36 000 / 31 200 ≈ 1,15 → nagyobb 1-nél, tehát nyereség."}}],"kunde-im-mittelpunkt":[{type:"tf",level:1,correct:!1,de:{q:"Wer seine Zielgruppe nach Lebensstil, Interessen und Werten einteilt, segmentiert demografisch",e:"Falsch. Lebensstil, Interessen und Werte sind psychografische Kriterien. Demografisch wären Alter, Einkommen, Familienstand oder Geschlecht."},en:{q:"Dividing a target group by lifestyle, interests and values is demographic segmentation",e:"False. Lifestyle, interests and values are psychographic criteria. Demographic criteria would be age, income, marital status or gender."},hu:{q:"Aki a célcsoportját életstílus, érdeklődés és értékek szerint osztja fel, demográfiai szegmentálást végez",e:"Hamis. Az életstílus, az érdeklődés és az értékek pszichográfiai ismérvek. Demográfiai ismérv az életkor, a jövedelem, a családi állapot vagy a nem."}},{type:"tf",level:2,correct:!0,de:{q:"Marktpsychologische Ziele wie Bekanntheit und Image sind die Voraussetzung dafür, dass marktökonomische Ziele wie Umsatz und Marktanteil erreicht werden",e:"Richtig. Wer ein Unternehmen nicht kennt oder ein schlechtes Bild von ihm hat, kauft dort nicht. Daher bauen marktökonomische Ziele (gut messbare Zahlen) auf marktpsychologischen Zielen (Wahrnehmung) auf."},en:{q:"Market-psychological goals such as awareness and image are the precondition for achieving market-economic goals such as sales revenue and market share",e:"True. People who do not know a company or have a poor image of it will not buy from it. So market-economic goals (easily measurable figures) build on market-psychological goals (perception)."},hu:{q:"A piaclélektani célok, mint az ismertség és az imázs, előfeltételei annak, hogy a piacgazdasági célok, mint az árbevétel és a piaci részesedés, teljesüljenek",e:"Igaz. Aki nem ismer egy vállalatot, vagy rossz képe van róla, nem ott vásárol. A piacgazdasági célok (jól mérhető számok) ezért a piaclélektani célokra (észlelés) épülnek."}},{type:"tf",level:3,correct:!0,de:{q:"Ein Unternehmen, das mehrere ausgewählte Segmente gezielt bearbeitet, aber nicht den gesamten Markt, betreibt konzentrierte Marktbearbeitung",e:"Richtig. Konzentriert heißt: ein oder mehrere Segmente gezielt bearbeiten. Differenziert wäre es erst, wenn ALLE Segmente jeweils unterschiedlich bearbeitet werden; undifferenziert ist ein Angebot für den Gesamtmarkt."},en:{q:"A company that deliberately targets several selected segments, but not the whole market, is pursuing concentrated marketing",e:"True. Concentrated means targeting one or more segments deliberately. It would only be differentiated if ALL segments were each served differently; undifferentiated means one offer for the whole market."},hu:{q:"Az a vállalat, amely több kiválasztott szegmenst céltudatosan, de nem a teljes piacot dolgozza fel, koncentrált piacfeldolgozást folytat",e:"Igaz. A koncentrált azt jelenti, hogy egy vagy több szegmenst céltudatosan dolgoznak fel. Differenciált csak akkor lenne, ha MINDEN szegmenst eltérően dolgoznának fel; a differenciálatlan egyetlen ajánlat a teljes piacnak."}},{type:"multi",level:1,correct:[0,1,2],de:{q:"Welche Touchpoints liegen in der Customer Journey NACH dem Kauf? Wähle alle zutreffenden.",o:["Kundenservice-Hotline","Member-Club mit Treuepunkten","Persönliche Angebote für Stammkund:innen","Instagram-Post einer Influencerin","Bezahlvorgang im Onlineshop"],e:"Nach dem Kauf: Kundenservice, Member-Club, Angebote. Influencer-Posts sind ein Erstkontakt VOR dem Kauf, der Bezahlvorgang im Onlineshop gehört zur Phase WÄHREND des Kaufs."},en:{q:"Which touchpoints in the customer journey come AFTER the purchase? Select all that apply.",o:["Customer service hotline","Member club with loyalty points","Personal offers for regular customers","An influencer's Instagram post","Checkout in the online shop"],e:"After the purchase: customer service, member club, offers. Influencer posts are a first contact BEFORE the purchase; checkout in the online shop belongs to the phase DURING the purchase."},hu:{q:"A vásárlói út mely érintkezési pontjai vannak a vásárlás UTÁN? Jelöld meg az összes helyeset.",o:["Ügyfélszolgálati forródrót","Hűségpontos klubtagság","Személyre szabott ajánlatok törzsvásárlóknak","Egy influenszer Instagram-posztja","Fizetés a webáruházban"],e:"A vásárlás után: ügyfélszolgálat, tagsági klub, ajánlatok. Az influenszer-posztok a vásárlás ELŐTTI első kapcsolatot jelentik, a webáruházi fizetés a vásárlás KÖZBENI szakaszhoz tartozik."}},{type:"multi",level:3,correct:[0,1,4],de:{q:"Welche der folgenden Ziele sind marktökonomische Ziele? Wähle alle zutreffenden.",o:["Marktanteil von 12 % auf 15 % steigern","Umsatz im Onlineshop um 20 % erhöhen","Kundenzufriedenheit verbessern","Markentreue der Stammkund:innen stärken","Absatz auf 50.000 Stück pro Jahr erhöhen","Bekanntheit in der Zielgruppe ausbauen"],e:"Marktökonomische Ziele sind gut messbare Zahlen: Absatz, Umsatz, Marktanteil, Wachstum. Kundenzufriedenheit, Markentreue und Bekanntheit sind marktpsychologische Ziele – sie betreffen die Wahrnehmung, auch wenn man sie mit Umfragen messen kann."},en:{q:"Which of the following goals are market-economic goals? Select all that apply.",o:["Increase market share from 12% to 15%","Raise online shop revenue by 20%","Improve customer satisfaction","Strengthen brand loyalty among regular customers","Increase sales to 50,000 units per year","Build awareness in the target group"],e:"Market-economic goals are easily measurable figures: sales volume, revenue, market share, growth. Customer satisfaction, brand loyalty and awareness are market-psychological goals – they concern perception, even though surveys can measure them."},hu:{q:"Az alábbi célok közül melyek piacgazdasági célok? Jelöld meg az összes helyeset.",o:["A piaci részesedés növelése 12%-ról 15%-ra","A webáruház árbevételének 20%-os növelése","A vevői elégedettség javítása","A törzsvásárlók márkahűségének erősítése","Az értékesített mennyiség növelése évi 50 000 darabra","Az ismertség növelése a célcsoportban"],e:"A piacgazdasági célok jól mérhető számok: értékesített mennyiség, árbevétel, piaci részesedés, növekedés. A vevői elégedettség, a márkahűség és az ismertség piaclélektani célok – az észlelésre vonatkoznak, még ha felmérésekkel mérhetők is."}},{type:"order",level:1,de:{q:"Bringe die Schritte des zielgerichteten Marketings (STP) in die richtige Reihenfolge.",o:["Segmenting – Gesamtmarkt in Teilmärkte aufteilen","Targeting – Zielmarkt auswählen","Positioning – Kund:innen mit bedeutsamem Nutzen überzeugen"],e:"Erst wird der Markt segmentiert, dann wählt man das Zielsegment aus, und erst dann positioniert man sich dort mit einem überzeugenden Nutzen (USP)."},en:{q:"Put the steps of targeted marketing (STP) in the correct order.",o:["Segmenting – dividing the overall market into sub-markets","Targeting – choosing the target market","Positioning – convincing customers with a meaningful benefit"],e:"First the market is segmented, then the target segment is chosen, and only then does the company position itself there with a convincing benefit (USP)."},hu:{q:"Állítsd helyes sorrendbe a célzott marketing (STP) lépéseit.",o:["Szegmentálás – a teljes piac felosztása részpiacokra","Célpiac kiválasztása (targeting)","Pozicionálás – a vevők meggyőzése jelentős előnnyel"],e:"Először szegmentálják a piacot, aztán kiválasztják a célszegmenst, és csak ezután pozicionálják magukat ott egy meggyőző előnnyel (USP)."}},{type:"match",level:2,de:{q:"Ordne jede Zielgruppenbeschreibung dem passenden Segmentierungskriterium zu.",p:[["Kund:innen in Wien und Graz","geografisch"],["Familien mit Kindern unter 10 Jahren","demografisch"],["Umweltbewusste, sportbegeisterte Menschen","psychografisch"],["Stammkund:innen, die jede Woche einkaufen","verhaltensbezogen"]],e:"Geografisch = Länder, Städte. Demografisch = Alter, Einkommen, Familienstand, Geschlecht. Psychografisch = Lebensstil, Interessen, Werte. Verhaltensbezogen = Markentreue, Kaufhäufigkeit, Kaufmotiv."},en:{q:"Match each target group description with the right segmentation criterion.",p:[["Customers in Vienna and Graz","geographic"],["Families with children under 10","demographic"],["Environmentally aware sports enthusiasts","psychographic"],["Regular customers who shop every week","behavioural"]],e:"Geographic = countries, cities. Demographic = age, income, marital status, gender. Psychographic = lifestyle, interests, values. Behavioural = brand loyalty, purchase frequency, buying motive."},hu:{q:"Párosítsd az egyes célcsoport-leírásokat a megfelelő szegmentálási ismérvvel.",p:[["Bécsi és grazi vásárlók","földrajzi"],["10 év alatti gyermekes családok","demográfiai"],["Környezettudatos, sportrajongó emberek","pszichográfiai"],["Hetente vásárló törzsvevők","magatartási"]],e:"Földrajzi = országok, városok. Demográfiai = életkor, jövedelem, családi állapot, nem. Pszichográfiai = életstílus, érdeklődés, értékek. Magatartási = márkahűség, vásárlási gyakoriság, vásárlási motívum."}},{type:"mc",level:2,correctIndex:0,de:{q:"Loopy verkauft ihre Süßigkeiten bisher nur im Geschäft. Jetzt startet sie zusätzlich einen Onlineshop und eine App zum Vorbestellen. Welches Marketinginstrument setzt sie damit vor allem ein?",o:["Distributionspolitik (Place)","Kommunikationspolitik (Promotion)","Produktpolitik (Product)","Preispolitik (Price)"],e:"Neue Vertriebswege (Onlineshop, App) gehören zur Distributionspolitik – Loopy verfolgt damit einen Multi-Channel-Ansatz. Kommunikationspolitik wäre z. B. Werbung, Preispolitik ein Rabatt."},en:{q:"So far Loopy has only sold her sweets in her shop. Now she also launches an online shop and an app for pre-orders. Which marketing instrument is she mainly using?",o:["Distribution policy (Place)","Communication policy (Promotion)","Product policy (Product)","Pricing policy (Price)"],e:"New sales channels (online shop, app) belong to distribution policy – Loopy is pursuing a multi-channel approach. Communication policy would be e.g. advertising, pricing policy a discount."},hu:{q:"Loopy eddig csak az üzletében árulta az édességeit. Most emellett elindít egy webáruházat és egy előrendelő alkalmazást. Melyik marketingeszközt alkalmazza ezzel elsősorban?",o:["Disztribúciós politika (Place)","Kommunikációs politika (Promotion)","Termékpolitika (Product)","Árpolitika (Price)"],e:"Az új értékesítési csatornák (webáruház, alkalmazás) a disztribúciós (értékesítési) politikához tartoznak – Loopy ezzel többcsatornás megközelítést követ. Kommunikációs politika pl. a reklám, árpolitika egy árengedmény."}},{type:"mc",level:3,correctIndex:0,de:{q:"Im Merkmalsraster (Achsen: Preis und Prestige) liegt Loopys Candy Store derzeit bei „niedriger Preis, niedriges Prestige“. Die Soll-Positionierung ist „hoher Preis, hohes Prestige“. Welche Maßnahme passt zur Soll-Positionierung?",o:["Premium-Pralinen in edler Verpackung, höherer Preis","Dauerhaft 30 % Rabatt auf das gesamte Sortiment geben","Verkauf der Produkte über Diskonter-Regale","Billigere Zutaten verwenden, um Kosten zu senken"],e:"Um von der Ist- zur Soll-Position zu kommen, muss Loopy Preis UND Prestige anheben – z. B. mit hochwertigen Produkten und edler Verpackung. Rabatte, Diskonter und billige Zutaten würden das Prestige weiter senken."},en:{q:"In the positioning grid (axes: price and prestige), Loopy's Candy Store is currently at ‘low price, low prestige’. The target positioning is ‘high price, high prestige’. Which measure fits the target positioning?",o:["Premium chocolates in elegant packaging, higher price","A permanent 30% discount on the entire product range","Selling the products on discount-store shelves","Using cheaper ingredients to cut costs"],e:"To move from the current to the target position, Loopy has to raise price AND prestige – e.g. with high-quality products and elegant packaging. Discounts, discount stores and cheap ingredients would lower prestige further."},hu:{q:"A pozicionálási térképen (tengelyek: ár és presztízs) Loopy Candy Store-ja jelenleg az „alacsony ár, alacsony presztízs” helyen áll. A kívánt pozíció „magas ár, magas presztízs”. Melyik intézkedés illik a kívánt pozícióhoz?",o:["Prémium bonbonok elegáns csomagolásban, magasabb áron","Tartós 30%-os árengedmény a teljes kínálatra","A termékek árusítása diszkontáruházak polcain","Olcsóbb alapanyagok használata a költségcsökkentéshez"],e:"Ahhoz, hogy a jelenlegi pozícióból a kívánt pozícióba jusson, Loopynak az árat ÉS a presztízst is emelnie kell – pl. minőségi termékekkel és elegáns csomagolással. Az árengedmények, a diszkontok és az olcsó alapanyagok tovább csökkentenék a presztízst."}},{type:"text",level:2,de:{q:"Wie nennt man den Ansatz, Kund:innen gleichzeitig über mehrere Vertriebskanäle wie Filiale, Onlineshop und App zu erreichen?",a:["Multi-Channel-Ansatz","Multi-Channel","Multichannel","Multi-Channel-Marketing","Mehrkanalvertrieb"],e:"Beim Multi-Channel-Ansatz nutzt ein Unternehmen mehrere Vertriebskanäle, um seine Kund:innen dort zu erreichen, wo sie kaufen wollen."},en:{q:"What is the approach called of reaching customers through several sales channels at once, such as a branch, an online shop and an app?",a:["multi-channel approach","multi-channel","multichannel","multi-channel marketing","multichannel approach"],e:"With a multi-channel approach a company uses several sales channels to reach its customers wherever they want to buy."},hu:{q:"Hogyan nevezzük azt a megközelítést, amikor a vevőket egyszerre több értékesítési csatornán, például üzletben, webáruházban és alkalmazáson keresztül érik el?",a:["többcsatornás megközelítés","multichannel","multi-channel","többcsatornás értékesítés","többcsatornás marketing"],e:"A többcsatornás (multi-channel) megközelítésnél a vállalat több értékesítési csatornát használ, hogy ott érje el a vevőit, ahol azok vásárolni szeretnének."}}],marktforschung:[{type:"tf",level:1,correct:!1,de:{q:"Primäre Marktforschung ist in der Regel günstiger als sekundäre Marktforschung",e:"Falsch. Primärforschung erhebt Daten neu direkt am Markt und ist deshalb teurer – dafür passen die Daten genau zur Fragestellung. Sekundärforschung nutzt bereits vorhandene Daten und ist günstiger."},en:{q:"Primary market research is usually cheaper than secondary market research",e:"False. Primary research collects new data directly in the market and is therefore more expensive – but the data fit the question exactly. Secondary research uses existing data and is cheaper."},hu:{q:"A primer piackutatás általában olcsóbb, mint a szekunder piackutatás",e:"Hamis. A primer kutatás közvetlenül a piacon gyűjt új adatokat, ezért drágább – cserébe az adatok pontosan illeszkednek a kérdésfeltevéshez. A szekunder kutatás már meglévő adatokat használ, és olcsóbb."}},{type:"tf",level:2,correct:!0,de:{q:"Fragen zu Alter, Einkommen und anderen demografischen Daten sollten in einem Fragebogen eher am Ende stehen",e:"Richtig. Am Anfang steht eine leichte Eisbrecherfrage, persönliche demografische Angaben kommen ans Ende – so springen weniger Befragte ab. Außerdem sollte Anonymität zugesichert werden."},en:{q:"Questions about age, income and other demographic data should rather be placed at the end of a questionnaire",e:"True. An easy icebreaker question comes first, personal demographic details go at the end – so fewer respondents drop out. Anonymity should also be assured."},hu:{q:"Az életkorra, a jövedelemre és más demográfiai adatokra vonatkozó kérdéseknek a kérdőív inkább a végén van a helyük",e:"Igaz. Az elején egy könnyű jégtörő kérdés áll, a személyes demográfiai adatok a végére kerülnek – így kevesebb válaszadó hagyja abba. Emellett biztosítani kell az anonimitást."}},{type:"tf",level:3,correct:!1,de:{q:"Eine Stichprobe ist automatisch repräsentativ, wenn sie nur groß genug ist",e:"Falsch. Repräsentativ ist eine Stichprobe, wenn sie die wichtigsten Eigenschaften der Grundgesamtheit (z. B. Alter, Geschlecht) widerspiegelt. Auch eine sehr große, aber einseitige Stichprobe liefert verzerrte Ergebnisse."},en:{q:"A sample is automatically representative as long as it is large enough",e:"False. A sample is representative if it reflects the most important characteristics of the population (e.g. age, gender). Even a very large but one-sided sample gives distorted results."},hu:{q:"Egy minta automatikusan reprezentatív, ha elég nagy",e:"Hamis. Egy minta akkor reprezentatív, ha tükrözi az alapsokaság legfontosabb jellemzőit (pl. életkor, nem). Egy nagyon nagy, de egyoldalú minta is torz eredményt ad."}},{type:"multi",level:1,correct:[0,1,2],de:{q:"Welche Informationsquellen sind unternehmensinterne Quellen der sekundären Marktforschung? Wähle alle zutreffenden.",o:["Außendienstberichte","Umsatzstatistiken","Kundenstatistiken","Amtliche Statistiken (Statistik Austria)","Geschäftsberichte anderer Unternehmen","Externe Datenbanken"],e:"Intern sind Daten, die im eigenen Unternehmen schon vorliegen: Außendienstberichte, Kunden- und Umsatzstatistiken, Rechnungswesen. Amtliche Statistiken, fremde Geschäftsberichte und externe Datenbanken sind externe Quellen."},en:{q:"Which information sources are internal sources of secondary market research? Select all that apply.",o:["Field sales reports","Sales statistics","Customer statistics","Official statistics (Statistics Austria)","Annual reports of other companies","External databases"],e:"Internal sources are data already available within the company: field sales reports, customer and sales statistics, accounting. Official statistics, other companies' annual reports and external databases are external sources."},hu:{q:"Mely információforrások a szekunder piackutatás vállalaton belüli forrásai? Jelöld meg az összes helyeset.",o:["Külszolgálati jelentések","Értékesítési statisztikák","Vevőstatisztikák","Hivatalos statisztikák (Statistik Austria)","Más vállalatok üzleti jelentései","Külső adatbázisok"],e:"Belső forrás minden, ami a saját vállalatnál már rendelkezésre áll: külszolgálati jelentések, vevő- és értékesítési statisztikák, számvitel. A hivatalos statisztikák, más cégek üzleti jelentései és a külső adatbázisok külső források."}},{type:"multi",level:2,correct:[0,1,2],de:{q:"Welche der folgenden Verfahren sind Formen der Beobachtung? Wähle alle zutreffenden.",o:["Eyetracking am Supermarktregal","Social Listening in sozialen Netzwerken","Auswertung des Klickverhaltens im Onlineshop","Storetest in ausgewählten Filialen","A/B-Test mit zwei Varianten einer Website"],e:"Eyetracking (apparativ), Social Listening und Klickverhalten (online) sind Beobachtungen. Storetest und A/B-Test sind Experimente – dabei wird gezielt etwas verändert und die Wirkung getestet."},en:{q:"Which of the following methods are forms of observation? Select all that apply.",o:["Eye tracking at a supermarket shelf","Social listening on social networks","Analysing click behaviour in an online shop","Store test in selected branches","A/B test with two versions of a website"],e:"Eye tracking (instrument-based), social listening and click behaviour (online) are observations. Store tests and A/B tests are experiments – something is changed deliberately and the effect is tested."},hu:{q:"Az alábbi eljárások közül melyek a megfigyelés formái? Jelöld meg az összes helyeset.",o:["Szemmozgáskövetés (eyetracking) a szupermarket polcánál","Social listening a közösségi hálózatokon","A kattintási viselkedés elemzése a webáruházban","Bolti teszt kiválasztott üzletekben","A/B-teszt egy weboldal két változatával"],e:"A szemmozgáskövetés (műszeres), a social listening és a kattintási viselkedés (online) megfigyelés. A bolti teszt és az A/B-teszt kísérlet – ilyenkor célzottan változtatnak valamin, és tesztelik a hatását."}},{type:"order",level:2,de:{q:"Bringe die Teile eines gut aufgebauten Fragebogens in die richtige Reihenfolge.",o:["Einleitung mit Zusicherung der Anonymität","Eisbrecherfrage","Fachliche Hauptfragen zum Thema","Demografische Angaben (Alter, Geschlecht …)"],e:"Zuerst schafft man Vertrauen (Anonymität), dann lockert eine einfache Eisbrecherfrage auf. Danach folgen die eigentlichen Fragen; persönliche demografische Daten kommen ans Ende."},en:{q:"Put the parts of a well-structured questionnaire in the correct order.",o:["Introduction assuring anonymity","Icebreaker question","Main questions on the topic","Demographic details (age, gender …)"],e:"First build trust (anonymity), then an easy icebreaker question relaxes respondents. The actual questions follow; personal demographic data go at the end."},hu:{q:"Állítsd helyes sorrendbe egy jól felépített kérdőív részeit.",o:["Bevezetés az anonimitás biztosításával","Jégtörő kérdés","A témára vonatkozó fő kérdések","Demográfiai adatok (életkor, nem …)"],e:"Először bizalmat kell teremteni (anonimitás), aztán egy egyszerű jégtörő kérdés oldja a hangulatot. Ezt követik a tulajdonképpeni kérdések; a személyes demográfiai adatok a végére kerülnek."}},{type:"match",level:2,de:{q:"Ordne jedes Beispiel der passenden Methode der primären Marktforschung zu.",p:[["Testpersonen kosten eine neue Schokolade und geben Feedback","Produkttest"],["Neue Sorte wird 4 Wochen nur in 5 Filialen verkauft","Storetest"],["Produkt samt Werbekampagne startet zuerst nur in Kärnten","Markttest"],["Dieselben 2.000 Haushalte melden monatlich ihre Einkäufe","Panelerhebung"],["Eine Kamera zeichnet den Blickverlauf am Regal auf","Apparative Beobachtung"]],e:"Produkttest = Feedback zum Produkt. Storetest = Verkauf in ausgewählten Geschäften. Markttest = Produkt + Marketing auf einem Testmarkt. Panel = gleiche Personen regelmäßig. Kamera/Eyetracking = apparative Beobachtung."},en:{q:"Match each example with the right method of primary market research.",p:[["Test persons taste a new chocolate and give feedback","Product test"],["A new flavour is sold for 4 weeks in only 5 branches","Store test"],["Product and ad campaign launch first in Carinthia only","Test market"],["The same 2,000 households report their purchases monthly","Panel survey"],["A camera records eye movements at the shelf","Instrument-based observation"]],e:"Product test = feedback on the product. Store test = sales in selected shops. Test market = product + marketing in a test market. Panel = the same people regularly. Camera/eye tracking = instrument-based observation."},hu:{q:"Párosítsd az egyes példákat a primer piackutatás megfelelő módszerével.",p:[["Tesztalanyok megkóstolnak egy új csokoládét és visszajeleznek","Termékteszt"],["Egy új ízt 4 hétig csak 5 üzletben árulnak","Bolti teszt"],["A termék a reklámkampánnyal együtt először csak Karintiában indul","Piacteszt"],["Ugyanaz a 2000 háztartás havonta jelenti a vásárlásait","Panelfelmérés"],["Egy kamera rögzíti a tekintet útját a polcnál","Műszeres megfigyelés"]],e:"Termékteszt = visszajelzés a termékről. Bolti teszt = értékesítés kiválasztott üzletekben. Piacteszt = termék + marketing egy tesztpiacon. Panel = ugyanazok a személyek rendszeresen. Kamera/szemmozgáskövetés = műszeres megfigyelés."}},{type:"mc",level:1,correctIndex:0,de:{q:"Die Direktorin einer HAK will wissen, wie zufrieden ihre 24 Lehrer:innen mit dem neuen Stundenplan sind, und befragt jede einzelne Lehrkraft. Wie nennt man diese Erhebung?",o:["Vollerhebung","Teilerhebung","Panelerhebung","Sekundärerhebung"],e:"Werden ALLE Personen der Grundgesamtheit (hier alle 24 Lehrer:innen) untersucht, ist das eine Vollerhebung. Bei einer Teilerhebung würde man nur eine Stichprobe befragen."},en:{q:"The head of a commercial academy wants to know how satisfied her 24 teachers are with the new timetable and asks every single one of them. What is this survey called?",o:["Full survey (census)","Partial survey (sample)","Panel survey","Secondary survey"],e:"If ALL members of the population (here all 24 teachers) are surveyed, it is a full survey. A partial survey would only ask a sample."},hu:{q:"Egy HAK igazgatónője tudni szeretné, mennyire elégedett a 24 tanára az új órarenddel, és minden egyes tanárt megkérdez. Hogyan nevezzük ezt a felmérést?",o:["Teljes körű felmérés","Részleges (mintavételes) felmérés","Panelfelmérés","Szekunder felmérés"],e:"Ha az alapsokaság MINDEN tagját (itt mind a 24 tanárt) megvizsgálják, az teljes körű felmérés. Részleges felmérésnél csak egy mintát kérdeznének meg."}},{type:"mc",level:3,correctIndex:0,de:{q:"Ein Getränkehersteller will herausfinden, wie sich die Markenvorlieben junger Kund:innen über die nächsten drei Jahre verändern. Welche Methode eignet sich am besten?",o:["Panelerhebung mit denselben Personen","Einmalige Online-Befragung vieler Personen","Storetest in ausgewählten Supermärkten","Laborbeobachtung mit neuer Verpackung"],e:"Um Veränderungen und Trends über die Zeit zu erkennen, befragt oder beobachtet man dieselben Personen regelmäßig – eine Panelerhebung. Eine einmalige Befragung zeigt nur eine Momentaufnahme, Store- und Labortests prüfen konkrete Produkte."},en:{q:"A beverage producer wants to find out how young customers' brand preferences change over the next three years. Which method is best suited?",o:["Panel survey with the same people","One-off online survey of many people","Store test in selected supermarkets","Laboratory observation with new packaging"],e:"To detect changes and trends over time, the same people are surveyed or observed regularly – a panel survey. A one-off survey only gives a snapshot; store and lab tests examine specific products."},hu:{q:"Egy italgyártó szeretné megtudni, hogyan változnak a fiatal vásárlók márkapreferenciái a következő három évben. Melyik módszer a legalkalmasabb?",o:["Panelfelmérés ugyanazokkal a személyekkel","Egyszeri online felmérés sok személlyel","Bolti teszt kiválasztott szupermarketekben","Laboratóriumi megfigyelés új csomagolással"],e:"Az időbeli változások és trendek felismeréséhez ugyanazokat a személyeket kérdezik meg vagy figyelik meg rendszeresen – ez a panelfelmérés. Egy egyszeri felmérés csak pillanatfelvétel, a bolti és laboratóriumi tesztek konkrét termékeket vizsgálnak."}},{type:"mc",level:3,correctIndex:2,de:{q:"Ein Hotel will die Zufriedenheit ALLER Gäste messen, befragt aber nur Gäste am Sonntagvormittag beim Frühstücksbuffet – fast nur Familien. Geschäftsreisende reisen meist schon früher ab. Was ist das Hauptproblem?",o:["Es handelt sich um sekundäre statt primäre Marktforschung","Es hätte eine Vollerhebung aller Gäste sein müssen","Die Stichprobe ist nicht repräsentativ für alle Gäste","Am Frühstücksbuffet sind offene Fragen nicht erlaubt"],e:"Die befragte Gruppe spiegelt die Grundgesamtheit (alle Gäste) nicht wider, weil Geschäftsreisende fehlen – die Ergebnisse sind verzerrt. Eine Teilerhebung ist zulässig, die Stichprobe muss aber repräsentativ sein."},en:{q:"A hotel wants to measure the satisfaction of ALL guests but only surveys guests at the breakfast buffet on Sunday morning – almost exclusively families. Business travellers usually leave earlier. What is the main problem?",o:["It is secondary rather than primary market research","It should have been a full survey of all guests","The sample is not representative of all guests","Open questions are not allowed at a breakfast buffet"],e:"The group surveyed does not reflect the population (all guests) because business travellers are missing – the results are distorted. A partial survey is fine, but the sample must be representative."},hu:{q:"Egy szálloda MINDEN vendég elégedettségét szeretné mérni, de csak a vasárnap délelőtti reggelinél kérdezi meg a vendégeket – szinte kizárólag családokat. Az üzleti utazók többnyire már korábban elutaznak. Mi a fő probléma?",o:["Szekunder és nem primer piackutatásról van szó","Teljes körű felmérést kellett volna végezni minden vendég körében","A minta nem reprezentatív az összes vendégre","A reggelinél nem szabad nyitott kérdéseket feltenni"],e:"A megkérdezett csoport nem tükrözi az alapsokaságot (az összes vendéget), mert hiányoznak az üzleti utazók – az eredmények torzak. A részleges felmérés megengedett, de a mintának reprezentatívnak kell lennie."}}]},i={"instrumente-marketings":[{type:"tf",level:1,correct:!1,de:{q:"Eine Familienmarke bedeutet, dass alle Produkte eines Unternehmens unter einer einzigen Marke verkauft werden.",e:"Falsch – das ist eine Dachmarke (z. B. Procter & Gamble). Eine Familienmarke gilt nur für eine Produktgruppe, z. B. Nivea bei Beiersdorf."},en:{q:"A family brand means that all products of a company are sold under one single brand.",e:"False – that is an umbrella brand (e.g. Procter & Gamble). A family brand covers only one product group, e.g. Nivea at Beiersdorf."},hu:{q:"A családi márka azt jelenti, hogy egy vállalat összes terméke egyetlen márkanév alatt kerül forgalomba.",e:"Hamis – ez az ernyőmárka (pl. Procter & Gamble). A családi márka csak egy termékcsoportra vonatkozik, pl. a Beiersdorfnál a Nivea."}},{type:"tf",level:2,correct:!0,de:{q:"Eine Produktdifferenzierung erhöht die Sortimentstiefe, eine Diversifikation dagegen die Sortimentsbreite.",e:"Richtig – Differenzierung bringt weitere Varianten innerhalb einer Produktgruppe (Tiefe), Diversifikation nimmt neue Produktgruppen ins Programm (Breite)."},en:{q:"Product differentiation increases the depth of the product range, whereas diversification increases its width.",e:"True – differentiation adds further variants within a product group (depth), diversification adds new product groups to the range (width)."},hu:{q:"A termékdifferenciálás a választék mélységét, a diverzifikáció viszont a választék szélességét növeli.",e:"Igaz – a differenciálás egy termékcsoporton belül hoz új változatokat (mélység), a diverzifikáció új termékcsoportokat vesz fel a kínálatba (szélesség)."}},{type:"tf",level:3,correct:!1,de:{q:"Bei der Abschöpfungsstrategie startet ein Unternehmen mit einem niedrigen Preis und erhöht ihn, sobald sich das Produkt am Markt durchgesetzt hat.",e:"Falsch – das beschreibt die Marktdurchdringung (z. B. Netflix). Bei der Abschöpfung startet man hoch und senkt den Preis später (z. B. PS5)."},en:{q:"With a skimming strategy, a company starts with a low price and raises it as soon as the product has become established on the market.",e:"False – that describes market penetration (e.g. Netflix). With skimming you start high and lower the price later (e.g. PS5)."},hu:{q:"Lefölözési stratégiánál a vállalat alacsony árral indul, és megemeli, amint a termék befutott a piacon.",e:"Hamis – ez a piacpenetrációs stratégia (pl. Netflix). Lefölözésnél magas árral indulnak, és később csökkentik (pl. PS5)."}},{type:"multi",level:2,correct:[0,1,3],de:{q:"Welche Aussagen zur Portfolioanalyse (BCG-Matrix) treffen zu? Wähle alle zutreffenden.",o:["Die Achsen sind Marktwachstum und relativer Marktanteil.","Stars sollen stark gefördert werden.","Poor Dogs haben hohes Marktwachstum, aber niedrigen Marktanteil.","Ein relativer Marktanteil über 1 bedeutet Marktführerschaft.","Question Marks werden sofort vom Markt genommen."],e:"Ist der eigene Anteil größer als der des größten Konkurrenten, liegt der relative Marktanteil über 1. Poor Dogs haben niedriges Wachstum UND niedrigen Anteil; Question Marks werden beobachtet, nicht sofort eliminiert."},en:{q:"Which statements about portfolio analysis (BCG matrix) are correct? Select all that apply.",o:["The axes are market growth and relative market share.","Stars should be strongly supported.","Poor dogs have high market growth but a low market share.","A relative market share above 1 means market leadership.","Question marks are taken off the market immediately."],e:"If your own share is larger than that of the biggest competitor, the relative market share is above 1. Poor dogs have low growth AND low share; question marks are watched, not eliminated at once."},hu:{q:"Mely állítások igazak a portfólióelemzésre (BCG-mátrix)? Jelöld az összes helyeset.",o:["A tengelyek a piaci növekedés és a relatív piaci részesedés.","A sztárokat erősen támogatni kell.","A döglött kutyák piaca gyorsan nő, de piaci részesedésük alacsony.","Az 1 feletti relatív piaci részesedés piacvezető szerepet jelent.","A kérdőjeleket azonnal kivonják a piacról."],e:"Ha a saját részesedés nagyobb a legnagyobb versenytársénál, a relatív piaci részesedés 1 feletti. A döglött kutyák piaca lassan nő ÉS részesedésük is alacsony; a kérdőjeleket megfigyelik, nem vonják ki azonnal."}},{type:"multi",level:2,correct:[0,2,4],de:{q:"Loopy plant eine Werbekampagne. Welche der folgenden sind Werbeträger (nicht Werbemittel)? Wähle alle zutreffenden.",o:["Fernsehen","TV-Spot","Plakatwand an der Bushaltestelle","Text und Bild eines Zeitungsinserats","Influencerin auf Instagram"],e:"Werbeträger transportieren die Botschaft (Fernsehen, Außenwerbung, Influencer:innen). TV-Spot und Inserat sind Werbemittel – die Gestaltungsform der Botschaft."},en:{q:"Loopy is planning an advertising campaign. Which of the following are advertising media (not advertising materials)? Select all that apply.",o:["Television","TV commercial","Billboard at the bus stop","Text and image of a newspaper ad","Influencer on Instagram"],e:"Advertising media carry the message (television, outdoor advertising, influencers). The TV commercial and the ad are advertising materials – the form in which the message is designed."},hu:{q:"Loopy reklámkampányt tervez. Az alábbiak közül melyek reklámhordozók (és nem reklámeszközök)? Jelöld az összes helyeset.",o:["Televízió","Tévéreklám (reklámspot)","Plakáttábla a buszmegállóban","Egy újsághirdetés szövege és képe","Influencer az Instagramon"],e:"A reklámhordozó továbbítja az üzenetet (televízió, kültéri reklám, influencerek). A tévéspot és a hirdetés reklámeszköz – az üzenet megformált alakja."}},{type:"order",level:1,de:{q:"Bringe die Schritte eines Marketingkonzepts in die richtige Reihenfolge.",o:["Situationsanalyse","Marketingziele","Marketingstrategie (STP)","Marketingmix (4 Ps)","Umsetzung von Maßnahmen"],e:"Erst die Lage analysieren, dann Ziele setzen, die Strategie (Segmenting, Targeting, Positioning) wählen, den Marketingmix festlegen und schließlich umsetzen und kontrollieren."},en:{q:"Put the steps of a marketing concept in the correct order.",o:["Situation analysis","Marketing objectives","Marketing strategy (STP)","Marketing mix (4 Ps)","Implementation of measures"],e:"First analyse the situation, then set objectives, choose the strategy (segmenting, targeting, positioning), define the marketing mix and finally implement and monitor."},hu:{q:"Állítsd helyes sorrendbe a marketingkoncepció lépéseit!",o:["Helyzetelemzés","Marketingcélok","Marketingstratégia (STP)","Marketingmix (4P)","Az intézkedések megvalósítása"],e:"Először elemezzük a helyzetet, majd kitűzzük a célokat, kiválasztjuk a stratégiát (szegmentálás, célpiac-választás, pozicionálás), meghatározzuk a marketingmixet, végül megvalósítunk és ellenőrzünk."}},{type:"match",level:1,de:{q:"Ordne jede Maßnahme dem passenden Instrument der Produktpolitik zu.",p:[["Loopy ändert die Rezeptur ihrer Karamellbonbons","Produktvariation (Relaunch)"],["Loopy bringt eine Junior-Edition für Kinder heraus","Produktdifferenzierung"],["Loopy verkauft zusätzlich Kaffee und Kuchen","Diversifikation"],["Loopy nimmt Lakritzschnecken aus dem Sortiment","Produkteliminierung"]],e:"Variation verbessert ein bestehendes Produkt, Differenzierung bringt ähnliche Produkte für neue Zielgruppen, Diversifikation neue Produktgruppen, Eliminierung nimmt ein Produkt vom Markt."},en:{q:"Match each measure with the right instrument of product policy.",p:[["Loopy changes the recipe of her caramel sweets","Product variation (relaunch)"],["Loopy launches a junior edition for children","Product differentiation"],["Loopy also starts selling coffee and cake","Diversification"],["Loopy drops liquorice wheels from her range","Product elimination"]],e:"Variation improves an existing product, differentiation adds similar products for new target groups, diversification adds new product groups, elimination takes a product off the market."},hu:{q:"Párosítsd az intézkedéseket a termékpolitika megfelelő eszközével!",p:[["Loopy megváltoztatja a karamellcukorka receptjét","Termékmódosítás (relaunch)"],["Loopy junior kiadást dob piacra gyerekeknek","Termékdifferenciálás"],["Loopy kávét és süteményt is kezd árulni","Diverzifikáció"],["Loopy kiveszi a kínálatából a medvecukor-csigát","Termékeliminálás"]],e:"A módosítás egy meglévő terméket javít, a differenciálás hasonló termékeket kínál új célcsoportoknak, a diverzifikáció új termékcsoportot hoz, az eliminálás kivonja a terméket a piacról."}},{type:"mc",level:2,correctIndex:2,de:{q:"Ein Kino in Linz verlangt montags und für Schüler:innen niedrigere Eintrittspreise als am Samstagabend. Welche preispolitische Maßnahme liegt vor?",o:["Kalkulatorischer Ausgleich","Abschöpfungsstrategie","Preisdifferenzierung","Shrinkflation"],e:"Für dieselbe Leistung werden je nach Zeit und Zielgruppe unterschiedliche Preise verlangt = Preisdifferenzierung. Kalkulatorischer Ausgleich hieße, verschiedene Produkte unterschiedlich hoch zu kalkulieren."},en:{q:"A cinema in Linz charges lower ticket prices on Mondays and for school students than on Saturday evenings. Which pricing measure is this?",o:["Compensatory pricing","Price skimming strategy","Price differentiation","Shrinkflation"],e:"Different prices for the same service depending on time and target group = price differentiation. Compensatory pricing would mean calculating different products with different margins."},hu:{q:"Egy linzi mozi hétfőn és a diákoknak olcsóbb jegyet kínál, mint szombat este. Milyen árpolitikai intézkedésről van szó?",o:["Kalkulációs kiegyenlítés","Lefölözési stratégia","Árdifferenciálás","Zsugorfláció"],e:"Ugyanazért a szolgáltatásért időponttól és célcsoporttól függően eltérő árat kérnek = árdifferenciálás. A kalkulációs kiegyenlítés azt jelentené, hogy különböző termékeket eltérő árréssel kalkulálnak."}},{type:"mc",level:3,correctIndex:1,de:{q:"Loopys Fruchtgummi hat 12 % Marktanteil, der größte Konkurrent 30 %. Der Markt wächst jährlich um 15 %. Wo liegt das Produkt in der BCG-Matrix und was ist zu tun?",o:["Star – stark investieren und fördern","Question Mark – beobachten, Investition abwägen","Cashcow – Marktposition halten und Gewinne „melken“","Poor Dog – vom Markt nehmen"],e:"Relativer Marktanteil = 12 / 30 = 0,4 → niedrig; Marktwachstum 15 % → hoch. Hohes Wachstum + niedriger Anteil = Question Mark. Ein Star bräuchte einen relativen Marktanteil über 1."},en:{q:"Loopy's fruit gums have a 12 % market share, the biggest competitor 30 %. The market grows by 15 % a year. Where is the product in the BCG matrix and what should be done?",o:["Star – invest heavily and support","Question mark – watch, weigh up investing","Cash cow – hold the position and 'milk' its profits","Poor dog – take it off the market"],e:"Relative market share = 12 / 30 = 0.4 → low; market growth 15 % → high. High growth + low share = question mark. A star would need a relative market share above 1."},hu:{q:"Loopy gumicukrának piaci részesedése 12 %, a legnagyobb versenytársé 30 %. A piac évente 15 %-kal nő. Hol helyezkedik el a termék a BCG-mátrixban, és mit kell tenni?",o:["Sztár – erősen befektetni és támogatni","Kérdőjel – figyelni, mérlegelni a befektetést","Fejőstehén – a pozíciót tartani és a nyereséget „fejni”","Döglött kutya – kivonni a piacról"],e:"Relatív piaci részesedés = 12 / 30 = 0,4 → alacsony; piaci növekedés 15 % → magas. Magas növekedés + alacsony részesedés = kérdőjel. Sztárhoz 1 feletti relatív piaci részesedés kellene."}},{type:"number",level:3,value:5,tol:.01,unit:{de:"€",en:"€",hu:"€"},de:{q:"Ein Radiospot kostet 1.200 € und erreicht 80.000 Hörer:innen. Ein Plakat kostet 900 € und erreicht 45.000 Personen. Um wie viel Euro ist der Tausend-Kontakt-Preis (TKP) des Plakats höher als der des Radiospots?",e:"TKP Radio = 1.200 · 1.000 / 80.000 = 15 €. TKP Plakat = 900 · 1.000 / 45.000 = 20 €. Differenz = 20 − 15 = 5 €. Obwohl das Plakat absolut billiger ist, ist jeder Kontakt teurer."},en:{q:"A radio commercial costs €1,200 and reaches 80,000 listeners. A poster costs €900 and reaches 45,000 people. By how many euros is the cost per thousand contacts (CPM) of the poster higher than that of the radio commercial?",e:"CPM radio = 1,200 · 1,000 / 80,000 = €15. CPM poster = 900 · 1,000 / 45,000 = €20. Difference = 20 − 15 = €5. Although the poster is cheaper in absolute terms, each contact costs more."},hu:{q:"Egy rádióreklám 1200 €-ba kerül, és 80 000 hallgatót ér el. Egy plakát 900 €-ba kerül, és 45 000 embert ér el. Hány euróval magasabb a plakát ezer kontaktusra jutó ára (TKP), mint a rádióreklámé?",e:"TKP rádió = 1200 · 1000 / 80 000 = 15 €. TKP plakát = 900 · 1000 / 45 000 = 20 €. Különbség = 20 − 15 = 5 €. Bár a plakát abszolút értékben olcsóbb, minden egyes kontaktus drágább."}}],"material-warenwirtschaft":[{type:"tf",level:1,correct:!0,de:{q:"Der Begriff Materialwirtschaft wird vor allem bei Produktionsbetrieben verwendet, der Begriff Warenwirtschaft vor allem bei Handelsbetrieben.",e:"Richtig – Produktionsbetriebe beschaffen Roh-, Hilfs- und Betriebsstoffe (Materialwirtschaft), Handelsbetriebe Handelswaren für ihre Kund:innen (Warenwirtschaft)."},en:{q:"The term materials management is used mainly for manufacturing companies, the term merchandise management mainly for trading companies.",e:"True – manufacturers procure raw materials, auxiliary materials and operating supplies (materials management), traders procure merchandise for their customers (merchandise management)."},hu:{q:"Az anyaggazdálkodás fogalmát főleg termelő vállalatoknál, az árugazdálkodásét főleg kereskedelmi vállalatoknál használják.",e:"Igaz – a termelő vállalatok alap-, segéd- és üzemi anyagokat szereznek be (anyaggazdálkodás), a kereskedők árukat vevőik számára (árugazdálkodás)."}},{type:"tf",level:1,correct:!1,de:{q:"Die Material- und Warenwirtschaft hat ihre Aufgabe erfüllt, sobald die Güter zum niedrigsten Preis eingekauft wurden.",e:"Falsch – die Güter müssen auch in der richtigen Qualität und Menge, zur richtigen Zeit und am richtigen Ort bereitstehen; zusätzlich sind soziale und ökologische Kriterien zu beachten."},en:{q:"Materials and merchandise management has done its job as soon as the goods have been bought at the lowest price.",e:"False – the goods must also be available in the right quality and quantity, at the right time and in the right place; social and ecological criteria must be respected too."},hu:{q:"Az anyag- és árugazdálkodás akkor teljesítette a feladatát, ha a javakat a legalacsonyabb áron szerezte be.",e:"Hamis – a javaknak megfelelő minőségben és mennyiségben, a megfelelő időben és helyen is rendelkezésre kell állniuk; emellett társadalmi és ökológiai szempontokat is figyelembe kell venni."}},{type:"tf",level:3,correct:!0,de:{q:"Ein hoher Lagerbestand unterstützt das Sachziel einer störungsfreien Leistungserstellung, steht aber im Konflikt mit dem ökonomischen Ziel der Kostenminimierung.",e:"Richtig – viel Vorrat verhindert Engpässe (Sachziel), verursacht aber Lager- und Kapitalbindungskosten (ökonomisches Ziel). Das ist ein typischer Zielkonflikt."},en:{q:"A high stock level supports the operational goal of smooth production, but conflicts with the economic goal of minimising costs.",e:"True – large stocks prevent shortages (operational goal) but cause storage costs and tie up capital (economic goal). This is a typical goal conflict."},hu:{q:"A magas készletszint segíti a zavartalan teljesítményelőállítás tárgyi célját, de ütközik a költségminimalizálás gazdasági céljával.",e:"Igaz – a sok készlet megelőzi a hiányt (tárgyi cél), de raktározási és tőkelekötési költséget okoz (gazdasági cél). Ez tipikus célkonfliktus."}},{type:"multi",level:2,correct:[0,1,2,4],de:{q:"Welche Güter einer Tischlerei zählen zu den Roh-, Hilfs- und Betriebsstoffen? Wähle alle zutreffenden.",o:["Eichenholz","Leim","Schmieröl für die Maschinen","Die neue CNC-Fräse","Strom für die Werkstatt","Das Werkstattgebäude"],e:"Holz ist Rohstoff, Leim Hilfsstoff, Schmieröl und Strom sind Betriebsstoffe. CNC-Fräse und Gebäude werden nicht verbraucht – sie sind Anlagevermögen (Betriebsmittel)."},en:{q:"Which goods of a joinery count as raw materials, auxiliary materials or operating supplies? Select all that apply.",o:["Oak wood","Glue","Lubricating oil for the machines","The new CNC milling machine","Electricity for the workshop","The workshop building"],e:"Wood is a raw material, glue an auxiliary material, oil and electricity are operating supplies. The CNC machine and the building are not used up – they are fixed assets."},hu:{q:"Egy asztalosműhely mely javai tartoznak az alap-, segéd- és üzemi anyagok közé? Jelöld az összes helyeset.",o:["Tölgyfa","Ragasztó","Kenőolaj a gépekhez","Az új CNC-marógép","A műhely áramfogyasztása","A műhelyépület"],e:"A fa alapanyag, a ragasztó segédanyag, a kenőolaj és az áram üzemi anyag. A CNC-gép és az épület nem használódik el egyszerre – ezek tárgyi eszközök."}},{type:"multi",level:2,correct:[0,1,3],de:{q:"Welche Entscheidungen berücksichtigen soziale oder ökologische Kriterien in der Beschaffung? Wähle alle zutreffenden.",o:["Kakao mit Fairtrade-Siegel einkaufen","Milch von Bäuer:innen aus der Region beziehen","Lieferanten nur nach dem niedrigsten Preis auswählen","Mehrweg-Transportboxen statt Einwegkartons nutzen","Größere Mengen für einen Mengenrabatt bestellen"],e:"Fairtrade (sozial), Regionalität und Mehrweg (ökologisch) erfüllen diese Kriterien. Niedrigster Preis und Mengenrabatt dienen dem ökonomischen Ziel der Kostenminimierung."},en:{q:"Which decisions take social or ecological criteria into account in procurement? Select all that apply.",o:["Buying cocoa with a Fairtrade label","Sourcing milk from local farmers","Choosing suppliers only by the lowest price","Using reusable transport boxes instead of disposable cartons","Ordering larger quantities to get a volume discount"],e:"Fairtrade (social), local sourcing and reusable boxes (ecological) meet these criteria. Lowest price and volume discounts serve the economic goal of minimising costs."},hu:{q:"Mely döntések veszik figyelembe a társadalmi vagy ökológiai szempontokat a beszerzésben? Jelöld az összes helyeset.",o:["Fairtrade minősítésű kakaó vásárlása","Tej beszerzése a környékbeli gazdáktól","Beszállítók kiválasztása kizárólag a legalacsonyabb ár alapján","Többutas szállítódobozok használata eldobható kartonok helyett","Nagyobb mennyiség rendelése mennyiségi engedményért"],e:"A Fairtrade (társadalmi), a helyi beszerzés és a többutas dobozok (ökológiai) megfelelnek ezeknek a szempontoknak. A legalacsonyabb ár és a mennyiségi engedmény a költségminimalizálás gazdasági célját szolgálja."}},{type:"order",level:1,de:{q:"Bringe die Bereiche der Material- und Warenwirtschaft in die Reihenfolge, in der ein Gut sie durchläuft.",o:["Beschaffung (Beschaffungsmarketing)","Lagerung (Lagerlogistik)","Verteilung (Transportlogistik)","Entsorgung (Entsorgungslogistik)"],e:"Güter werden zuerst beschafft, dann gelagert, anschließend verteilt; am Ende stehen Reste, Verpackungen und Retouren, um die sich die Entsorgungslogistik kümmert."},en:{q:"Put the areas of materials and merchandise management in the order in which a good passes through them.",o:["Procurement (procurement marketing)","Storage (warehouse logistics)","Distribution (transport logistics)","Disposal (disposal logistics)"],e:"Goods are first procured, then stored, then distributed; at the end come leftovers, packaging and returns, which disposal logistics takes care of."},hu:{q:"Állítsd sorrendbe az anyag- és árugazdálkodás területeit aszerint, ahogyan egy jószág végighalad rajtuk!",o:["Beszerzés (beszerzési marketing)","Raktározás (raktárlogisztika)","Elosztás (szállítási logisztika)","Hulladékkezelés (hulladéklogisztika)"],e:"A javakat először beszerzik, majd raktározzák, aztán elosztják; a végén a maradékok, csomagolások és visszáruk kezelése a hulladéklogisztika feladata."}},{type:"match",level:2,de:{q:"Eine Tischlerei fertigt Esstische. Ordne die Güter richtig zu.",p:[["Eichenholz für die Tischplatte","Rohstoff"],["Leim und Schrauben","Hilfsstoff"],["Strom und Schmieröl für die Maschinen","Betriebsstoff"],["Holzpflegeöl, unverändert an Kund:innen verkauft","Handelsware"]],e:"Rohstoffe sind Hauptbestandteile, Hilfsstoffe Nebenbestandteile des Produkts. Betriebsstoffe werden verbraucht, gehen aber nicht ins Produkt ein. Handelswaren werden unverändert weiterverkauft."},en:{q:"A joinery makes dining tables. Match the goods correctly.",p:[["Oak wood for the table top","Raw material"],["Glue and screws","Auxiliary material"],["Electricity and machine oil","Operating supplies"],["Wood care oil resold unchanged to customers","Merchandise"]],e:"Raw materials are main components, auxiliary materials minor components of the product. Operating supplies are used up but do not become part of the product. Merchandise is resold unchanged."},hu:{q:"Egy asztalosműhely étkezőasztalokat gyárt. Párosítsd helyesen a javakat!",p:[["Tölgyfa az asztallaphoz","Alapanyag"],["Ragasztó és csavarok","Segédanyag"],["Áram és kenőolaj a gépekhez","Üzemi anyag"],["Faápoló olaj, változatlanul eladva a vevőknek","Kereskedelmi áru"]],e:"Az alapanyag a termék fő alkotórésze, a segédanyag mellékes alkotórésze. Az üzemi anyag elhasználódik, de nem épül be a termékbe. A kereskedelmi árut változatlanul adják tovább."}},{type:"mc",level:2,correctIndex:3,de:{q:"Eine Bäckereikette lässt Mehl an die Zentrale in Linz liefern, obwohl es dringend in der Filiale in Wels gebraucht wird. Gegen welche Anforderung der Materialwirtschaft wird verstoßen?",o:["Erforderliche Qualität","Richtige Menge","Richtiger Zeitpunkt","Richtiger Ort"],e:"Das Mehl ist da, aber nicht dort, wo es gebraucht wird – der Ort stimmt nicht. Menge und Qualität sind laut Sachverhalt in Ordnung."},en:{q:"A bakery chain has flour delivered to its head office in Linz although it is urgently needed in the branch in Wels. Which requirement of materials management is violated?",o:["Required quality","Right quantity","Right time","Right place"],e:"The flour has arrived, but not where it is needed – the place is wrong. According to the case, quantity and quality are fine."},hu:{q:"Egy pékséglánc a lisztet a linzi központba szállíttatja, pedig sürgősen a welsi fióküzletben lenne rá szükség. Az anyaggazdálkodás melyik követelményét sértik meg?",o:["Megfelelő minőség","Megfelelő mennyiség","Megfelelő időpont","Megfelelő hely"],e:"A liszt megérkezett, de nem oda, ahol szükség van rá – a hely nem stimmel. A mennyiség és a minőség az eset szerint rendben van."}},{type:"mc",level:3,correctIndex:0,de:{q:"Im Hotel Alpenblick möchte der Küchenchef große Tiefkühlvorräte, damit nie etwas ausgeht. Die Controllerin will den Bestand senken, um Kosten zu sparen. Welche Ziele stehen hier in Konflikt?",o:["Sachziel und ökonomisches Ziel","Ökonomisches und ökologisches Ziel","Soziales und ökologisches Ziel","Sachziel und soziales Ziel"],e:"Der Küchenchef verfolgt die störungsfreie Leistungserstellung (Sachziel), die Controllerin die Kostenminimierung (ökonomisches Ziel). Umwelt- oder Sozialaspekte spielen in diesem Fall keine Rolle."},en:{q:"At Hotel Alpenblick the head chef wants large frozen stocks so that nothing ever runs out. The controller wants to reduce stock to save costs. Which goals are in conflict here?",o:["Operational and economic goal","Economic and ecological goal","Social and ecological goal","Operational goal and social goal"],e:"The chef pursues smooth service (operational goal), the controller cost minimisation (economic goal). Environmental or social aspects play no role in this case."},hu:{q:"Az Alpenblick szállodában a séf nagy mélyhűtött készletet szeretne, hogy soha ne fogyjon ki semmi. A kontroller csökkenteni akarja a készletet a költségek miatt. Mely célok ütköznek itt?",o:["Tárgyi cél és gazdasági cél","Gazdasági és ökológiai cél","Társadalmi és ökológiai cél","Tárgyi cél és társadalmi cél"],e:"A séf a zavartalan teljesítményelőállítást (tárgyi cél), a kontroller a költségminimalizálást (gazdasági cél) képviseli. Környezeti vagy társadalmi szempont ebben az esetben nem játszik szerepet."}},{type:"text",level:2,de:{q:"Wie nennt man Stoffe, die als Nebenbestandteil in ein Produkt eingehen (z. B. Leim bei einem Tisch)?",a:["Hilfsstoffe","Hilfsstoff"],e:"Hilfsstoffe gehen in das Produkt ein, sind aber nur Nebenbestandteile. Hauptbestandteile sind Rohstoffe, Betriebsstoffe gehen gar nicht ins Produkt ein."},en:{q:"What are materials called that become a minor component of a product (e.g. glue in a table)?",a:["auxiliary materials","auxiliary material","supplies","indirect materials"],e:"Auxiliary materials become part of the product but only as minor components. Main components are raw materials; operating supplies do not become part of the product at all."},hu:{q:"Hogyan nevezzük azokat az anyagokat, amelyek mellékes alkotórészként épülnek be a termékbe (pl. a ragasztó egy asztalban)?",a:["segédanyag","segédanyagok"],e:"A segédanyag beépül a termékbe, de csak mellékes alkotórészként. A fő alkotórész az alapanyag, az üzemi anyag pedig egyáltalán nem épül be."}}],beschaffungsmarketing:[{type:"tf",level:1,correct:!0,de:{q:"Bei der Einzelbeschaffung wird erst dann bestellt, wenn ein konkreter Auftrag vorliegt.",e:"Richtig – dadurch ist die Lagerdauer kurz und nichts verdirbt. Nachteile sind mögliche Verzögerungen und geringere Rabatte."},en:{q:"With individual procurement, goods are only ordered once a specific customer order has been received.",e:"True – this keeps storage time short and nothing spoils. Drawbacks are possible delays and smaller discounts."},hu:{q:"Egyedi beszerzésnél csak akkor rendelnek, amikor konkrét megrendelés érkezett.",e:"Igaz – így rövid a raktározási idő, és semmi sem romlik meg. Hátránya a lehetséges késedelem és a kisebb engedmény."}},{type:"tf",level:2,correct:!1,de:{q:"Bei der programmgebundenen Bedarfsermittlung entscheidet der Lagerbestand, ob bestellt wird.",e:"Falsch – das ist die bestandsgesteuerte Bedarfsermittlung. Programmgebunden heißt: Die Menge ergibt sich aus dem Produktionsprogramm (Stückliste · Produktionsmenge)."},en:{q:"With programme-based requirements planning, the stock level decides whether to order.",e:"False – that is stock-based requirements planning. Programme-based means the quantity results from the production programme (bill of materials · production quantity)."},hu:{q:"Programhoz kötött szükségletszámításnál a raktárkészlet dönti el, hogy rendelnek-e.",e:"Hamis – ez a készletvezérelt szükségletszámítás. Programhoz kötött esetben a mennyiség a termelési programból adódik (darabjegyzék · gyártási mennyiség)."}},{type:"tf",level:3,correct:!1,de:{q:"Die Formel für die optimale Bestellmenge liefert auch bei stark schwankendem Verbrauch zuverlässige Ergebnisse.",e:"Falsch – die Formel setzt einen gleichmäßigen Verbrauch voraus. Bei stark schwankendem Bedarf (z. B. Z-Güter) passt sie laut Lehrbuch nicht."},en:{q:"The formula for the optimal order quantity also delivers reliable results when consumption fluctuates strongly.",e:"False – the formula assumes steady consumption. With strongly fluctuating demand (e.g. Z goods) it does not fit, as the textbook points out."},hu:{q:"Az optimális rendelési mennyiség képlete erősen ingadozó felhasználás esetén is megbízható eredményt ad.",e:"Hamis – a képlet egyenletes felhasználást feltételez. Erősen ingadozó szükségletnél (pl. Z-cikkek) a tankönyv szerint nem alkalmazható."}},{type:"multi",level:1,correct:[0,1,2],de:{q:"Welche Nachteile hat die Vorratsbeschaffung? Wähle alle zutreffenden.",o:["Hohe Lagerkosten","Hohe Kapitalbindung","Gefahr des Verderbs","Produktionsstopp bei Lieferverzug","Kaum Mengenrabatte"],e:"Wer große Mengen lagert, hat Lagerkosten, gebundenes Kapital und Verderbsrisiko. Produktionsstopp bei Lieferverzug ist das Risiko von Just-in-time; Mengenrabatte sind gerade ein Vorteil des Vorratskaufs."},en:{q:"What are the disadvantages of stockpiling (procurement for stock)? Select all that apply.",o:["High storage costs","High capital tie-up","Risk of spoilage","Production stop if delivery is late","Hardly any volume discounts"],e:"Storing large quantities causes storage costs, ties up capital and risks spoilage. A production stop due to late delivery is the risk of just-in-time; volume discounts are actually an advantage of buying for stock."},hu:{q:"Melyek a készletre történő beszerzés hátrányai? Jelöld az összes helyeset.",o:["Magas raktározási költség","Magas tőkelekötés","Romlás veszélye","Termelésleállás szállítási késedelem esetén","Alig van mennyiségi engedmény"],e:"A nagy mennyiség tárolása raktározási költséggel, tőkelekötéssel és romlási kockázattal jár. A szállítási késés miatti termelésleállás a just-in-time kockázata; a mennyiségi engedmény éppen a készletre vásárlás előnye."}},{type:"multi",level:2,correct:[0,1,2],de:{q:"Welche Aussagen treffen auf die zentrale Beschaffung zu? Wähle alle zutreffenden.",o:["Günstige Konditionen durch große Bestellmengen","Gute Kontrolle über den Einkauf","Mehr Verwaltungsaufwand","Flexibler bei Notfällen in einzelnen Filialen","Waren sind schneller vor Ort"],e:"Eine zentrale Einkaufsstelle bündelt Mengen und kontrolliert gut, ist aber verwaltungsintensiv und wenig flexibel. Flexibilität und schnelle Verfügbarkeit vor Ort sind Vorteile der dezentralen Beschaffung."},en:{q:"Which statements apply to centralised procurement? Select all that apply.",o:["Favourable terms thanks to large order quantities","Good control over purchasing","More administrative work","More flexible in emergencies at individual branches","Goods arrive on site faster"],e:"One central purchasing unit bundles quantities and controls well, but is admin-heavy and not very flexible. Flexibility and fast local availability are advantages of decentralised procurement."},hu:{q:"Mely állítások igazak a központosított beszerzésre? Jelöld az összes helyeset.",o:["Kedvező feltételek a nagy rendelési mennyiség miatt","Jó ellenőrizhetőség","Nagyobb adminisztratív teher","Rugalmasabb az egyes fióktelepek vészhelyzeteiben","Az áru gyorsabban helyben van"],e:"A központi beszerzés összevonja a mennyiségeket és jól ellenőrizhető, de adminisztrációigényes és kevésbé rugalmas. A rugalmasság és a gyors helyi elérhetőség a decentralizált beszerzés előnye."}},{type:"order",level:3,de:{q:"Bringe die Teilbereiche des Beschaffungsmarketings in die richtige Reihenfolge.",o:["Beschaffungsmarktforschung","Beschaffungsprogrammpolitik","Beschaffungsmethodenpolitik","Beschaffungskonditionenpolitik","Beschaffungskommunikationspolitik","Beschaffungsdurchführung und -kontrolle"],e:"Zuerst Märkte und Lieferanten erforschen, dann festlegen, was (Programm) und nach welchem Prinzip (Methode) gekauft wird, zu welchen Konditionen, wie man die Lieferantenbeziehung pflegt – und schließlich durchführen und kontrollieren."},en:{q:"Put the sub-areas of procurement marketing in the correct order.",o:["Procurement market research","Procurement programme policy","Procurement method policy","Procurement terms policy","Procurement communication policy","Procurement execution and control"],e:"First research markets and suppliers, then decide what to buy (programme), by which principle (method), on which terms, how to maintain supplier relations – and finally execute and control."},hu:{q:"Állítsd helyes sorrendbe a beszerzési marketing részterületeit!",o:["Beszerzési piackutatás","Beszerzési programpolitika","Beszerzési módszerpolitika","Beszerzési kondíciópolitika","Beszerzési kommunikációs politika","A beszerzés lebonyolítása és ellenőrzése"],e:"Először a piacokat és beszállítókat kutatják fel, aztán eldöntik, mit (program) és milyen elv szerint (módszer) vásárolnak, milyen feltételekkel, hogyan ápolják a beszállítói kapcsolatot – végül lebonyolítják és ellenőrzik a beszerzést."}},{type:"match",level:3,de:{q:"Ordne jeder ABC-XYZ-Kombination das passende Beschaffungsprinzip zu.",p:[["AX – hoher Wert, regelmäßiger Verbrauch","Just-in-time-Beschaffung"],["CX – geringer Wert, regelmäßiger Verbrauch","Vorratsbeschaffung"],["AZ – hoher Wert, sehr unregelmäßiger Verbrauch","Einzelbeschaffung"]],e:"Teure, planbare Güter kommen just in time (kaum Kapitalbindung). Billige, planbare Güter kauft man auf Vorrat. Teure, unplanbare Güter bestellt man erst, wenn ein Auftrag da ist."},en:{q:"Match each ABC-XYZ combination with the appropriate procurement principle.",p:[["AX – high value, regular consumption","Just-in-time procurement"],["CX – low value, regular consumption","Procurement for stock"],["AZ – high value, very irregular consumption","Individual procurement"]],e:"Expensive, predictable goods arrive just in time (little capital tied up). Cheap, predictable goods are bought for stock. Expensive, unpredictable goods are ordered only when there is a customer order."},hu:{q:"Párosítsd az ABC-XYZ kombinációkat a megfelelő beszerzési elvvel!",p:[["AX – nagy érték, rendszeres felhasználás","Just-in-time beszerzés"],["CX – kis érték, rendszeres felhasználás","Készletre történő beszerzés"],["AZ – nagy érték, nagyon rendszertelen felhasználás","Egyedi beszerzés"]],e:"A drága, jól tervezhető cikkek just-in-time érkeznek (alig van tőkelekötés). Az olcsó, tervezhető cikkeket készletre veszik. A drága, nem tervezhető cikkeket csak megrendelés esetén rendelik meg."}},{type:"mc",level:2,correctIndex:1,de:{q:"Eine Tischlerei bestellt ihre Spanplatten über das Webportal ihres Holzgroßhändlers, auf dem viele Tischlereien einkaufen können. Welche Form des E-Procurements liegt vor?",o:["Geschlossenes System","Halboffenes System","Offenes System","Bestellrhythmussystem"],e:"Das Portal eines einzelnen Händlers, auf dem mehrere Kund:innen bestellen, ist ein halboffenes System. Geschlossen wäre eine exklusive Verbindung zweier Partner, offen ein Marktplatz vieler Anbieter (z. B. Amazon Business)."},en:{q:"A joinery orders its chipboard via the web portal of its timber wholesaler, where many joineries can shop. Which form of e-procurement is this?",o:["Closed system","Semi-open system","Open system","Fixed-interval ordering system"],e:"The portal of a single supplier on which several customers order is a semi-open system. Closed would be an exclusive link between two partners, open a marketplace with many suppliers (e.g. Amazon Business)."},hu:{q:"Egy asztalosműhely a forgácslapot a fa-nagykereskedője webportálján rendeli, ahol sok asztalos vásárolhat. Az e-beszerzés melyik formájáról van szó?",o:["Zárt rendszer","Félig nyitott rendszer","Nyitott rendszer","Rendelési ciklus rendszer"],e:"Egyetlen kereskedő portálja, ahol több vevő rendel, félig nyitott rendszer. Zárt rendszer két partner kizárólagos kapcsolata lenne, nyitott egy sok szállítót felvonultató piactér (pl. Amazon Business)."}},{type:"mc",level:3,correctIndex:2,de:{q:"Durch steigende Zinsen erhöht sich Loopys Lagerhaltungskostensatz deutlich. Alle anderen Werte bleiben gleich. Wie verändert sich die optimale Bestellmenge?",o:["Sie steigt, weil größere Mengen Rabatte bringen","Sie bleibt gleich, weil nur Bestellkosten zählen","Sie sinkt – kleinere Mengen, öfter bestellen","Sie steigt, weil die Bestellkosten sinken"],e:"Der Lagerhaltungskostensatz (Zinssatz + Lagerkostensatz) steht im Nenner der Formel. Wird Lagern teurer, lohnt es sich, kleinere Mengen häufiger zu bestellen."},en:{q:"Due to rising interest rates, Loopy's holding cost rate rises significantly. All other values stay the same. How does the optimal order quantity change?",o:["It rises because larger quantities bring discounts","It stays the same because only ordering costs count","It falls – smaller quantities, ordered more often","It rises because ordering costs fall"],e:"The holding cost rate (interest rate + storage cost rate) is in the denominator of the formula. If storing gets more expensive, it pays to order smaller quantities more often."},hu:{q:"Az emelkedő kamatok miatt Loopy készlettartási költségrátája jelentősen nő. Minden más érték változatlan. Hogyan változik az optimális rendelési mennyiség?",o:["Nő, mert a nagyobb mennyiség engedményt hoz","Változatlan, mert csak a rendelési költség számít","Csökken – kisebb tételek, gyakoribb rendelés","Nő, mert a rendelési költség csökken"],e:"A készlettartási költségráta (kamatláb + raktározási költségráta) a képlet nevezőjében áll. Ha a tárolás drágul, érdemes kisebb tételeket gyakrabban rendelni."}},{type:"number",level:2,value:140,tol:.01,unit:{de:"kg",en:"kg",hu:"kg"},de:{q:"Loopy plant 1.200 Pralinenschachteln. Laut Stückliste braucht jede Schachtel 0,15 kg Schokolade. Im Lager sind noch 40 kg. Wie hoch ist der Nettobedarf an Schokolade?",e:"Bruttobedarf = 0,15 kg · 1.200 = 180 kg. Nettobedarf = 180 − 40 (Lagerbestand) = 140 kg. Nur der Nettobedarf muss tatsächlich beschafft werden."},en:{q:"Loopy plans 1,200 boxes of chocolates. According to the bill of materials, each box needs 0.15 kg of chocolate. There are still 40 kg in stock. What is the net requirement for chocolate?",e:"Gross requirement = 0.15 kg · 1,200 = 180 kg. Net requirement = 180 − 40 (stock) = 140 kg. Only the net requirement actually has to be procured."},hu:{q:"Loopy 1200 doboz bonbont tervez. A darabjegyzék szerint dobozonként 0,15 kg csokoládé kell. A raktárban még 40 kg van. Mekkora a csokoládé nettó szükséglete?",e:"Bruttó szükséglet = 0,15 kg · 1200 = 180 kg. Nettó szükséglet = 180 − 40 (raktárkészlet) = 140 kg. Csak a nettó szükségletet kell ténylegesen beszerezni."}},{type:"text",level:1,de:{q:"Wie heißt die Analyse, die Güter nach der Regelmäßigkeit ihres Verbrauchs in drei Klassen einteilt?",a:["XYZ-Analyse","XYZ Analyse","XYZ"],e:"Die XYZ-Analyse unterscheidet X- (regelmäßig), Y- (saisonal schwankend) und Z-Güter (sehr unregelmäßig). Die ABC-Analyse teilt dagegen nach dem Wertanteil ein."},en:{q:"What is the analysis called that divides goods into three classes according to how regularly they are consumed?",a:["XYZ analysis","XYZ-analysis","XYZ"],e:"XYZ analysis distinguishes X (regular), Y (seasonally fluctuating) and Z goods (very irregular). ABC analysis, by contrast, classifies by share of value."},hu:{q:"Hogyan nevezzük azt az elemzést, amely a javakat felhasználásuk rendszeressége szerint három csoportba sorolja?",a:["XYZ-elemzés","XYZ elemzés","XYZ-analízis","XYZ"],e:"Az XYZ-elemzés X- (rendszeres), Y- (szezonálisan ingadozó) és Z-cikkeket (nagyon rendszertelen) különböztet meg. Az ABC-elemzés ezzel szemben az értékarány szerint csoportosít."}}],"lager-transport-entsorgung":[{type:"tf",level:1,correct:!1,de:{q:"Eine hohe Lagerumschlagsdauer ist ein Zeichen für eine effiziente Lagerhaltung.",e:"Falsch – die Umschlagsdauer soll GERING sein: Ware liegt dann nur kurz im Lager und bindet wenig Kapital. Hoch sein soll die Umschlagshäufigkeit."},en:{q:"A long average storage period (stock turnover period) is a sign of efficient warehousing.",e:"False – the storage period should be SHORT: goods then stay in stock only briefly and tie up little capital. It is the turnover rate that should be high."},hu:{q:"A hosszú készletforgási idő hatékony raktározásra utal.",e:"Hamis – a forgási időnek RÖVIDNEK kell lennie: az áru így csak rövid ideig van raktáron, és kevés tőkét köt le. A forgási sebességnek kell magasnak lennie."}},{type:"tf",level:2,correct:!0,de:{q:"Beim Festplatzsystem muss für jede Ware so viel Platz reserviert werden, wie ihre höchste Bestellmenge benötigt.",e:"Richtig – jede Ware hat ihren fixen Platz, auch wenn er gerade fast leer ist. Deshalb nutzt das Festplatzsystem den Raum schlechter als das Freiplatzsystem."},en:{q:"With a fixed-location system, each item needs reserved space large enough for its biggest order quantity.",e:"True – each item has its fixed place, even when it is almost empty. That is why the fixed-location system uses space less efficiently than the free-location system."},hu:{q:"Fix helyes tárolásnál minden árunak akkora helyet kell fenntartani, amekkorát a legnagyobb rendelési mennyisége igényel.",e:"Igaz – minden árunak megvan a fix helye, akkor is, ha az éppen majdnem üres. Ezért a fix helyes rendszer rosszabbul használja ki a teret, mint a szabad helyes."}},{type:"tf",level:3,correct:!1,de:{q:"Gefahrengüter eignen sich besonders gut für das Freiplatzsystem, weil sie dort flexibel auf freie Plätze verteilt werden können.",e:"Falsch – laut Lehrbuch ist das chaotische Lager gerade NICHT für Gefahrengüter geeignet: Sie brauchen fest zugewiesene, speziell gesicherte Lagerplätze."},en:{q:"Hazardous goods are particularly well suited to the free-location system because they can be spread flexibly across free spaces.",e:"False – according to the textbook, chaotic storage is precisely NOT suitable for hazardous goods: they need fixed, specially secured storage locations."},hu:{q:"A veszélyes áruk különösen alkalmasak a szabad helyes tárolásra, mert ott rugalmasan eloszthatók a szabad helyeken.",e:"Hamis – a tankönyv szerint a kaotikus raktár éppen NEM alkalmas veszélyes árukra: ezeknek kijelölt, külön biztosított tárolóhely kell."}},{type:"multi",level:2,correct:[0,1,2,3],de:{q:"Mit welchen Maßnahmen kann ein Unternehmen seine Lagerumschlagshäufigkeit erhöhen? Wähle alle zutreffenden.",o:["Bestände überwachen und Höchstbestände festlegen","Das Angebot verschlanken","Just-in-time-Belieferung","Aktionen für Ladenhüter","Größere Vorratskäufe wegen Mengenrabatt","Ein zusätzliches Lager anmieten"],e:"Weniger Bestand bei gleichem Wareneinsatz erhöht die Umschlagshäufigkeit. Größere Vorratskäufe und mehr Lagerfläche erhöhen den Ø Lagerbestand und senken sie."},en:{q:"Which measures can a company use to increase its stock turnover rate? Select all that apply.",o:["Monitor stock and set maximum stock levels","Slim down the range","Just-in-time deliveries","Promotions for slow-moving items","Larger stock purchases for volume discounts","Rent an additional warehouse"],e:"Less stock with the same cost of goods sold raises the turnover rate. Larger stock purchases and more storage space increase average stock and lower it."},hu:{q:"Milyen intézkedésekkel növelheti egy vállalat a készletforgási sebességet? Jelöld az összes helyeset.",o:["Készletfigyelés és maximális készletszint meghatározása","A kínálat szűkítése","Just-in-time szállítás","Akciók a nehezen eladható árukra","Nagyobb készletvásárlás mennyiségi engedményért","Egy további raktár bérlése"],e:"Változatlan anyag-, ill. áruráfordítás mellett kisebb készlet növeli a forgási sebességet. A nagyobb készletvásárlás és a több raktárterület növeli az átlagkészletet, így csökkenti azt."}},{type:"multi",level:1,correct:[0,1,2],de:{q:"Welche Tätigkeiten gehören zur Entsorgungslogistik? Wähle alle zutreffenden.",o:["Verpackungsmaterial sammeln und sortieren","Retouren abwickeln","Ausschuss aus der Produktion abtransportieren","Lieferrouten zu den Kund:innen planen","Neue Lieferanten auswählen"],e:"Die Entsorgungslogistik kümmert sich um Reste, Ausschuss, Verpackungen und Retouren. Lieferrouten planen gehört zur Transportlogistik, Lieferantenauswahl zum Beschaffungsmarketing."},en:{q:"Which activities belong to disposal logistics? Select all that apply.",o:["Collecting and sorting packaging material","Handling returns","Removing production scrap","Planning delivery routes to customers","Selecting new suppliers"],e:"Disposal logistics deals with leftovers, scrap, packaging and returns. Planning delivery routes belongs to transport logistics, choosing suppliers to procurement marketing."},hu:{q:"Mely tevékenységek tartoznak a hulladéklogisztikához? Jelöld az összes helyeset.",o:["Csomagolóanyag gyűjtése és válogatása","Visszáruk kezelése","A gyártási selejt elszállítása","Szállítási útvonalak tervezése a vevőkhöz","Új beszállítók kiválasztása"],e:"A hulladéklogisztika a maradékokkal, selejttel, csomagolással és visszárukkal foglalkozik. Az útvonaltervezés a szállítási logisztikához, a beszállítóválasztás a beszerzési marketinghez tartozik."}},{type:"order",level:1,de:{q:"Bringe die Stufen der Abfallhierarchie in die richtige Reihenfolge – die wichtigste zuerst.",o:["Abfallvermeidung","Vorbereitung zur Wiederverwendung","Recycling","Sonstige Verwertung (z. B. Energie)","Beseitigung"],e:"Am besten entsteht Abfall gar nicht. Danach folgen Wiederverwendung, Recycling und sonstige Verwertung; beseitigt wird nur, wenn nichts anderes möglich ist."},en:{q:"Put the levels of the waste hierarchy in the correct order – the most important first.",o:["Waste prevention","Preparing for reuse","Recycling","Other recovery (e.g. energy)","Disposal"],e:"Best of all, waste is not created at all. Then come reuse, recycling and other recovery; disposal only happens when nothing else is possible."},hu:{q:"Állítsd helyes sorrendbe a hulladékhierarchia szintjeit – a legfontosabbal kezdve!",o:["Hulladékmegelőzés","Újrahasználatra való előkészítés","Újrafeldolgozás (recycling)","Egyéb hasznosítás (pl. energetikai)","Ártalmatlanítás"],e:"A legjobb, ha hulladék nem is keletkezik. Ezt követi az újrahasználat, az újrafeldolgozás és az egyéb hasznosítás; ártalmatlanítani csak akkor szabad, ha más nem lehetséges."}},{type:"match",level:2,de:{q:"Ordne jedem Fall die passende Lagerfunktion zu.",p:[["Loopy hält eine Reserve Kakao für Lieferverzögerungen","Sicherung"],["Ein Spielwarenhändler lagert ab Juli für das Weihnachtsgeschäft","Ausgleich (Überbrückung)"],["Im Möbelhaus ist die Ausstellungsfläche zugleich Lager","Warenpräsentation"],["Eine Sammelstelle für Kartonagen und Retouren","Entsorgung"],["Ein Weingut lässt Wein im Holzfass reifen","Umformung (Reifung)"]],e:"Sicherung = Reserve, Ausgleich = Zeit zwischen Einkauf und Absatz überbrücken, Warenpräsentation = Lager als Verkaufsraum, Entsorgung = Reste sammeln, Umformung = Güter verändern sich im Lager."},en:{q:"Match each case with the appropriate warehouse function.",p:[["Loopy keeps a cocoa reserve in case of delivery delays","Safety"],["A toy shop stocks up from July for Christmas","Balancing (bridging time)"],["In the furniture store the showroom is also the warehouse","Product presentation"],["A collection point for cardboard and returns","Disposal"],["A winery lets wine mature in wooden barrels","Transformation (maturing)"]],e:"Safety = reserve, balancing = bridging the time between purchase and sale, presentation = warehouse as salesroom, disposal = collecting leftovers, transformation = goods change while stored."},hu:{q:"Párosítsd az eseteket a megfelelő raktározási funkcióval!",p:[["Loopy kakaótartalékot tart szállítási késések esetére","Biztonsági funkció"],["Egy játékbolt júliustól készletez a karácsonyi szezonra","Kiegyenlítő (áthidaló) funkció"],["A bútoráruházban a bemutatótér egyben raktár","Árubemutató funkció"],["Gyűjtőhely kartonok és visszáruk számára","Hulladékkezelési funkció"],["Egy borászat fahordóban érleli a bort","Átalakító (érlelő) funkció"]],e:"Biztonság = tartalék, kiegyenlítés = a beszerzés és értékesítés közötti idő áthidalása, árubemutatás = a raktár egyben eladótér, hulladékkezelés = maradékok gyűjtése, átalakítás = a jószág raktározás közben változik."}},{type:"mc",level:2,correctIndex:1,de:{q:"Ein Baumarkt lagert Holzbretter und Gartenmöbel auf einer befestigten, eingezäunten Fläche mit Dach. Um welche Lagerart nach der Bauform handelt es sich?",o:["Offenes Lager","Halboffenes Lager","Geschlossenes Lager","Freiplatzsystem"],e:"Eine befestigte Fläche mit Zaun und/oder Dach ist ein halboffenes Lager. Offen wäre eine ungeschützte Fläche (Sand, Rohholz), geschlossen ein Gebäude. Das Freiplatzsystem betrifft die Platzzuordnung, nicht die Bauform."},en:{q:"A DIY store keeps wooden boards and garden furniture on a paved, fenced area with a roof. Which type of warehouse (by construction) is this?",o:["Open warehouse","Semi-open warehouse","Closed warehouse","Free-location system"],e:"A paved area with a fence and/or roof is a semi-open warehouse. Open would be an unprotected area (sand, logs), closed a building. The free-location system concerns slot allocation, not construction."},hu:{q:"Egy barkácsáruház a deszkákat és kerti bútorokat burkolt, bekerített, tetővel fedett területen tárolja. Építési mód szerint milyen raktárról van szó?",o:["Nyitott raktár","Félig nyitott raktár","Zárt raktár","Szabad helyes tárolás"],e:"A burkolt, kerítéssel és/vagy tetővel ellátott terület félig nyitott raktár. Nyitott lenne egy védtelen terület (homok, rönkfa), zárt egy épület. A szabad helyes tárolás a helykiosztásra vonatkozik, nem az építési módra."}},{type:"mc",level:3,correctIndex:0,de:{q:"Händler A hat eine Lagerumschlagshäufigkeit von 8, Händler B eine Lagerumschlagsdauer von 30 Tagen (Jahr = 365 Tage). Wer wirtschaftet beim Lager effizienter?",o:["B, seine Umschlagshäufigkeit liegt bei rund 12","A, weil 8 Umschläge mehr sind als bei B","A, seine Lagerdauer ist mit rund 46 Tagen kürzer","Beide gleich, die Kennzahlen sind nicht vergleichbar"],e:"Umrechnen: B: 365 / 30 ≈ 12,2 Umschläge; A: 365 / 8 ≈ 45,6 Tage Lagerdauer. B schlägt sein Lager öfter um und hat die kürzere Lagerdauer – B ist effizienter."},en:{q:"Retailer A has a stock turnover rate of 8, retailer B an average storage period of 30 days (year = 365 days). Who manages stock more efficiently?",o:["B, its turnover rate is about 12","A, because 8 turns are more than B's","A, its storage period is shorter at about 46 days","Both equal, the ratios cannot be compared"],e:"Convert: B: 365 / 30 ≈ 12.2 turns; A: 365 / 8 ≈ 45.6 days storage period. B turns its stock over more often and has the shorter storage period – B is more efficient."},hu:{q:"Az A kereskedő készletforgási sebessége 8, a B kereskedő készletforgási ideje 30 nap (év = 365 nap). Ki gazdálkodik hatékonyabban a készlettel?",o:["B, forgási sebessége kb. 12","A, mert a 8 forduló több, mint B-é","A, forgási ideje kb. 46 nappal rövidebb","Egyformák, a mutatók nem összehasonlíthatók"],e:"Átszámítás: B: 365 / 30 ≈ 12,2 forduló; A: 365 / 8 ≈ 45,6 nap forgási idő. B gyakrabban forgatja meg a készletét, és rövidebb a forgási ideje – B a hatékonyabb."}},{type:"number",level:2,value:5,tol:.01,de:{q:"Loopy hat im Jahr 5.000 Packungen Pralinen verkauft, der Einstandspreis beträgt 12 € pro Packung. Der Lagerbestand betrug am Jahresanfang 10.000 € und am Jahresende 14.000 €. Berechne die Lagerumschlagshäufigkeit.",e:"Wareneinsatz = 12 € · 5.000 = 60.000 €. Ø Lagerbestand = (10.000 + 14.000) / 2 = 12.000 €. Umschlagshäufigkeit = 60.000 / 12.000 = 5 – das Lager wird 5-mal pro Jahr umgeschlagen."},en:{q:"Loopy sold 5,000 boxes of chocolates during the year; the purchase cost is €12 per box. Stock was worth €10,000 at the beginning of the year and €14,000 at the end. Calculate the stock turnover rate.",e:"Cost of goods sold = €12 · 5,000 = €60,000. Average stock = (10,000 + 14,000) / 2 = €12,000. Turnover rate = 60,000 / 12,000 = 5 – stock is turned over 5 times a year."},hu:{q:"Loopy egy év alatt 5000 doboz bonbont adott el, a beszerzési ár dobozonként 12 €. A készlet értéke az év elején 10 000 €, az év végén 14 000 € volt. Számítsd ki a készletforgási sebességet!",e:"Eladott áruk beszerzési értéke = 12 € · 5000 = 60 000 €. Átlagkészlet = (10 000 + 14 000) / 2 = 12 000 €. Forgási sebesség = 60 000 / 12 000 = 5 – a készlet évente ötször fordul meg."}},{type:"number",level:3,value:15,tol:.01,unit:{de:"%",en:"%",hu:"%"},de:{q:"Die Lagerkosten einer Tischlerei betragen im Jahr 3.600 €. Der Lagerbestand lag am 1. Jänner bei 20.000 € und am 31. Dezember bei 28.000 €. Wie hoch sind die Lagerkosten in % des durchschnittlichen Lagerbestands?",e:"Ø Lagerbestand = (20.000 + 28.000) / 2 = 24.000 €. Lagerkosten in % = 3.600 / 24.000 · 100 = 15 %. Achtung: durch den Ø Lagerbestand dividieren, nicht durch den Endbestand."},en:{q:"A joinery's annual storage costs are €3,600. Stock was €20,000 on 1 January and €28,000 on 31 December. What are the storage costs as a percentage of average stock?",e:"Average stock = (20,000 + 28,000) / 2 = €24,000. Storage costs in % = 3,600 / 24,000 · 100 = 15 %. Careful: divide by average stock, not by closing stock."},hu:{q:"Egy asztalosműhely éves raktározási költsége 3600 €. A készlet január 1-jén 20 000 €, december 31-én 28 000 € volt. Hány százaléka a raktározási költség az átlagkészletnek?",e:"Átlagkészlet = (20 000 + 28 000) / 2 = 24 000 €. Raktározási költség % = 3600 / 24 000 · 100 = 15 %. Figyelem: az átlagkészlettel kell osztani, nem a záró készlettel."}}],"supply-chain-management":[{type:"tf",level:1,correct:!0,de:{q:"In einer Lieferkette fließen nicht nur Güter, sondern auch Geld, Dienstleistungen und Informationen.",e:"Richtig – Güter wandern Richtung Endverbraucher:in, Geld fließt zurück, und Informationen (z. B. Bestellungen, Absatzdaten) werden in beide Richtungen ausgetauscht."},en:{q:"In a supply chain, not only goods flow, but also money, services and information.",e:"True – goods move towards the end consumer, money flows back, and information (e.g. orders, sales data) is exchanged in both directions."},hu:{q:"Az ellátási láncban nemcsak áruk, hanem pénz, szolgáltatások és információk is áramlanak.",e:"Igaz – az áruk a végfelhasználó felé haladnak, a pénz visszafelé áramlik, az információk (pl. rendelések, értékesítési adatok) pedig mindkét irányban."}},{type:"tf",level:2,correct:!1,de:{q:"Pufferbestände sind im Supply-Chain-Management grundsätzlich zu vermeiden, weil sie nur Kosten verursachen und die Versorgung nicht sichern.",e:"Falsch – Pufferbestände kosten zwar Geld, sichern aber die Versorgung bei Störungen. Sie sind eine der Maßnahmen für eine resiliente Supply Chain."},en:{q:"In supply chain management, buffer stocks should always be avoided because they only cause costs and do not secure supply.",e:"False – buffer stocks do cost money, but they secure supply when disruptions occur. They are one of the measures for a resilient supply chain."},hu:{q:"Az ellátásilánc-menedzsmentben a pufferkészleteket mindig kerülni kell, mert csak költséget okoznak, és nem biztosítják az ellátást.",e:"Hamis – a pufferkészlet valóban pénzbe kerül, de zavarok esetén biztosítja az ellátást. Az ellenálló (reziliens) ellátási lánc egyik eszköze."}},{type:"tf",level:2,correct:!0,de:{q:"Nach dem EU-Lieferkettengesetz (2024) dürfen EU-Unternehmen nicht mit Lieferanten zusammenarbeiten, die Kinder- oder Zwangsarbeit einsetzen.",e:"Richtig – Unternehmen tragen damit Verantwortung für die gesamte Lieferkette, nicht nur für den eigenen Betrieb."},en:{q:"Under the EU Supply Chain Act (2024), EU companies may not work with suppliers who use child or forced labour.",e:"True – companies thus bear responsibility for the entire supply chain, not just for their own operations."},hu:{q:"Az uniós ellátásilánc-irányelv (2024) szerint az EU-s vállalatok nem dolgozhatnak olyan beszállítókkal, amelyek gyermek- vagy kényszermunkát alkalmaznak.",e:"Igaz – a vállalatok így a teljes ellátási láncért felelősek, nem csak a saját üzemükért."}},{type:"tf",level:3,correct:!1,de:{q:"Durch Supply-Chain-Management steigt typischerweise die Kapitalbindung, weil alle Partner höhere Lagerbestände halten müssen.",e:"Falsch – eine Chance des SCM ist gerade WENIGER Kapitalbindung: Durch Zusammenarbeit und Datenaustausch wird der Bedarf besser vorhersagbar, die Lagerbestände sinken."},en:{q:"Supply chain management typically increases capital tie-up because all partners have to hold higher stocks.",e:"False – one opportunity of SCM is precisely LESS capital tie-up: cooperation and data exchange make demand more predictable, so stocks fall."},hu:{q:"Az ellátásilánc-menedzsment jellemzően növeli a tőkelekötést, mert minden partnernek nagyobb készletet kell tartania.",e:"Hamis – az SCM egyik lehetősége éppen a KISEBB tőkelekötés: az együttműködés és az adatcsere révén a kereslet jobban előre jelezhető, a készletek csökkennek."}},{type:"multi",level:2,correct:[0,1,2,4],de:{q:"Welche Risiken des Supply-Chain-Managements nennt das Lehrbuch? Wähle alle zutreffenden.",o:["Internes Wissen wird öffentlich","Imageschaden durch Fehler anderer Partner","Abhängigkeit – ein Ausfall trifft die ganze Kette","Längere Durchlaufzeiten","Hoher Zeitaufwand und Komplexität","Höhere Kapitalbindung"],e:"Wer eng zusammenarbeitet, teilt Wissen, haftet beim Image mit und wird abhängig; die Abstimmung ist aufwendig. Kürzere Durchlaufzeit und weniger Kapitalbindung sind dagegen Chancen des SCM."},en:{q:"Which risks of supply chain management does the textbook name? Select all that apply.",o:["Internal know-how becomes public","Damage to image through other partners' mistakes","Dependence – one failure hits the whole chain","Longer lead times","High time expenditure and complexity","Higher capital tie-up"],e:"Working closely means sharing know-how, sharing image risks and becoming dependent; coordination is demanding. Shorter lead times and less capital tie-up are opportunities of SCM."},hu:{q:"Milyen kockázatait említi a tankönyv az ellátásilánc-menedzsmentnek? Jelöld az összes helyeset.",o:["A belső tudás nyilvánossá válik","Imázsromlás más partnerek hibái miatt","Függőség – egy kiesés az egész láncot sújtja","Hosszabb átfutási idő","Nagy időráfordítás és összetettség","Nagyobb tőkelekötés"],e:"A szoros együttműködés tudásmegosztással, közös imázskockázattal és függőséggel jár; az összehangolás munkaigényes. A rövidebb átfutási idő és a kisebb tőkelekötés viszont az SCM lehetőségei."}},{type:"multi",level:3,correct:[0,1,2,5],de:{q:"Ein Elektronikhersteller will seine Supply Chain resilienter machen. Welche Maßnahmen sind dafür geeignet? Wähle alle zutreffenden.",o:["Multi-Sourcing: Bauteile von mehreren Lieferanten","Pufferbestände für kritische Bauteile","APS-Software zur Planung und Steuerung","Umstieg auf den einen billigsten Lieferanten","Lagerbestände konsequent auf null senken","Transparenter Datenaustausch mit Partnern"],e:"Mehrere Lieferanten, Puffer, Planungssoftware und offene Kooperation federn Störungen ab. Ein einziger Lieferant und null Lagerbestand machen die Kette dagegen anfälliger – effizient, aber nicht resilient."},en:{q:"An electronics manufacturer wants to make its supply chain more resilient. Which measures are suitable? Select all that apply.",o:["Multi-sourcing: components from several suppliers","Buffer stocks for critical components","APS software for planning and control","Switching to the single cheapest supplier","Consistently reducing stocks to zero","Transparent data exchange with partners"],e:"Several suppliers, buffers, planning software and open cooperation cushion disruptions. A single supplier and zero stock make the chain more vulnerable – efficient, but not resilient."},hu:{q:"Egy elektronikai gyártó ellenállóbbá akarja tenni az ellátási láncát. Mely intézkedések alkalmasak erre? Jelöld az összes helyeset.",o:["Multi-sourcing: alkatrészek több beszállítótól","Pufferkészlet a kritikus alkatrészekből","APS-szoftver a tervezéshez és irányításhoz","Átállás egyetlen, a legolcsóbb beszállítóra","A készletek következetes nullára csökkentése","Átlátható adatcsere a partnerekkel"],e:"A több beszállító, a puffer, a tervezőszoftver és a nyílt együttműködés tompítja a zavarokat. Egyetlen beszállító és nulla készlet viszont sérülékenyebbé teszi a láncot – hatékony, de nem ellenálló."}},{type:"order",level:1,de:{q:"Bringe die Glieder der Supply Chain für Pralinen in die richtige Reihenfolge.",o:["Vorlieferant (Kakaobauer)","Lieferant (Kuvertürehersteller)","Hersteller (Pralinenmanufaktur)","Handel (Loopys Candy Store)","Endverbraucher:in","Entsorger (Verpackungsrecycling)"],e:"Die Kette reicht vom Rohstoff über Verarbeitung und Handel bis zur Endverbraucher:in; am Ende kommt noch der Entsorger für Verpackungen und Reste."},en:{q:"Put the links of the supply chain for chocolates in the correct order.",o:["Sub-supplier (cocoa farmer)","Supplier (couverture producer)","Manufacturer (chocolate maker)","Retail (Loopy's Candy Store)","End consumer","Disposal company (packaging recycling)"],e:"The chain runs from the raw material through processing and retail to the end consumer; finally comes the disposal company for packaging and leftovers."},hu:{q:"Állítsd helyes sorrendbe a bonbonok ellátási láncának szemeit!",o:["Előbeszállító (kakaótermelő)","Beszállító (tortabevonó-gyártó)","Gyártó (bonbonmanufaktúra)","Kereskedelem (Loopy édességboltja)","Végfelhasználó","Hulladékkezelő (csomagolás-újrahasznosítás)"],e:"A lánc a nyersanyagtól a feldolgozáson és a kereskedelmen át a végfelhasználóig tart; a végén a csomagolást és a maradékot kezelő hulladékkezelő áll."}},{type:"match",level:1,de:{q:"Ordne jeder SCM-Maßnahme ihre Bedeutung zu.",p:[["Multi-Sourcing","Mehrere Lieferanten statt einem"],["APS-System","Software für Planung und Steuerung"],["Pufferbestand","Reserve, die die Versorgung sichert"],["Kundenorientierung","Alles auf Kundenbedürfnisse ausrichten"]],e:"Diese Maßnahmen machen eine Supply Chain erfolgreicher und widerstandsfähiger; die meisten kosten aber Geld oder Koordination."},en:{q:"Match each SCM measure with its meaning.",p:[["Multi-sourcing","Several suppliers instead of one"],["APS system","Software for planning and control"],["Buffer stock","Reserve that secures supply"],["Customer orientation","Aligning everything to customer needs"]],e:"These measures make a supply chain more successful and resilient; most of them, however, cost money or coordination."},hu:{q:"Párosítsd az SCM-intézkedéseket a jelentésükkel!",p:[["Multi-sourcing","Több beszállító egy helyett"],["APS-rendszer","Tervező és irányító szoftver"],["Pufferkészlet","Az ellátást biztosító tartalék"],["Vevőorientáció","Mindent a vevői igényekhez igazítani"]],e:"Ezek az intézkedések sikeresebbé és ellenállóbbá teszik az ellátási láncot; a legtöbbjük azonban pénzbe vagy koordinációba kerül."}},{type:"mc",level:2,correctIndex:2,de:{q:"Ein Sportartikelhändler teilt seine Verkaufsdaten in Echtzeit mit dem Hersteller und dessen Lieferanten. Welche Chance des SCM wird dadurch vor allem genutzt?",o:["Die Abhängigkeit von Partnern sinkt","Internes Wissen bleibt besser geschützt","Bedarf besser vorhersagbar, weniger Lager","Längere Durchlaufzeit, dafür mehr Termintreue"],e:"Echtzeitdaten machen den Bedarf planbar – alle Stufen können mit kleineren Lagern arbeiten. Wissensschutz und Unabhängigkeit verbessern sich dadurch gerade nicht (das sind eher Risiken)."},en:{q:"A sporting goods retailer shares its sales data in real time with the manufacturer and its suppliers. Which SCM opportunity is mainly being used?",o:["Dependence on partners decreases","Internal know-how is better protected","Demand more predictable, less stock","Longer lead time, but better punctuality"],e:"Real-time data make demand plannable – all stages can work with smaller stocks. Protection of know-how and independence do not improve this way (those are rather risks)."},hu:{q:"Egy sportszer-kereskedő valós időben megosztja értékesítési adatait a gyártóval és annak beszállítóival. Az SCM melyik lehetőségét használja ki elsősorban?",o:["Csökken a partnerektől való függőség","A belső tudás jobban védett marad","Jobban előre jelezhető kereslet, kevesebb készlet","Hosszabb átfutási idő, ám cserébe jobb határidő-tartás"],e:"A valós idejű adatok tervezhetővé teszik a keresletet – minden szint kisebb készlettel dolgozhat. A tudásvédelem és a függetlenség ettől éppen nem javul (ezek inkább kockázatok)."}},{type:"mc",level:3,correctIndex:3,de:{q:"Ein steirischer Autozulieferer hält nun drei Wochen Pufferbestand und hat für jedes Kernbauteil einen zweiten Lieferanten. Die Störanfälligkeit sinkt, die Kosten steigen um 4 %. Welcher Begriff beschreibt diese Situation?",o:["Synergieeffekt durch Kooperation","Just-in-time-Prinzip","Greenwashing","Resilienz-Effizienz-Dilemma"],e:"Mehr Sicherheit (Puffer, zweite Quelle) kostet mehr Geld und Koordination – die Kette wird resilienter, aber weniger effizient. Just-in-time wäre das Gegenteil: kaum Bestand."},en:{q:"A Styrian automotive supplier now holds three weeks of buffer stock and has a second supplier for every core component. Vulnerability falls, costs rise by 4 %. Which term describes this situation?",o:["Synergy effect through cooperation","Just-in-time principle","Greenwashing","Resilience-efficiency dilemma"],e:"More security (buffers, a second source) costs more money and coordination – the chain becomes more resilient but less efficient. Just-in-time would be the opposite: hardly any stock."},hu:{q:"Egy stájer autóipari beszállító mostantól háromheti pufferkészletet tart, és minden fő alkatrészre van egy második beszállítója. A sérülékenység csökken, a költségek 4 %-kal nőnek. Melyik fogalom írja le ezt a helyzetet?",o:["Együttműködésből fakadó szinergiahatás","Just-in-time elv","Zöldre mosás (greenwashing)","Reziliencia–hatékonyság dilemma"],e:"A nagyobb biztonság (puffer, második forrás) több pénzbe és koordinációba kerül – a lánc ellenállóbb, de kevésbé hatékony lesz. A just-in-time ennek ellentéte: alig van készlet."}},{type:"text",level:2,de:{q:"Wie heißt die Zeitspanne für die Bearbeitung eines Auftrags bzw. für einen Prozess zwischen Unternehmen, die durch gutes SCM verkürzt werden soll?",a:["Durchlaufzeit","Durchlaufzeiten"],e:"Die Durchlaufzeit misst, wie lange ein Auftrag oder Prozess dauert. Gutes SCM verkürzt sie – das spart Zeit und erhöht die Termintreue."},en:{q:"What is the period of time needed to process an order or a process between companies called, which good SCM aims to shorten?",a:["lead time","throughput time","cycle time","processing time"],e:"Lead time measures how long an order or process takes. Good SCM shortens it – saving time and improving punctuality."},hu:{q:"Hogyan nevezzük egy megrendelés vagy egy vállalatok közötti folyamat feldolgozásához szükséges időtartamot, amelyet a jó SCM lerövidít?",a:["átfutási idő","átfutási időt"],e:"Az átfutási idő azt méri, mennyi ideig tart egy megrendelés vagy folyamat. A jó SCM lerövidíti – ez időt takarít meg, és javítja a határidő-tartást."}}],logistik:[{type:"tf",level:1,correct:!0,de:{q:"Beim Werkverkehr transportiert ein Unternehmen seine Güter mit eigenen Fahrzeugen und eigenem Personal.",e:"Richtig – es wird kein Spediteur oder Frachtführer beauftragt, z. B. wenn eine Bäckerei ihre Filialen mit eigenen Lieferwagen beliefert."},en:{q:"With own-account transport, a company transports its goods with its own vehicles and its own staff.",e:"True – no forwarder or carrier is hired, e.g. when a bakery supplies its branches with its own vans."},hu:{q:"Saját számlás fuvarozásnál a vállalat saját járműveivel és saját személyzetével szállítja az áruit.",e:"Igaz – nem bíznak meg szállítmányozót vagy fuvarozót, pl. amikor egy pékség saját kisteherautóival látja el a fióküzleteit."}},{type:"tf",level:2,correct:!1,de:{q:"Beim kombinierten Verkehr werden die Güter beim Wechsel des Verkehrsträgers aus ihrer Ladeeinheit ausgepackt und neu verladen.",e:"Falsch – beim kombinierten Verkehr bleiben die Güter in ihrer Ladeeinheit (Container, Sattelauflieger, Lkw); nur die Ladeeinheit wechselt den Verkehrsträger."},en:{q:"In combined transport, the goods are unpacked from their loading unit and reloaded whenever the mode of transport changes.",e:"False – in combined transport the goods stay in their loading unit (container, semi-trailer, truck); only the loading unit changes the mode of transport."},hu:{q:"Kombinált fuvarozásnál a közlekedési ág váltásakor az árut kipakolják a rakodási egységből, és újra berakodják.",e:"Hamis – kombinált fuvarozásnál az áru a rakodási egységben (konténer, félpótkocsi, kamion) marad; csak a rakodási egység vált közlekedési ágat."}},{type:"tf",level:2,correct:!0,de:{q:"Sowohl der Spediteur als auch der Frachtführer haben ein Pfandrecht am Transportgut.",e:"Richtig – beide können das Gut zurückbehalten, bis Speditionsprovision bzw. Fracht bezahlt ist. Das Selbsteintrittsrecht hat dagegen nur der Spediteur."},en:{q:"Both the freight forwarder and the carrier have a lien on the goods being transported.",e:"True – both can retain the goods until the forwarding commission or the freight charge is paid. The right of self-entry, however, belongs only to the forwarder."},hu:{q:"A szállítmányozónak és a fuvarozónak is zálogjoga van a szállított árun.",e:"Igaz – mindketten visszatarthatják az árut, amíg a szállítmányozói jutalékot, illetve a fuvardíjat ki nem fizetik. Az önbelépési jog viszont csak a szállítmányozót illeti meg."}},{type:"tf",level:3,correct:!1,de:{q:"Der CMR-Frachtbrief ist ein Traditionspapier: Wer ihn besitzt, kann über die Ware verfügen.",e:"Falsch – der CMR-Frachtbrief ist nur ein Nachweis, dass die Ware versendet wurde. Traditionspapiere (Wertpapiere) sind das See- und Flusskonnossement sowie das FBL."},en:{q:"The CMR consignment note is a document of title: whoever holds it can dispose of the goods.",e:"False – the CMR note only proves that the goods were dispatched. Documents of title (securities) are the ocean and inland bill of lading and the FBL."},hu:{q:"A CMR-fuvarlevél árut megtestesítő értékpapír: aki birtokolja, rendelkezhet az áru felett.",e:"Hamis – a CMR-fuvarlevél csak azt igazolja, hogy az árut feladták. Árut megtestesítő értékpapír a tengeri és a belvízi hajóraklevél (konnosszement), valamint az FBL."}},{type:"multi",level:2,correct:[0,1,2,5],de:{q:"Welche Dokumente zählen zu den Begleitpapieren? Wähle alle zutreffenden.",o:["Ursprungszeugnis","Packliste","Handelsrechnung","Seekonnossement","CMR-Frachtbrief","Warenverkehrsbescheinigung"],e:"Begleitpapiere begleiten die Fracht (Ursprungszeugnis, Warenverkehrsbescheinigung, Genehmigungen, Rechnungen, Packliste). Seekonnossement ist ein Traditionspapier, der CMR-Frachtbrief ein Frachtbrief."},en:{q:"Which documents are accompanying documents? Select all that apply.",o:["Certificate of origin","Packing list","Commercial invoice","Ocean bill of lading","CMR consignment note","Movement certificate"],e:"Accompanying documents travel with the freight (certificate of origin, movement certificate, permits, invoices, packing list). The ocean bill of lading is a document of title, the CMR note a consignment note."},hu:{q:"Mely okmányok tartoznak a kísérőokmányok közé? Jelöld az összes helyeset.",o:["Származási bizonyítvány","Csomaglista","Kereskedelmi számla","Tengeri hajóraklevél","CMR-fuvarlevél","Áruforgalmi bizonyítvány (EUR.1)"],e:"A kísérőokmányok a szállítmánnyal együtt utaznak (származási bizonyítvány, áruforgalmi bizonyítvány, engedélyek, számlák, csomaglista). A tengeri hajóraklevél árut megtestesítő értékpapír, a CMR pedig fuvarlevél."}},{type:"multi",level:3,correct:[0,1,2],de:{q:"Welche Transportformen gehören zum Huckepackverkehr? Wähle alle zutreffenden.",o:["Rollende Landstraße (RoLa)","Roll-on/Roll-off (RoRo)","Load-on/Load-off mit Sattelaufliegern","Umladen eines Überseecontainers vom Schiff auf die Bahn","Werkverkehr mit eigenem Lkw"],e:"Beim Huckepackverkehr reitet der Lkw oder sein Sattelauflieger auf Bahn oder Schiff mit. Das Umladen von Containern ist Behälterverkehr; Werkverkehr ist gar kein kombinierter Verkehr."},en:{q:"Which forms of transport belong to piggyback transport? Select all that apply.",o:["Rolling road (RoLa)","Roll-on/roll-off (RoRo)","Load-on/load-off with semi-trailers","Transferring an overseas container from ship to rail","Own-account transport with one's own truck"],e:"In piggyback transport the truck or its semi-trailer rides on a train or ship. Transferring containers is container transport; own-account transport is not combined transport at all."},hu:{q:"Mely szállítási formák tartoznak a ráterheléses (huckepack) fuvarozáshoz? Jelöld az összes helyeset.",o:["Gördülő országút (RoLa)","Roll-on/roll-off (RoRo)","Load-on/load-off félpótkocsikkal","Tengerentúli konténer átrakása hajóról vasútra","Saját számlás fuvarozás saját kamionnal"],e:"Ráterheléses fuvarozásnál a kamion vagy a félpótkocsija vonaton vagy hajón utazik. A konténerek átrakása konténeres fuvarozás; a saját számlás fuvarozás egyáltalán nem kombinált fuvarozás."}},{type:"match",level:1,de:{q:"Ordne jedem Transportmittel die Güter zu, für die es laut Lehrbuch besonders geeignet ist.",p:[["Lkw","Stückgüter, Just-in-time-Lieferungen"],["Bahn","Massengüter, Gefahrgut"],["Binnenschiff","Schwere, unverderbliche Güter"],["Seeschiff","Container, große Sendungen nach Übersee"],["Flugzeug","Leichte, verderbliche, wertvolle Güter"]],e:"Der Lkw ist flexibel (Haus-zu-Haus), die Bahn sicher mit großer Kapazität, das Binnenschiff günstig, aber langsam, das Seeschiff hat die größte Kapazität, das Flugzeug ist am schnellsten, aber am teuersten."},en:{q:"Match each means of transport with the goods it is particularly suited for according to the textbook.",p:[["Truck","General cargo, just-in-time deliveries"],["Rail","Bulk goods, dangerous goods"],["Inland vessel","Heavy, non-perishable goods"],["Ocean ship","Containers, large overseas shipments"],["Aircraft","Light, perishable, valuable goods"]],e:"The truck is flexible (door to door), rail is safe with large capacity, the inland vessel cheap but slow, the ocean ship has the largest capacity, the aircraft is fastest but most expensive."},hu:{q:"Párosítsd a szállítóeszközöket azokkal az árukkal, amelyekhez a tankönyv szerint különösen alkalmasak!",p:[["Kamion","Darabáru, just-in-time szállítások"],["Vasút","Tömegáru, veszélyes áru"],["Belvízi hajó","Nehéz, nem romlandó áru"],["Tengeri hajó","Konténerek, nagy tengerentúli szállítmányok"],["Repülőgép","Könnyű, romlandó, értékes áru"]],e:"A kamion rugalmas (háztól házig), a vasút biztonságos és nagy kapacitású, a belvízi hajó olcsó, de lassú, a tengeri hajó kapacitása a legnagyobb, a repülő a leggyorsabb, de a legdrágább."}},{type:"match",level:2,de:{q:"Ordne jedes Transportdokument dem passenden Verkehrsträger zu.",p:[["CMR-Frachtbrief","Straße"],["CIM-Frachtbrief","Bahn"],["Air Waybill","Luft"],["Seekonnossement (Bill of Lading)","Seeschiff"],["FIATA Multimodal (FBL)","Kombinierter Verkehr"]],e:"Frachtbriefe gibt es für Straße (CMR), Bahn (CIM) und Luft (Air Waybill). Traditionspapiere gibt es für die Schifffahrt (Konnossement) und den kombinierten Verkehr (FBL)."},en:{q:"Match each transport document with the appropriate mode of transport.",p:[["CMR consignment note","Road"],["CIM consignment note","Rail"],["Air waybill","Air"],["Ocean bill of lading","Sea"],["FIATA multimodal bill of lading (FBL)","Combined transport"]],e:"Consignment notes exist for road (CMR), rail (CIM) and air (air waybill). Documents of title exist for shipping (bill of lading) and combined transport (FBL)."},hu:{q:"Párosítsd a szállítási okmányokat a megfelelő közlekedési ággal!",p:[["CMR-fuvarlevél","Közút"],["CIM-fuvarlevél","Vasút"],["Air Waybill (légi fuvarlevél)","Légi közlekedés"],["Tengeri hajóraklevél (Bill of Lading)","Tengeri hajózás"],["FIATA multimodális (FBL)","Kombinált fuvarozás"]],e:"Fuvarlevél létezik közúton (CMR), vasúton (CIM) és légi úton (Air Waybill). Árut megtestesítő értékpapír a hajózásban (konnosszement) és a kombinált fuvarozásban (FBL) van."}},{type:"mc",level:2,correctIndex:0,de:{q:"Ein Stahlwerk in Linz will 2.000 Tonnen Stahlblech-Rollen nach Rotterdam schicken. Die Lieferung ist nicht eilig, es soll möglichst günstig und umweltfreundlich sein. Welches Transportmittel passt am besten?",o:["Binnenschiff","Flugzeug","Lkw","Kurier- und Expressdienst"],e:"Schwere, unverderbliche Massengüter ohne Zeitdruck sind typisch fürs Binnenschiff (Donau, Main, Rhein): günstig und umweltfreundlich, aber langsam. Flugzeug und Kurier wären teuer, der Lkw für 2.000 t ineffizient."},en:{q:"A steel mill in Linz wants to ship 2,000 tonnes of steel coils to Rotterdam. The delivery is not urgent and should be as cheap and environmentally friendly as possible. Which means of transport fits best?",o:["Inland vessel","Aircraft","Truck","Courier and express service"],e:"Heavy, non-perishable bulk goods without time pressure are typical for inland shipping (Danube, Main, Rhine): cheap and eco-friendly, but slow. Air and courier would be expensive, trucks inefficient for 2,000 t."},hu:{q:"Egy linzi acélmű 2000 tonna acéllemez-tekercset akar Rotterdamba küldeni. A szállítás nem sürgős, legyen a lehető legolcsóbb és legkörnyezetkímélőbb. Melyik szállítóeszköz a legmegfelelőbb?",o:["Belvízi hajó","Repülőgép","Kamion","Futár- és expresszszolgálat"],e:"A nehéz, nem romlandó tömegáru időnyomás nélkül tipikusan belvízi hajóra való (Duna, Majna, Rajna): olcsó és környezetkímélő, de lassú. A repülő és a futár drága lenne, a kamion 2000 tonnához nem hatékony."}},{type:"mc",level:3,correctIndex:1,de:{q:"Ein Möbelhersteller beauftragt einen Spediteur mit einem Transport nach Mailand. Der Spediteur beauftragt einen Frachtführer, der die Fahrt durchführt. Welcher Vertrag besteht zwischen Möbelhersteller und Frachtführer?",o:["Ein Frachtvertrag","Kein direkter Vertrag","Ein Speditionsvertrag","Ein Kaufvertrag"],e:"Der Speditionsvertrag besteht zwischen Möbelhersteller und Spediteur, der Frachtvertrag zwischen Spediteur und Frachtführer. Der Spediteur handelt im eigenen Namen – zwischen Hersteller und Frachtführer gibt es keinen direkten Vertrag."},en:{q:"A furniture manufacturer hires a freight forwarder for a transport to Milan. The forwarder hires a carrier who carries out the trip. Which contract exists between the furniture manufacturer and the carrier?",o:["A contract of carriage","No direct contract","A forwarding contract","A contract of sale"],e:"The forwarding contract is between the manufacturer and the forwarder, the contract of carriage between the forwarder and the carrier. The forwarder acts in its own name – there is no direct contract between manufacturer and carrier."},hu:{q:"Egy bútorgyártó egy szállítmányozót bíz meg egy milánói szállítással. A szállítmányozó egy fuvarozót bíz meg, aki elvégzi a fuvart. Milyen szerződés áll fenn a bútorgyártó és a fuvarozó között?",o:["Fuvarozási szerződés","Nincs közvetlen szerződés","Szállítmányozási szerződés","Adásvételi szerződés"],e:"A szállítmányozási szerződés a bútorgyártó és a szállítmányozó, a fuvarozási szerződés a szállítmányozó és a fuvarozó között jön létre. A szállítmányozó saját nevében jár el – a gyártó és a fuvarozó között nincs közvetlen szerződés."}},{type:"text",level:1,de:{q:"Wie heißt das Traditionspapier im Seeverkehr, das das Recht an der Ware verbrieft?",a:["Seekonnossement","Konnossement","Bill of Lading","B/L"],e:"Das Seekonnossement (Bill of Lading) ist ein Wertpapier: Wer es besitzt, kann über die Ware verfügen. Frachtbriefe wie CMR oder CIM sind dagegen nur Versandnachweise."},en:{q:"What is the document of title in sea transport called, which embodies the right to the goods?",a:["bill of lading","ocean bill of lading","B/L","BL"],e:"The bill of lading is a security: whoever holds it can dispose of the goods. Consignment notes such as CMR or CIM are only proof of dispatch."},hu:{q:"Hogy hívják a tengeri szállítás árut megtestesítő értékpapírját, amely az árura vonatkozó jogot testesíti meg?",a:["hajóraklevél","tengeri hajóraklevél","konnosszement","Bill of Lading","B/L"],e:"A tengeri hajóraklevél (konnosszement, Bill of Lading) értékpapír: aki birtokolja, rendelkezhet az áru felett. A CMR- vagy CIM-fuvarlevél csak a feladást igazolja."}}],"der-handel":[{type:"tf",level:1,correct:!0,de:{q:"Außenhandel ist der Handel zwischen verschiedenen Staaten, Binnenhandel der Handel innerhalb eines Staates.",e:"Richtig – die Einteilung erfolgt nach dem Wirtschaftsraum. Die Einteilung in Einzel- und Großhandel richtet sich dagegen nach der Art der Abnehmer."},en:{q:"Foreign trade is trade between different countries, domestic trade is trade within one country.",e:"True – this classification is based on the economic area. The split into retail and wholesale, by contrast, depends on the type of buyer."},hu:{q:"A külkereskedelem különböző államok közötti, a belkereskedelem egy államon belüli kereskedelem.",e:"Igaz – ez a felosztás a gazdasági térség szerint történik. A kis- és nagykereskedelemre való felosztás viszont a vevők típusától függ."}},{type:"tf",level:2,correct:!1,de:{q:"Ein Pop-up-Store ist ein Geschäft ohne festen Standort, das wie ein Marktstand von Ort zu Ort zieht.",e:"Falsch – ein Pop-up-Store wird vorübergehend in einem leerstehenden Geschäftslokal betrieben, also stationär. Ohne festen Standort ist der ambulante Handel (z. B. Wochenmarkt)."},en:{q:"A pop-up store is a shop without a fixed location that moves from place to place like a market stall.",e:"False – a pop-up store is run temporarily in an empty shop, i.e. it is stationary. Trade without a fixed location is itinerant trade (e.g. a weekly market)."},hu:{q:"A pop-up store állandó helyszín nélküli üzlet, amely piaci standként vándorol helyről helyre.",e:"Hamis – a pop-up store ideiglenesen egy üresen álló üzlethelyiségben működik, tehát helyhez kötött. Állandó helyszín nélküli a mozgó kereskedelem (pl. heti piac)."}},{type:"tf",level:2,correct:!0,de:{q:"Beim Zustellgroßhandel bestellen die Kund:innen z. B. nach Muster oder Katalog, und der Großhändler liefert die Ware zu ihnen.",e:"Richtig – im Gegensatz zum Abholgroßhandel (z. B. Cash-and-carry bei Metro), wo die Kund:innen die Ware selbst abholen."},en:{q:"In delivery wholesale, customers order e.g. from samples or a catalogue, and the wholesaler delivers the goods to them.",e:"True – unlike collection wholesale (e.g. cash-and-carry at Metro), where customers collect the goods themselves."},hu:{q:"Kiszállító nagykereskedelemnél a vevők pl. minta vagy katalógus alapján rendelnek, és a nagykereskedő kiszállítja nekik az árut.",e:"Igaz – szemben az átvevő (elviteles) nagykereskedelemmel (pl. cash & carry a Metróban), ahol a vevők maguk viszik el az árut."}},{type:"tf",level:3,correct:!1,de:{q:"Wer sich einer freiwilligen Handelskette wie SPAR anschließt, verliert seine rechtliche Selbstständigkeit und wird angestellter Filialleiter.",e:"Falsch – bei einer freiwilligen Handelskette bleiben die Händler:innen selbstständig; sie treten nur unter gemeinsamer Marke auf und erledigen bestimmte Aufgaben gemeinsam. Kooperation heißt freiwillige, vertragliche Zusammenarbeit."},en:{q:"Anyone who joins a voluntary chain such as SPAR loses their legal independence and becomes an employed branch manager.",e:"False – in a voluntary chain the retailers remain independent; they only use a common brand and perform certain tasks together. Cooperation means voluntary, contractual collaboration."},hu:{q:"Aki csatlakozik egy önkéntes kereskedelmi lánchoz, például a SPAR-hoz, elveszíti jogi önállóságát, és alkalmazott üzletvezető lesz.",e:"Hamis – önkéntes kereskedelmi láncban a kereskedők önállóak maradnak; csak közös márkanév alatt lépnek fel, és bizonyos feladatokat közösen végeznek. A kooperáció önkéntes, szerződéses együttműködés."}},{type:"multi",level:1,correct:[0,1,4],de:{q:"Welche Betriebsformen gehören zum stationären Einzelhandel (fester Standort)? Wähle alle zutreffenden.",o:["Diskonter","Einkaufszentrum","Teleshopping","Wochenmarktstand","Fachgeschäft","Onlineshop"],e:"Diskonter, Einkaufszentrum und Fachgeschäft haben einen festen Standort. Teleshopping und Onlineshop sind Versandhandel (Distanzhandel), der Wochenmarkt ist ambulanter Handel."},en:{q:"Which store formats belong to stationary retail (fixed location)? Select all that apply.",o:["Discounter","Shopping centre","Teleshopping","Weekly market stall","Specialist shop","Online shop"],e:"Discounters, shopping centres and specialist shops have a fixed location. Teleshopping and online shops are distance selling, the weekly market is itinerant trade."},hu:{q:"Mely üzletformák tartoznak a helyhez kötött (bolti) kiskereskedelemhez? Jelöld az összes helyeset.",o:["Diszkont","Bevásárlóközpont","Teleshopping","Heti piaci stand","Szaküzlet","Webáruház"],e:"A diszkont, a bevásárlóközpont és a szaküzlet állandó helyen működik. A teleshopping és a webáruház csomagküldő (távértékesítő) kereskedelem, a heti piac mozgó kereskedelem."}},{type:"multi",level:3,correct:[0,1,2],de:{q:"Welche Aussagen zu Kooperationen im Handel treffen zu? Wähle alle zutreffenden.",o:["Sie beruhen auf freiwilliger, vertraglicher Zusammenarbeit.","Ihr Ziel ist es, wettbewerbsfähig zu bleiben.","In einer Handelsgenossenschaft betreiben Händler gemeinsam Einkauf und Logistik.","Franchisenehmer:innen sind Angestellte des Franchisegebers.","Bei einer Kooperation verschmelzen die Unternehmen zu einem einzigen."],e:"Kooperationen sind freiwillig und vertraglich; die Partner bleiben rechtlich selbstständig. Auch Franchisenehmer:innen sind selbstständige Unternehmer:innen, die das Konzept des Franchisegebers nutzen."},en:{q:"Which statements about cooperation in trade are correct? Select all that apply.",o:["It is based on voluntary, contractual collaboration.","Its aim is to stay competitive.","In a retail cooperative, traders run purchasing and logistics together.","Franchisees are employees of the franchisor.","In a cooperation the companies merge into a single one."],e:"Cooperation is voluntary and contractual; the partners remain legally independent. Franchisees, too, are independent entrepreneurs who use the franchisor's concept."},hu:{q:"Mely állítások igazak a kereskedelmi együttműködésekre (kooperációkra)? Jelöld az összes helyeset.",o:["Önkéntes, szerződéses együttműködésen alapulnak.","Céljuk a versenyképesség megőrzése.","A kereskedelmi szövetkezetben a kereskedők közösen végzik a beszerzést és a logisztikát.","A franchise-átvevők a franchise-átadó alkalmazottai.","Kooperáció esetén a vállalatok egyetlen vállalattá olvadnak össze."],e:"A kooperáció önkéntes és szerződéses; a partnerek jogilag önállóak maradnak. A franchise-átvevők is önálló vállalkozók, akik a franchise-átadó koncepcióját használják."}},{type:"match",level:2,de:{q:"Ordne jede Maßnahme dem passenden Erfolgsfaktor im Handel zu.",p:[["Kundenkarte, Newsletter, Kundenclub","Kundenbindung"],["Licht, Musik, Regalplatzierung","Merchandising"],["Laden, Onlineshop und Social Media","Multi-Channel-Lösung"],["Miete, Verkehrslage, Kundennähe prüfen","Idealer Standort"]],e:"Kundenbindung hält Kund:innen, Merchandising gestaltet den ganzheitlichen Auftritt im Geschäft, Multi-Channel nutzt mehrere Absatzkanäle, und der Standort entscheidet über Erreichbarkeit und Kosten."},en:{q:"Match each measure with the appropriate success factor in retail.",p:[["Loyalty card, newsletter, customer club","Customer loyalty"],["Lighting, music, shelf placement","Merchandising"],["Shop, online shop and social media","Multi-channel solution"],["Checking rent, traffic, customer proximity","Ideal location"]],e:"Customer loyalty keeps customers, merchandising shapes the overall in-store experience, multi-channel uses several sales channels, and the location determines accessibility and costs."},hu:{q:"Párosítsd az intézkedéseket a kereskedelem megfelelő sikertényezőjével!",p:[["Törzsvásárlói kártya, hírlevél, vásárlói klub","Vevőmegtartás"],["Világítás, zene, polcelhelyezés","Merchandising"],["Bolt, webáruház és közösségi média","Többcsatornás (multi-channel) megoldás"],["Bérleti díj, közlekedés, vevőközelség vizsgálata","Ideális telephely"]],e:"A vevőmegtartás megtartja a vásárlókat, a merchandising az üzlet egységes megjelenését alakítja, a multi-channel több értékesítési csatornát használ, a telephely pedig az elérhetőséget és a költségeket határozza meg."}},{type:"mc",level:2,correctIndex:2,de:{q:"Ein Sportartikelhersteller verkauft in Parndorf in einem von vielen Markengeschäften an einem Standort Vorjahresware deutlich günstiger. Welche Betriebsform liegt vor?",o:["Diskonter","Pop-up-Store","Factory-Outlet-Center","Fachmarkt mit Selbstbedienung"],e:"Im Factory-Outlet-Center verkaufen Hersteller Markenartikel günstiger, oft Restposten oder Vorjahresware. Ein Diskonter verkauft ein schmales Sortiment billig, ein Fachmarkt eine Branche auf großer Fläche."},en:{q:"A sporting goods manufacturer sells last year's products at clearly lower prices in one of many brand shops at a single location in Parndorf. Which store format is this?",o:["Discounter","Pop-up store","Factory outlet centre","Self-service specialist superstore"],e:"In a factory outlet centre, manufacturers sell branded goods more cheaply, often leftovers or last season's products. A discounter sells a narrow range cheaply, a specialist superstore one sector on a large floor space."},hu:{q:"Egy sportszergyártó Parndorfban, sok márkabolt egyikében az előző évi kollekciót jóval olcsóbban árulja. Milyen üzletformáról van szó?",o:["Diszkont","Pop-up store","Factory outlet center (gyári outlet)","Nagy alapterületű, önkiszolgáló szakáruház"],e:"A factory outlet centerben a gyártók olcsóbban adják márkás termékeiket, gyakran maradékkészletet vagy előző évi árut. A diszkont szűk választékot kínál olcsón, a szakáruház egy ágazatot nagy alapterületen."}},{type:"mc",level:3,correctIndex:0,de:{q:"Welcher der folgenden Betriebe ist ein Handelsbetrieb im Sinne des Lehrbuchs?",o:["Weinhändler stellt Weine vieler Winzer zu Paketen zusammen","Tischlerei fertigt Einbauküchen nach Maß für Privatkund:innen","Brauerei braut Bier und verkauft es an Wirte","Bäckerei bäckt Brot und verkauft es im Laden"],e:"Ein Handelsbetrieb kauft Produkte, stellt ein Sortiment zusammen und verkauft sie OHNE wesentliche Bearbeitung weiter. Tischlerei, Brauerei und Bäckerei stellen ihre Produkte selbst her – sie sind Produktionsbetriebe, auch wenn sie direkt verkaufen."},en:{q:"Which of the following businesses is a trading business as defined in the textbook?",o:["Wine merchant packs wines from many winemakers","Joinery builds made-to-measure fitted kitchens for private clients","Brewery brews beer and sells it to pubs","Bakery bakes bread and sells it in its shop"],e:"A trading business buys products, puts together a range and resells them WITHOUT substantial processing. The joinery, brewery and bakery make their products themselves – they are manufacturers, even if they sell directly."},hu:{q:"Az alábbiak közül melyik kereskedelmi vállalat a tankönyv értelmében?",o:["Borkereskedő sok borász borából állít össze csomagokat","Asztalosműhely méretre gyárt beépített konyhákat magánügyfeleknek","Sörfőzde sört főz, és kocsmáknak adja el","Pékség kenyeret süt, és a boltjában árulja"],e:"A kereskedelmi vállalat termékeket vásárol, választékot állít össze, és lényeges feldolgozás NÉLKÜL adja tovább. Az asztalos, a sörfőzde és a pékség maga állítja elő a termékeit – termelő vállalatok, még ha közvetlenül értékesítenek is."}},{type:"text",level:1,de:{q:"Wie nennt man den Einzelhandel ohne festen Standort, z. B. Markthandel oder Direktvertrieb bei Home-Partys?",a:["ambulanter Handel","Ambulanter Handel","halbstationärer Handel","ambulanter (halbstationärer) Handel","ambulant"],e:"Der ambulante (halbstationäre) Handel hat keinen festen Standort: Straßen- und Markthandel sowie Direktvertrieb. Stationärer Handel findet in einem festen Geschäft statt."},en:{q:"What is retail without a fixed location called, e.g. market trading or direct selling at home parties?",a:["itinerant trade","itinerant retail","mobile retail","ambulant trade","semi-stationary trade"],e:"Itinerant (semi-stationary) trade has no fixed location: street and market trading as well as direct selling. Stationary retail takes place in a fixed shop."},hu:{q:"Hogyan nevezzük az állandó helyszín nélküli kiskereskedelmet, pl. a piaci árusítást vagy a házibulikon történő közvetlen értékesítést?",a:["mozgó kereskedelem","vándorkereskedelem","ambuláns kereskedelem","mozgóárusítás"],e:"A mozgó (félig helyhez kötött) kereskedelemnek nincs állandó helye: utcai és piaci árusítás, valamint közvetlen értékesítés. A helyhez kötött kereskedelem állandó üzletben zajlik."}}],"businessplan-2jg":[{type:"tf",level:1,correct:!0,de:{q:"Lebensläufe der Gründer:innen und Angebote von Lieferanten gehören in den Anhang des Businessplans.",e:"Richtig – Detailunterlagen kommen in den Anhang, damit der Hauptteil übersichtlich bleibt. Ergänzt wird der Plan außerdem durch Deckblatt, Inhalts- und Quellenverzeichnis."},en:{q:"The founders' CVs and supplier quotations belong in the appendix of the business plan.",e:"True – detailed documents go in the appendix so that the main part stays clear. The plan is also completed by a cover page, table of contents and list of sources."},hu:{q:"Az alapítók önéletrajzai és a beszállítói ajánlatok az üzleti terv mellékletébe tartoznak.",e:"Igaz – a részletes dokumentumok a mellékletbe kerülnek, hogy a fő rész áttekinthető maradjon. A tervet ezenkívül fedlap, tartalomjegyzék és forrásjegyzék egészíti ki."}},{type:"tf",level:2,correct:!1,de:{q:"Das Ziel „Wir wollen bekannter werden.“ ist SMART formuliert.",e:"Falsch – es ist weder spezifisch noch messbar noch terminiert. SMART wäre z. B.: „Bis 31. Dezember gewinnen wir 1.000 Instagram-Follower:innen.“"},en:{q:"The goal 'We want to become better known.' is formulated SMART.",e:"False – it is neither specific nor measurable nor time-bound. SMART would be, for example: 'By 31 December we will gain 1,000 Instagram followers.'"},hu:{q:"A „Szeretnénk ismertebbek lenni.” cél SMART módon van megfogalmazva.",e:"Hamis – nem konkrét, nem mérhető és nincs határideje. SMART lenne pl.: „December 31-ig 1000 Instagram-követőt szerzünk.”"}},{type:"tf",level:3,correct:!1,de:{q:"Ein Gebrauchsmuster bietet einen stärkeren Schutz als ein Patent, ist dafür aber langsamer zu erlangen.",e:"Falsch – genau umgekehrt: Das Gebrauchsmuster ist schneller zu erlangen, bietet aber einen schwächeren Schutz als das Patent. Beide sind registrierungs- und kostenpflichtig."},en:{q:"A utility model offers stronger protection than a patent, but takes longer to obtain.",e:"False – it is the other way round: a utility model is quicker to obtain but offers weaker protection than a patent. Both must be registered and cost fees."},hu:{q:"A használati minta erősebb védelmet nyújt, mint a szabadalom, viszont lassabban lehet megszerezni.",e:"Hamis – éppen fordítva: a használati mintát gyorsabban lehet megszerezni, de gyengébb védelmet nyújt, mint a szabadalom. Mindkettőt be kell jegyeztetni, és díjköteles."}},{type:"tf",level:1,correct:!0,de:{q:"Die Finanzplanung im Businessplan sollte mindestens die ersten drei Jahre umfassen.",e:"Richtig – die Finanzplanung ist das Herzstück: Kapitalbedarf, Finanzierung (Eigen- und Fremdkapital) und ein Liquiditätsplan für mindestens die ersten 3 Jahre."},en:{q:"The financial plan in a business plan should cover at least the first three years.",e:"True – the financial plan is the core: capital requirements, financing (equity and debt) and a liquidity plan for at least the first 3 years."},hu:{q:"Az üzleti terv pénzügyi tervének legalább az első három évet le kell fednie.",e:"Igaz – a pénzügyi terv az üzleti terv lelke: tőkeszükséglet, finanszírozás (saját és idegen tőke) és likviditási terv legalább az első 3 évre."}},{type:"multi",level:2,correct:[0,1,2,5],de:{q:"Welche Standortfaktoren sind absatzorientiert? Wähle alle zutreffenden.",o:["Kundennähe","Wettbewerb in der Umgebung","Verkehrslage","Nähe zu Lieferanten","Förderungen","Image des Standorts"],e:"Absatzorientierte Faktoren betreffen den Verkauf: Kundennähe, Wettbewerb, Verkehrslage, Image. Nähe zu Lieferanten ist beschaffungsseitig, Förderungen sind produktionsbezogen."},en:{q:"Which location factors are sales-oriented? Select all that apply.",o:["Proximity to customers","Competition in the area","Traffic situation","Proximity to suppliers","Subsidies","Image of the location"],e:"Sales-oriented factors concern selling: proximity to customers, competition, traffic situation, image. Proximity to suppliers is procurement-related, subsidies are production-related."},hu:{q:"Mely telephelyi tényezők értékesítésorientáltak? Jelöld az összes helyeset.",o:["Vevőközelség","Verseny a környéken","Közlekedési helyzet","Beszállítók közelsége","Támogatások","A telephely imázsa"],e:"Az értékesítésorientált tényezők az eladást érintik: vevőközelség, verseny, közlekedési helyzet, imázs. A beszállítók közelsége beszerzési, a támogatások termeléssel kapcsolatos tényezők."}},{type:"multi",level:3,correct:[0,1,2,5],de:{q:"Welche Schutzrechte sind registrierungs- und kostenpflichtig? Wähle alle zutreffenden.",o:["Patent","Marke","Design (Muster)","Urheberrecht","Betriebsgeheimnis","Gebrauchsmuster"],e:"Patent, Gebrauchsmuster, Marke, Design und Herkunftsangaben müssen angemeldet werden und kosten Gebühren. Urheberrecht entsteht automatisch mit dem Werk, Betriebsgeheimnisse schützt man durch Geheimhaltung – beides kostenfrei."},en:{q:"Which intellectual property rights must be registered and cost fees? Select all that apply.",o:["Patent","Trademark","Design","Copyright","Trade secret","Utility model"],e:"Patents, utility models, trademarks, designs and geographical indications must be registered and cost fees. Copyright arises automatically with the work, trade secrets are protected by keeping them secret – both free of charge."},hu:{q:"Mely oltalmi jogokat kell bejegyeztetni, és díjkötelesek? Jelöld az összes helyeset.",o:["Szabadalom","Védjegy","Formatervezési minta","Szerzői jog","Üzleti titok","Használati minta"],e:"A szabadalmat, használati mintát, védjegyet, formatervezési mintát és földrajzi árujelzőt be kell jelenteni, és díjat kell fizetni. A szerzői jog a művel automatikusan keletkezik, az üzleti titkot titoktartással védik – mindkettő ingyenes."}},{type:"order",level:2,de:{q:"Bringe die Schritte zur Erstellung eines Umsetzungsfahrplans in die richtige Reihenfolge.",o:["Arbeitspakete schnüren","Meilensteine festlegen","Kritischen Pfad beachten","Kontrolle (Soll-Ist-Vergleich)"],e:"Zuerst zusammengehörende Tätigkeiten bündeln, dann prüfbare Zwischenziele setzen, die Aktivitäten ohne Zeitpuffer erkennen und laufend Soll und Ist vergleichen, um gegenzusteuern."},en:{q:"Put the steps for creating an implementation roadmap in the correct order.",o:["Define work packages","Set milestones","Watch the critical path","Control (target/actual comparison)"],e:"First bundle related activities, then set verifiable interim goals, identify the activities without time buffer and keep comparing target and actual to take corrective action."},hu:{q:"Állítsd helyes sorrendbe a megvalósítási ütemterv elkészítésének lépéseit!",o:["Munkacsomagok kialakítása","Mérföldkövek kijelölése","A kritikus út figyelembevétele","Ellenőrzés (terv–tény összehasonlítás)"],e:"Először összevonjuk az összetartozó tevékenységeket, aztán ellenőrizhető részcélokat tűzünk ki, azonosítjuk az időtartalék nélküli tevékenységeket, végül folyamatosan összevetjük a tervet a ténnyel, és szükség esetén beavatkozunk."}},{type:"match",level:1,de:{q:"Ordne jedes Ziel aus Loopys Businessplan der richtigen Zielart zu.",p:[["Nachhaltigkeit dauerhaft im Unternehmen verankern","Langfristig (strategisch)"],["In drei Jahren die Gewinnzone erreichen","Mittelfristig (taktisch)"],["Dieses Quartal auf recycelbare Verpackung umstellen","Kurzfristig (operativ)"]],e:"Langfristige Ziele reichen über 5 Jahre, mittelfristige 1–5 Jahre, kurzfristige unter 1 Jahr. Gewinnzone heißt: Erlöse sind höher als die Gesamtkosten."},en:{q:"Match each goal from Loopy's business plan with the right type of goal.",p:[["Permanently anchoring sustainability in the company","Long-term (strategic)"],["Reaching the profit zone in three years","Medium-term (tactical)"],["Switching to recyclable packaging this quarter","Short-term (operational)"]],e:"Long-term goals extend beyond 5 years, medium-term 1–5 years, short-term under 1 year. Profit zone means revenue is higher than total costs."},hu:{q:"Párosítsd Loopy üzleti tervének céljait a megfelelő céltípussal!",p:[["A fenntarthatóság tartós beépítése a vállalatba","Hosszú távú (stratégiai)"],["Három év alatt elérni a nyereséges működést","Középtávú (taktikai)"],["Ebben a negyedévben áttérni az újrahasznosítható csomagolásra","Rövid távú (operatív)"]],e:"A hosszú távú célok 5 évnél hosszabbak, a középtávúak 1–5 évesek, a rövid távúak 1 évnél rövidebbek. Nyereséges működés: a bevétel meghaladja az összköltséget."}},{type:"mc",level:2,correctIndex:0,de:{q:"Ein Softwareunternehmen gründet seinen Standort in Graz, weil dort viele gut ausgebildete Uni-Absolvent:innen leben. Welche Art von Standortfaktor ist ausschlaggebend?",o:["Beschaffungsseitig","Produktionsbezogen","Absatzorientiert","Rechtlich-steuerlich"],e:"Arbeitskräfte zählen laut Lehrbuch zu den beschaffungsseitigen Standortfaktoren (wie Infrastruktur, Nähe zu Lieferanten, Mieten). Absatzorientiert wären z. B. Kundennähe oder Verkehrslage."},en:{q:"A software company sets up in Graz because many well-trained university graduates live there. Which type of location factor is decisive?",o:["Procurement-related","Production-related","Sales-oriented","Legal and tax-related"],e:"According to the textbook, labour is a procurement-related location factor (like infrastructure, proximity to suppliers, rents). Sales-oriented would be e.g. proximity to customers or traffic situation."},hu:{q:"Egy szoftvercég Grazban telepszik le, mert ott sok jól képzett egyetemi végzős él. Melyik telephelyi tényező a döntő?",o:["Beszerzési oldali","Termeléssel kapcsolatos","Értékesítésorientált","Jogi-adózási"],e:"A munkaerő a tankönyv szerint beszerzési oldali telephelyi tényező (mint az infrastruktúra, a beszállítók közelsége, a bérleti díjak). Értékesítésorientált lenne pl. a vevőközelség vagy a közlekedési helyzet."}},{type:"mc",level:3,correctIndex:3,de:{q:"Scoring-Methode: Kundennähe (60 %) und Miete (40 %). Standort A erhält 2 und 5 Punkte, Standort B 5 und 1 Punkt. Welcher Standort ist zu wählen?",o:["A, ungewichtet 7 zu 6 Punkten","A, gewichtet 3,4 zu 3,2","Gleichstand – weitere Faktoren nötig","B, gewichtet 3,4 zu 3,2"],e:"A: 2 · 0,6 + 5 · 0,4 = 1,2 + 2,0 = 3,2. B: 5 · 0,6 + 1 · 0,4 = 3,0 + 0,4 = 3,4. Entscheidend ist die gewichtete Summe – B gewinnt, obwohl A ungewichtet mehr Punkte hat."},en:{q:"Scoring method: proximity to customers (60 %) and rent (40 %). Location A gets 2 and 5 points, location B 5 and 1 point. Which location should be chosen?",o:["A, unweighted 7 to 6 points","A, weighted 3.4 to 3.2","A tie – more factors needed","B, weighted 3.4 to 3.2"],e:"A: 2 · 0.6 + 5 · 0.4 = 1.2 + 2.0 = 3.2. B: 5 · 0.6 + 1 · 0.4 = 3.0 + 0.4 = 3.4. The weighted total decides – B wins although A has more unweighted points."},hu:{q:"Pontozásos módszer: vevőközelség (60 %) és bérleti díj (40 %). Az A telephely 2 és 5 pontot kap, a B 5 és 1 pontot. Melyik telephelyet kell választani?",o:["A-t, súlyozatlanul 7:6 pont","A-t, súlyozva 3,4:3,2","Döntetlen – további tényezők kellenek","B-t, súlyozva 3,4:3,2"],e:"A: 2 · 0,6 + 5 · 0,4 = 1,2 + 2,0 = 3,2. B: 5 · 0,6 + 1 · 0,4 = 3,0 + 0,4 = 3,4. A súlyozott összeg dönt – B nyer, bár A-nak súlyozatlanul több pontja van."}},{type:"number",level:2,value:48e4,tol:.5,unit:{de:"€",en:"€",hu:"€"},de:{q:"Eine Gründerin plant einen Kaffee-Lieferdienst in einer Kleinstadt. 2.500 mögliche Kund:innen bestellen durchschnittlich 2-mal pro Monat, eine Bestellung kostet 8 €. Wie hoch ist das monetäre Marktpotenzial pro Jahr?",e:"Mengenmäßig: 2.500 · 2 · 12 = 60.000 Bestellungen pro Jahr. Monetär: 60.000 · 8 € = 480.000 €. Das ist die theoretisch mögliche Obergrenze – der eigene Umsatz wird kleiner sein."},en:{q:"A founder plans a coffee delivery service in a small town. 2,500 potential customers order on average twice a month, one order costs €8. What is the monetary market potential per year?",e:"In units: 2,500 · 2 · 12 = 60,000 orders per year. In money: 60,000 · €8 = €480,000. This is the theoretical upper limit – the company's own revenue will be smaller."},hu:{q:"Egy alapító kávékiszállító szolgáltatást tervez egy kisvárosban. 2500 lehetséges vevő átlagosan havonta kétszer rendel, egy rendelés 8 €. Mekkora az éves piaci potenciál pénzben kifejezve?",e:"Mennyiségben: 2500 · 2 · 12 = 60 000 rendelés évente. Pénzben: 60 000 · 8 € = 480 000 €. Ez az elméleti felső határ – a saját árbevétel ennél kisebb lesz."}}]},o=e(t,a,n,r,s,i);export{o as default};
